      if (rem > 0.005) {
        const openAge = Math.max(0, Math.round((refMs - Date.parse('2024-01-01T00:00:00Z')) / 86400000));
        if (openAge > 60) b60 += rem;
        else if (openAge > 30) b31_60 += rem;
        else bCur += rem;
      }
