  const DIESEL_PRICE_MIN_BULK_L = 100;
  // asOf (optional, never later than today): the price that was the latest one on that day, for a ticket dated then.
  function _latestBulkDieselPrice(buys, groupBuys, asOf) {
    const todayIso = todayISO();
    const today = (asOf && String(asOf).slice(0, 10) < todayIso) ? String(asOf).slice(0, 10) : todayIso;
    const clean = list => (list || [])
      .filter(b => b && b.litres >= DIESEL_PRICE_MIN_BULK_L && b.amountUsd > 0 && b.date && String(b.date) <= today)
      .map(b => ({ d: String(b.date), l: Number(b.litres), u: Number(b.amountUsd) }))
      .sort((a, b) => (a.d < b.d ? -1 : (a.d > b.d ? 1 : 0)));
    const bulk = clean(buys);
    let groupBulk = null;
    let end = bulk.length;
    while (end > 0) {
      const date = bulk[end - 1].d;
      let start = end;
      while (start > 0 && bulk[start - 1].d === date) start--;
      let prev = [];
      for (let i = Math.max(0, start - 10); i < start; i++) prev.push(bulk[i].u / bulk[i].l);
      if (prev.length < 3 && groupBuys) {
        // A company with too little history of its own is checked against the group's deliveries before that day.
        if (!groupBulk) groupBulk = clean(groupBuys);
        prev = groupBulk.filter(g => g.d < date).slice(-10).map(g => g.u / g.l);
      }
      prev.sort((a, b) => a - b);
      const mid = prev.length >> 1;
      const ref = prev.length >= 3 ? (prev.length % 2 ? prev[mid] : (prev[mid - 1] + prev[mid]) / 2) : 0;
      let l = 0, usd = 0;
      for (let i = start; i < end; i++) {
        const p = bulk[i].u / bulk[i].l;
        if (!(ref > 0) || (p >= ref * 0.4 && p <= ref * 2.5)) { l += bulk[i].l; usd += bulk[i].u; }
      }
      if (l > 0) return { usdPerL: Math.round((usd / l) * 10000) / 10000, date, litres: round2(l) };
      end = start;
    }
    return null;
  }

  function _evalDieselMalfunctionWatchdog(consumedL, otherDiscOutL, malfNetL, malfAbsL) {
    const warnPct = (typeof getAlertParam === 'function' ? Number(getAlertParam('S11', 'malfunction_warn_pct', MALFUNCTION_ALERT_PCT)) : MALFUNCTION_ALERT_PCT) || MALFUNCTION_ALERT_PCT;
    const critPct = (typeof getAlertParam === 'function' ? Number(getAlertParam('S11', 'malfunction_crit_pct', 10.0)) : 10.0) || 10.0;
    const ruleEnabled = typeof isAlertRuleEnabled === 'function' ? isAlertRuleEnabled('S11') : true;
    const companyDieselUsedL = round2(Math.max(0, Number(consumedL || 0)) + Math.max(0, Number(otherDiscOutL || 0)) + Math.max(0, Number(malfNetL || 0)));
    const absL = round2(Math.max(0, Number(malfAbsL || 0)));
    const malfunctionPct = companyDieselUsedL > 0 ? round2((absL / companyDieselUsedL) * 100) : (absL > 0 ? 100 : 0);
    const malfunctionNetPct = companyDieselUsedL > 0 ? round2((Math.abs(Number(malfNetL || 0)) / companyDieselUsedL) * 100) : 0;
    const malfunctionAlert = Boolean(ruleEnabled && absL > 0 && malfunctionPct >= warnPct);
    const malfunctionSeverity = (ruleEnabled && absL > 0 && malfunctionPct >= critPct) ? 'crit' : (malfunctionAlert ? 'warn' : 'ok');
    return {
      companyDieselUsedL,
      malfunctionPct,
      malfunctionNetPct,
      malfunctionThresholdPct: warnPct,
      malfunctionAlert,
      malfunctionSeverity
    };
  }

  function _formatMonthYmLabel(ym) {
    const m = /^(\d{4})-(\d{2})$/.exec(String(ym || ''));
    if (!m) return String(ym || 'Unknown');
    const names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${names[Math.max(0, Math.min(11, Number(m[2]) - 1))]} ${m[1]}`;
  }

  function _getAllDieselMovementsIndex() {
    const expArr = (SEED.records && SEED.records.expenses) || [];
    const fuelArr = (SEED.records && SEED.records.fuel_intakes) || [];
    const malfArr = (SEED.records && SEED.records.fuel_malfunctions) || [];
    const salesArr = (SEED.records && SEED.records.sales_tickets) || [];
    const eqArr = (SEED.records && SEED.records.equipment) || [];
    const hydrated = Boolean(SEED._recordsReady);
    // todayISO: the latest fuel price leaves out future-dated deliveries, so the index turns over at midnight.
    const cacheKey = `${hydrated ? 1 : 0}|${SEED._customRev || 0}|${STATE._customRev || 0}|${STATE.basis}|${expArr.length}|${fuelArr.length}|${malfArr.length}|${salesArr.length}|${eqArr.length}|${todayISO()}`;
    if (_dieselAllIdxCache && _dieselAllIdxCache.cacheKey === cacheKey) return _dieselAllIdxCache;

    const movements = [];
    const byCo = {};
    const coRunning = {};
    ['WTC', 'BBConstruction', 'Lions Transport'].forEach(co => {
      const coKey = co === 'BBConstruction' ? 'bbconstruction' : (co === 'Lions Transport' ? 'lionstransport' : 'wtc');
      const allKpi = (((SEED.models && SEED.models[coKey]) || {}).periods || {}).all || {};
      const preB = hydrated ? 0 : Number(allKpi.diesel_purchased || 0);
      const preI = hydrated ? 0 : Number(allKpi.diesel_litres || 0);
      const preS = hydrated ? 0 : Number(allKpi.diesel_sold || 0);
      byCo[co] = {
        bought: preB,
        boughtUsd: 0,
        boughtCount: 0,
        issued: preI,
        issuedOwn: preI,
        issuedHauler: 0,
        issuedCount: 0,
        discrepancy: 0,
        discrepancyCount: 0,
        malfNet: 0,
        malfAbs: 0,
        malfCount: 0,
        sold: preS,
        soldUsd: 0,
        soldCount: 0,
        pricedLitres: 0,
        pricedUsd: 0,
        pendingCount: 0,
        pendingLitres: 0,
        balance: round2(preB - preI - preS),
        avgUsdPerL: 0 // set from priced deliveries below; never a fixed figure
      };
      coRunning[co] = round2(preB - preI - preS);
    });

    for (let i = 0; i < expArr.length; i++) {
      const e = expArr[i];
      if (!e || e.voided || !isBulkDieselExpense(e)) continue;
      const appRec = isAppRecord(e);
      if (!hydrated && !appRec) continue;
      const co = e.company || 'WTC';
      const l = round2(Number(e.qty || 0));
      const pend = isPendingPriceExpense(e);
      const amt = pend ? 0 : round2(Number(e.amount || 0));
      movements.push({
        id: e.id,
        rkey: 'expenses',
        rec: e,
        company: co,
        date: recordDate(e) || String(e.date || '').slice(0, 10),
        kind: 'bought',
        sortRank: 1,
        ref: String(e.reference || e.name || '').trim(),
        party: String(e.supplier || 'Unassigned Supplier').trim(),
        detail: String(e.notes || e.subcategory || 'Bulk Diesel Delivery').trim(),
        driver: '',
        isOwn: true,
        litres: l,
        deltaL: l,
        amountUsd: amt,
        unitPrice: (!pend && l > 0 && amt > 0) ? round2(amt / l) : null,
        pendingPrice: pend,
        isApp: appRec
      });
    }

    for (let i = 0; i < fuelArr.length; i++) {
      const f = fuelArr[i];
      if (!f || f.voided) continue;
      const appRec = isAppRecord(f);
      if (!hydrated && !appRec) continue;
      const co = f.company || 'WTC';
      if (isDieselTankRefillIntake(f)) {
        const l = round2(Number(f.litres || 0));
        movements.push({
          id: f.id,
          rkey: 'fuel_intakes',
          rec: f,
          company: co,
          date: recordDate(f) || String(f.date || '').slice(0, 10),
          kind: 'bought',
          sortRank: 1,
          ref: String(f.ticket_no || '').trim(),
          party: String(f.location || 'Tank Refill').trim(),
          detail: String(f.notes || 'Tank Refill Slip').trim(),
          driver: String(f.driver || '').trim(),
          isOwn: true,
          litres: l,
          deltaL: l,
          amountUsd: 0,
          unitPrice: null,
          pendingPrice: false,
          isApp: appRec
        });
      } else if (isDieselDispenseIntake(f)) {
        const l = round2(Number(f.litres || 0));
        const eqRec = f.equipment ? equipInfo(f.equipment) : null;
        const isOwn = !eqRec || /^own/i.test(String(eqRec.Ownership || eqRec.ownership || 'Own'));
        movements.push({
          id: f.id,
          rkey: 'fuel_intakes',
          rec: f,
          company: co,
          date: recordDate(f) || String(f.date || '').slice(0, 10),
          kind: isOwn ? 'consumed_own' : 'consumed_hauler',
          sortRank: 4,
          ref: String(f.ticket_no || '').trim(),
          party: String(f.equipment || 'Unassigned Unit').trim(),
          detail: String(f.driver || (isOwn ? 'Own Fleet' : 'Hauler')).trim(),
          driver: String(f.driver || '').trim(),
          isOwn,
          litres: l,
          deltaL: round2(-l),
          amountUsd: 0,
          unitPrice: null,
          pendingPrice: false,
          isApp: appRec
        });
      }
    }

    for (let i = 0; i < malfArr.length; i++) {
      const m = malfArr[i];
      if (!m || m.voided) continue;
      if (!classifyMalfunctionItem(m.item || 'Diesel', m.category || '').isDiesel) continue;
      const l = round2(Number(m.litres || 0));
      if (!l) continue;
      const appRec = isAppRecord(m);
      const co = m.company || 'WTC';
      const dtype = String(m.discrepancy_type || 'Malfunction').trim() || 'Malfunction';
      const eqTag = String(m.equipment || '').trim();
      movements.push({
        id: m.id,
        rkey: 'fuel_malfunctions',
        rec: m,
        company: co,
        date: recordDate(m) || String(m.date || '').slice(0, 10),
        kind: 'malfunction',
        discrepancyType: dtype,
        sortRank: 2,
        ref: String(m.ticket_no || m.name || '').trim(),
        party: eqTag ? `${dtype} · ${eqTag}` : dtype,
        detail: String(m.notes || m.driver || (l > 0 ? 'Tank Shortage / Outflow' : 'Tank Surplus / Over-Read')).trim(),
        driver: String(m.driver || '').trim(),
        isOwn: true,
        litres: l,
        deltaL: round2(-l),
        amountUsd: 0,
        unitPrice: null,
        pendingPrice: false,
        isApp: appRec
      });
    }

    for (let i = 0; i < salesArr.length; i++) {
      const s = salesArr[i];
      if (!s || s.voided || !isDieselSaleTicket(s)) continue;
      const appRec = isAppRecord(s);
      if (!hydrated && !appRec) continue;
      const co = s.company || 'WTC';
      const sgn = ticketSign(s);
      const l = round2(sgn * Number(s.qty || 0));
      const amt = round2(sgn * Number(s.total != null ? s.total : (Number(s.amount || 0) + Number(s.vat_amount || 0))));
      const up = (s.unit_price != null && Number(s.unit_price) > 0)
        ? Number(s.unit_price)
        : (Math.abs(l) > 0 && Math.abs(amt) > 0 ? round2(Math.abs(amt) / Math.abs(l)) : null);
      movements.push({
        id: s.id,
        rkey: 'sales_tickets',
        rec: s,
        company: co,
        date: recordDate(s) || String(s.date || '').slice(0, 10),
        kind: 'sold',
        sortRank: 3,
        ref: String(s.ticket_no || '').trim(),
        party: String(s.customer || 'Walk-in Buyer').trim(),
        detail: String(s.site || s.truck || 'Diesel Sale Ticket').trim(),
        driver: String(s.driver || '').trim(),
        isOwn: false,
        litres: l,
        deltaL: round2(-l),
        amountUsd: amt,
        unitPrice: up,
        pendingPrice: false,
        isApp: appRec
      });
    }

    movements.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      if (a.sortRank !== b.sortRank) return a.sortRank - b.sortRank;
      const rc = _NUM_COLLATOR.compare(a.ref, b.ref);
      if (rc !== 0) return rc;
      return String(a.id || '').localeCompare(String(b.id || ''));
    });

    const tankAfterById = new Map();
    for (let i = 0; i < movements.length; i++) {
      const mv = movements[i];
      const co = mv.company;
      if (!byCo[co]) {
        byCo[co] = { bought: 0, boughtUsd: 0, boughtCount: 0, issued: 0, issuedOwn: 0, issuedHauler: 0, issuedCount: 0, discrepancy: 0, discrepancyCount: 0, malfNet: 0, malfAbs: 0, malfCount: 0, sold: 0, soldUsd: 0, soldCount: 0, pricedLitres: 0, pricedUsd: 0, pendingCount: 0, pendingLitres: 0, balance: 0, avgUsdPerL: 0 };
        coRunning[co] = 0;
      }
      const st = byCo[co];
      coRunning[co] = round2((coRunning[co] || 0) + mv.deltaL);
      mv.co_tank_after = coRunning[co];
      if (mv.id != null) tankAfterById.set(mv.id, mv.co_tank_after);
      if (mv.kind === 'bought') {
        st.bought = round2(st.bought + mv.litres);
        st.boughtUsd = round2(st.boughtUsd + mv.amountUsd);
        st.boughtCount += 1;
        if (mv.pendingPrice) {
          st.pendingCount += 1;
          st.pendingLitres = round2(st.pendingLitres + mv.litres);
          if (!st._pendDates) st._pendDates = [];
          st._pendDates.push(String((mv.rec && mv.rec.date) || mv.date || '').slice(0, 10));
        } else if (mv.litres > 0 && mv.amountUsd > 0) {
          st.pricedLitres += mv.litres;
          st.pricedUsd += mv.amountUsd;
          if (!st._pricedBuys) st._pricedBuys = [];
          // txDate = the day the diesel was bought, whatever the Rep Date / Tx Date switch shows (latest fuel price).
          st._pricedBuys.push({ date: mv.date, txDate: String((mv.rec && mv.rec.date) || mv.date || '').slice(0, 10), litres: mv.litres, amountUsd: mv.amountUsd });
        }
      } else if (mv.kind === 'sold') {
        st.sold = round2(st.sold + mv.litres);
        st.soldUsd = round2(st.soldUsd + mv.amountUsd);
        st.soldCount += 1;
      } else if (mv.kind === 'malfunction') {
        st.discrepancy = round2(st.discrepancy + mv.litres);
        st.discrepancyCount += 1;
        if (/^malfunction$/i.test(mv.discrepancyType || 'Malfunction')) {
          st.malfNet = round2(st.malfNet + mv.litres);
          st.malfAbs = round2(st.malfAbs + Math.abs(mv.litres));
          st.malfCount += 1;
        }
      } else {
        st.issued = round2(st.issued + mv.litres);
        if (mv.isOwn) st.issuedOwn = round2(st.issuedOwn + mv.litres);
        else st.issuedHauler = round2(st.issuedHauler + mv.litres);
        st.issuedCount += 1;
      }
    }

    // Priced deliveries of the three Manufacturing companies together: the typo reference for a company with little history.
    const mfgGroupBuys = [];
    ['WTC', 'BBConstruction', 'Lions Transport'].forEach(co => {
      ((byCo[co] && byCo[co]._pricedBuys) || []).forEach(b => mfgGroupBuys.push({ date: b.txDate || b.date, litres: b.litres, amountUsd: b.amountUsd }));
    });
    Object.keys(byCo).forEach(co => {
      const st = byCo[co];
      st.balance = round2(st.bought - st.issued - st.discrepancy - st.sold);
      st.allRefillsAvgUsdPerL = st.pricedLitres > 0 ? round2(st.pricedUsd / st.pricedLitres) : 0;
      const buys = st._pricedBuys || [];
      if (st.balance > 0 && buys.length > 0) {
        let needL = st.balance;
        let remCostUsd = 0;
        let remCoveredL = 0;
        for (let i = buys.length - 1; i >= 0 && needL > 0.0001; i--) {
          const b = buys[i];
          const takeL = Math.min(needL, b.litres);
          remCostUsd += takeL * (b.amountUsd / b.litres);
          remCoveredL += takeL;
          needL = round2(needL - takeL);
        }
        st.remCoveredLitres = round2(remCoveredL);
        st.remValueUsd = round2(remCostUsd);
        st.avgUsdPerL = remCoveredL > 0 ? round2(remCostUsd / remCoveredL) : st.allRefillsAvgUsdPerL;
      } else if (buys.length > 0) {
        const lastDate = buys[buys.length - 1].date;
        let lastDayL = 0, lastDayUsd = 0;
        for (let i = buys.length - 1; i >= 0; i--) {
          if (buys[i].date !== lastDate) break;
          lastDayL += buys[i].litres;
          lastDayUsd += buys[i].amountUsd;
        }
        st.remCoveredLitres = 0;
        st.remValueUsd = 0;
        st.avgUsdPerL = lastDayL > 0 ? round2(lastDayUsd / lastDayL) : st.allRefillsAvgUsdPerL;
      } else {
        st.remCoveredLitres = 0;
        st.remValueUsd = 0;
        st.avgUsdPerL = 0;
      }
      // Kept on the index (purchase date, litres, $) so a past ticket can be costed at the price in force on its day.
      st.pricedBuysTx = buys.map(b => ({ date: b.txDate || b.date, litres: b.litres, amountUsd: b.amountUsd }));
      const lp = _latestBulkDieselPrice(st.pricedBuysTx, mfgGroupBuys);
      st.latestBuyUsdPerL = lp ? lp.usdPerL : 0;
      st.latestBuyDate = lp ? lp.date : '';
      st.latestBuyLitres = lp ? lp.litres : 0;
      // Deliveries already in the tank but newer than the latest priced one (supplier invoice still awaited).
      const todayIso = todayISO();
      st.pendingAfterLatestCount = (st._pendDates || []).filter(d => d <= todayIso && (!st.latestBuyDate || d > st.latestBuyDate)).length;
      delete st._pricedBuys;
      delete st._pendDates;
    });
    // Group fallback for a company with no delivery of its own: the newest one among the Manufacturing
    // companies only (the expenses table is shared with the other industries, e.g. resort generator diesel).
    let latestBuy = null;
    ['WTC', 'BBConstruction', 'Lions Transport'].forEach(co => {
      const st = byCo[co];
      if (!st || !(st.latestBuyUsdPerL > 0)) return;
      if (!latestBuy || st.latestBuyDate > latestBuy.date || (st.latestBuyDate === latestBuy.date && st.latestBuyLitres > latestBuy.litres)) {
        latestBuy = { co, usdPerL: st.latestBuyUsdPerL, date: st.latestBuyDate, litres: st.latestBuyLitres };
      }
    });
    // Tank valuation of a company with no priced delivery of its own: its latest fuel price, else the group's
    // latest one, else no rate at all (the screens then show no value). Never a fixed $/L.
    Object.keys(byCo).forEach(co => {
      const st = byCo[co];
      if (st.avgUsdPerL > 0) return;
      const isMfgCo = co === 'WTC' || co === 'BBConstruction' || co === 'Lions Transport';
      const fb = st.latestBuyUsdPerL > 0 ? st.latestBuyUsdPerL : ((isMfgCo && latestBuy) ? latestBuy.usdPerL : 0);
      st.avgUsdPerL = fb > 0 ? round2(fb) : 0;
      st.avgIsGroupPrice = Boolean(fb > 0 && !(st.latestBuyUsdPerL > 0));
    });

    _dieselAllIdxCache = { cacheKey, hydrated, movements, byCo, tankAfterById, latestBuy, mfgGroupBuys, _asOfMemo: new Map() };
    _dieselTankLedgerCache.clear();
    return _dieselAllIdxCache;
  }

  function getDieselTankLedger(coOverride, rangeOverride) {
    const idx = _getAllDieselMovementsIndex();
    const rawKey = coOverride || STATE.company;
    const coKey = resolveEffectiveModelKey(rawKey);
    const allowedAll = allowedCompanyNames();
    let cos;
    if (coKey === 'wtc') cos = allowedAll.includes('WTC') ? ['WTC'] : ['WTC'];
    else if (coKey === 'bbconstruction') cos = ['BBConstruction'];
    else if (coKey === 'lionstransport') cos = ['Lions Transport'];
    else cos = allowedAll.length ? allowedAll : ['WTC', 'BBConstruction', 'Lions Transport'];

    const range = rangeOverride !== undefined ? rangeOverride : periodRange(STATE.period);
    const rSig = range ? `${range.from}..${range.to}` : 'all';
    const lKey = `${idx.cacheKey}|${coKey}|${cos.join(',')}|${rSig}`;
    if (_dieselTankLedgerCache.has(lKey)) return _dieselTankLedgerCache.get(lKey);

    const perCo = {};
    Array.from(new Set(['WTC', 'BBConstruction', 'Lions Transport'].concat(cos || []))).forEach(co => {
      const coBase = idx.byCo[co] || {};
      perCo[co] = {
        openingL: 0, boughtL: 0, boughtUsd: 0, boughtCount: 0,
        consumedOwnL: 0, consumedHaulerL: 0, consumedL: 0, consumedCount: 0,
        discrepancyL: 0, discrepancyCount: 0, malfNetL: 0, malfAbsL: 0, malfCount: 0, otherDiscOutL: 0,
        soldL: 0, soldUsd: 0, soldCount: 0, closingL: 0, pendingCount: 0, pendingLitres: 0,
        avgUsdPerL: coBase.avgUsdPerL || 0, remValueUsd: coBase.remValueUsd || 0,
        companyDieselUsedL: 0, malfunctionPct: 0, malfunctionAlert: false, malfunctionSeverity: 'ok'
      };
    });

    let openingTankL = 0;
    let boughtL = 0, boughtUsd = 0, boughtCount = 0, pendingCount = 0, pendingLitres = 0;
    let consumedOwnL = 0, consumedOwnCount = 0;
    let consumedHaulerL = 0, consumedHaulerCount = 0;
    let discrepancyL = 0, discrepancyCount = 0;
    let malfNetL = 0, malfAbsL = 0, malfCount = 0, otherDiscOutL = 0;
    let soldL = 0, soldUsd = 0, soldCount = 0;
    const monthBuckets = new Map();
    const soldByBuyerMap = new Map();
    const boughtBySupplierMap = new Map();
    const discrepancyByTypeMap = new Map();
    const periodAsc = [];

    if (!idx.hydrated) {
      // Cold-boot pre-hydration fallback: anchor on pre-aggregated model monthly/all + seed_core malfunctions + local app-entered records
      cos.forEach(co => {
        const ck = co === 'BBConstruction' ? 'bbconstruction' : (co === 'Lions Transport' ? 'lionstransport' : 'wtc');
        const mdl = (SEED.models && SEED.models[ck]) || {};
        if (!range) {
          const ak = (mdl.periods && mdl.periods.all) || {};
          const b = Number(ak.diesel_purchased || 0);
          const u = Number(ak.diesel_litres || 0);
          const s = Number(ak.diesel_sold || 0);
          perCo[co].boughtL = round2(b);
          perCo[co].consumedOwnL = round2(u);
          perCo[co].consumedL = round2(u);
          perCo[co].soldL = round2(s);
          boughtL += b;
          consumedOwnL += u;
          soldL += s;
        } else {
          const mRows = Array.isArray(mdl.monthly) ? mdl.monthly : [];
          const fYm = String(range.from || '').slice(0, 7);
          const tYm = String(range.to || '').slice(0, 7);
          mRows.forEach(mr => {
            const ym = String(mr.month || mr.ym || '').slice(0, 7);
            if (!ym) return;
            const b = Number(mr.diesel_bought || 0);
            const u = Number(mr.diesel_issued || 0);
            const s = Number(mr.diesel_sold || 0);
            const d = b - u - s;
            if (ym < fYm) {
              openingTankL += d;
              perCo[co].openingL = round2(perCo[co].openingL + d);
            } else if (ym <= tYm) {
              boughtL += b;
              consumedOwnL += u;
              soldL += s;
              perCo[co].boughtL = round2(perCo[co].boughtL + b);
              perCo[co].consumedOwnL = round2(perCo[co].consumedOwnL + u);
              perCo[co].consumedL = round2(perCo[co].consumedL + u);
              perCo[co].soldL = round2(perCo[co].soldL + s);
            }
          });
        }
      });
    }

    let scopeRunning = round2(openingTankL);
    for (let i = 0; i < idx.movements.length; i++) {
      const mv = idx.movements[i];
      if (!cos.includes(mv.company)) continue;
      const pc = perCo[mv.company] || (perCo[mv.company] = {
        openingL: 0, boughtL: 0, boughtUsd: 0, boughtCount: 0,
        consumedOwnL: 0, consumedHaulerL: 0, consumedL: 0, consumedCount: 0,
        discrepancyL: 0, discrepancyCount: 0, malfNetL: 0, malfAbsL: 0, malfCount: 0, otherDiscOutL: 0,
        soldL: 0, soldUsd: 0, soldCount: 0, closingL: 0, pendingCount: 0, pendingLitres: 0,
        companyDieselUsedL: 0, malfunctionPct: 0, malfunctionAlert: false, malfunctionSeverity: 'ok'
      });
      if (range && mv.date < range.from) {
        openingTankL += mv.deltaL;
        scopeRunning += mv.deltaL;
        pc.openingL = round2(pc.openingL + mv.deltaL);
        continue;
      }
      if (range && mv.date > range.to) continue;
      scopeRunning = round2(scopeRunning + mv.deltaL);
      const ym = String(mv.date || '').slice(0, 7) || 'Unknown';
      let mb = monthBuckets.get(ym);
      if (!mb) {
        mb = {
          ym,
          monthLabel: _formatMonthYmLabel(ym),
          openingL: 0,
          boughtL: 0, boughtUsd: 0, boughtCount: 0,
          consumedOwnL: 0, consumedHaulerL: 0, consumedL: 0, consumedCount: 0,
          discrepancyL: 0, discrepancyCount: 0, malfNetL: 0, malfAbsL: 0, malfCount: 0, otherDiscOutL: 0,
          soldL: 0, soldUsd: 0, soldCount: 0,
          netChangeL: 0, closingL: 0,
          companyDieselUsedL: 0, malfunctionPct: 0, malfunctionAlert: false, malfunctionSeverity: 'ok'
        };
        monthBuckets.set(ym, mb);
      }
      if (mv.kind === 'bought') {
        boughtL += mv.litres;
        boughtUsd += mv.amountUsd;
        boughtCount += 1;
        pc.boughtL = round2(pc.boughtL + mv.litres);
        pc.boughtUsd = round2(pc.boughtUsd + mv.amountUsd);
        pc.boughtCount += 1;
        mb.boughtL = round2(mb.boughtL + mv.litres);
        mb.boughtUsd = round2(mb.boughtUsd + mv.amountUsd);
        mb.boughtCount += 1;
        if (mv.pendingPrice) {
          pendingCount += 1;
          pendingLitres += mv.litres;
          pc.pendingCount += 1;
          pc.pendingLitres = round2(pc.pendingLitres + mv.litres);
        }
        const sk = norm(mv.party) || 'unassigned';
        let sb = boughtBySupplierMap.get(sk);
        if (!sb) {
          sb = { supplier: mv.party || 'Unassigned Supplier', companiesSet: new Set(), vouchers: 0, litres: 0, amountUsd: 0, pricedLitres: 0, pendingCount: 0, lastDate: '' };
          boughtBySupplierMap.set(sk, sb);
        }
        sb.companiesSet.add(mv.company);
        sb.vouchers += 1;
        sb.litres = round2(sb.litres + mv.litres);
        sb.amountUsd = round2(sb.amountUsd + mv.amountUsd);
        if (mv.pendingPrice) sb.pendingCount += 1;
        else if (mv.litres > 0 && mv.amountUsd > 0) sb.pricedLitres += mv.litres;
        if (mv.date >= sb.lastDate) sb.lastDate = mv.date;
      } else if (mv.kind === 'sold') {
        soldL += mv.litres;
        soldUsd += mv.amountUsd;
        soldCount += 1;
        pc.soldL = round2(pc.soldL + mv.litres);
        pc.soldUsd = round2(pc.soldUsd + mv.amountUsd);
        pc.soldCount += 1;
        mb.soldL = round2(mb.soldL + mv.litres);
        mb.soldUsd = round2(mb.soldUsd + mv.amountUsd);
        mb.soldCount += 1;
        const bk = norm(mv.party) || 'walk-in';
        let bb = soldByBuyerMap.get(bk);
        if (!bb) {
          bb = { buyer: mv.party || 'Walk-in Buyer', companiesSet: new Set(), tickets: 0, litres: 0, amountUsd: 0, lastDate: '' };
          soldByBuyerMap.set(bk, bb);
        }
        bb.companiesSet.add(mv.company);
        bb.tickets += 1;
        bb.litres = round2(bb.litres + mv.litres);
        bb.amountUsd = round2(bb.amountUsd + mv.amountUsd);
        if (mv.date >= bb.lastDate) bb.lastDate = mv.date;
      } else if (mv.kind === 'malfunction') {
        const dtype = mv.discrepancyType || 'Malfunction';
        const isMalfOnly = /^malfunction$/i.test(dtype);
        const isCalib = /^configuration$/i.test(dtype);
        discrepancyL += mv.litres;
        discrepancyCount += 1;
        pc.discrepancyL = round2(pc.discrepancyL + mv.litres);
        pc.discrepancyCount += 1;
        mb.discrepancyL = round2(mb.discrepancyL + mv.litres);
        mb.discrepancyCount += 1;
        if (isMalfOnly) {
          malfNetL += mv.litres;
          malfAbsL += Math.abs(mv.litres);
          malfCount += 1;
          pc.malfNetL = round2(pc.malfNetL + mv.litres);
          pc.malfAbsL = round2(pc.malfAbsL + Math.abs(mv.litres));
          pc.malfCount += 1;
          mb.malfNetL = round2(mb.malfNetL + mv.litres);
          mb.malfAbsL = round2(mb.malfAbsL + Math.abs(mv.litres));
          mb.malfCount += 1;
        } else if (!isCalib && mv.litres > 0) {
          otherDiscOutL += mv.litres;
          pc.otherDiscOutL = round2(pc.otherDiscOutL + mv.litres);
          mb.otherDiscOutL = round2(mb.otherDiscOutL + mv.litres);
        }
        const dk = norm(dtype) || 'malfunction';
        let db = discrepancyByTypeMap.get(dk);
        if (!db) {
          db = { type: dtype, companiesSet: new Set(), count: 0, netLitres: 0, absLitres: 0, tankDeltaL: 0, lastDate: '' };
          discrepancyByTypeMap.set(dk, db);
        }
        db.companiesSet.add(mv.company);
        db.count += 1;
        db.netLitres = round2(db.netLitres + mv.litres);
        db.absLitres = round2(db.absLitres + Math.abs(mv.litres));
        db.tankDeltaL = round2(db.tankDeltaL + mv.deltaL);
        if (mv.date >= db.lastDate) db.lastDate = mv.date;
      } else {
        if (mv.isOwn) {
          consumedOwnL += mv.litres;
          consumedOwnCount += 1;
          pc.consumedOwnL = round2(pc.consumedOwnL + mv.litres);
          mb.consumedOwnL = round2(mb.consumedOwnL + mv.litres);
        } else {
          consumedHaulerL += mv.litres;
          consumedHaulerCount += 1;
          pc.consumedHaulerL = round2(pc.consumedHaulerL + mv.litres);
          mb.consumedHaulerL = round2(mb.consumedHaulerL + mv.litres);
        }
        pc.consumedL = round2(pc.consumedL + mv.litres);
        pc.consumedCount += 1;
        mb.consumedL = round2(mb.consumedL + mv.litres);
        mb.consumedCount += 1;
      }
      periodAsc.push(Object.assign({}, mv, { tank_after: idx.hydrated ? scopeRunning : mv.co_tank_after }));
    }

    openingTankL = round2(openingTankL);
    boughtL = round2(boughtL);
    boughtUsd = round2(boughtUsd);
    consumedOwnL = round2(consumedOwnL);
    consumedHaulerL = round2(consumedHaulerL);
    const consumedL = round2(consumedOwnL + consumedHaulerL);
    const consumedCount = consumedOwnCount + consumedHaulerCount;
    discrepancyL = round2(discrepancyL);
    malfNetL = round2(malfNetL);
    malfAbsL = round2(malfAbsL);
    otherDiscOutL = round2(otherDiscOutL);
    soldL = round2(soldL);
    soldUsd = round2(soldUsd);
    pendingLitres = round2(pendingLitres);
    const netChangeL = round2(boughtL - consumedL - discrepancyL - soldL);
    const closingTankL = round2(openingTankL + netChangeL);
    const scopeWatch = _evalDieselMalfunctionWatchdog(consumedL, otherDiscOutL, malfNetL, malfAbsL);

    Object.keys(perCo).forEach(co => {
      const pc = perCo[co];
      pc.openingL = round2(pc.openingL);
      pc.closingL = round2(pc.openingL + pc.boughtL - pc.consumedL - pc.discrepancyL - pc.soldL);
      const pw = _evalDieselMalfunctionWatchdog(pc.consumedL, pc.otherDiscOutL, pc.malfNetL, pc.malfAbsL);
      pc.companyDieselUsedL = pw.companyDieselUsedL;
      pc.malfunctionPct = pw.malfunctionPct;
      pc.malfunctionAlert = pw.malfunctionAlert;
      pc.malfunctionSeverity = pw.malfunctionSeverity;
    });

    let monthlyRows;
    if (idx.hydrated) {
      const sortedYms = Array.from(monthBuckets.keys()).sort();
      let mRun = openingTankL;
      const ascMonths = sortedYms.map(ym => {
        const mb = monthBuckets.get(ym);
        mb.openingL = round2(mRun);
        mb.netChangeL = round2(mb.boughtL - mb.consumedL - mb.discrepancyL - mb.soldL);
        mRun = round2(mRun + mb.netChangeL);
        mb.closingL = mRun;
        const mw = _evalDieselMalfunctionWatchdog(mb.consumedL, mb.otherDiscOutL, mb.malfNetL, mb.malfAbsL);
        mb.companyDieselUsedL = mw.companyDieselUsedL;
        mb.malfunctionPct = mw.malfunctionPct;
        mb.malfunctionAlert = mw.malfunctionAlert;
        mb.malfunctionSeverity = mw.malfunctionSeverity;
        return mb;
      });
      monthlyRows = ascMonths.reverse();
    } else {
      const mdl = (SEED.models && (SEED.models[coKey] || SEED.models['manufacturing-group'])) || {};
      const mSrc = getScopedMonthly(mdl.monthly);
      let mRun = openingTankL;
      monthlyRows = mSrc.map(mr => {
        const ym = String(mr.month || mr.ym || '').slice(0, 7);
        const mbExtra = monthBuckets.get(ym);
        const b = round2(Number(mr.diesel_bought || 0) + (mbExtra ? mbExtra.boughtL : 0));
        const u = round2(Number(mr.diesel_issued || 0) + (mbExtra ? mbExtra.consumedL : 0));
        const disc = round2(mbExtra ? mbExtra.discrepancyL : 0);
        const s = round2(Number(mr.diesel_sold || 0) + (mbExtra ? mbExtra.soldL : 0));
        const op = round2(mRun);
        const nc = round2(b - u - disc - s);
        mRun = round2(mRun + nc);
        const mw = _evalDieselMalfunctionWatchdog(u, mbExtra ? mbExtra.otherDiscOutL : 0, mbExtra ? mbExtra.malfNetL : 0, mbExtra ? mbExtra.malfAbsL : 0);
        return {
          ym,
          monthLabel: _formatMonthYmLabel(ym),
          openingL: op,
          boughtL: b, boughtUsd: mbExtra ? mbExtra.boughtUsd : 0, boughtCount: mbExtra ? mbExtra.boughtCount : 0,
          consumedOwnL: u, consumedHaulerL: 0, consumedL: u, consumedCount: mbExtra ? mbExtra.consumedCount : 0,
          discrepancyL: disc, discrepancyCount: mbExtra ? mbExtra.discrepancyCount : 0,
          malfNetL: mbExtra ? mbExtra.malfNetL : 0, malfAbsL: mbExtra ? mbExtra.malfAbsL : 0, malfCount: mbExtra ? mbExtra.malfCount : 0,
          soldL: s, soldUsd: mbExtra ? mbExtra.soldUsd : 0, soldCount: mbExtra ? mbExtra.soldCount : 0,
          netChangeL: nc, closingL: mRun,
          companyDieselUsedL: mw.companyDieselUsedL,
          malfunctionPct: mw.malfunctionPct,
          malfunctionAlert: mw.malfunctionAlert,
          malfunctionSeverity: mw.malfunctionSeverity
        };
      }).reverse();
    }

    const soldByBuyer = Array.from(soldByBuyerMap.values()).map(b => ({
      buyer: b.buyer,
      companies: Array.from(b.companiesSet).join(', '),
      tickets: b.tickets,
      litres: b.litres,
      amountUsd: b.amountUsd,
      avgPriceUsd: b.litres > 0 && b.amountUsd > 0 ? round2(b.amountUsd / b.litres) : null,
      sharePct: soldL > 0 ? round2((b.litres / soldL) * 100) : 0,
      lastDate: b.lastDate
    })).sort((a, b) => b.litres - a.litres || b.amountUsd - a.amountUsd);

    const boughtBySupplier = Array.from(boughtBySupplierMap.values()).map(s => ({
      supplier: s.supplier,
      companies: Array.from(s.companiesSet).join(', '),
      vouchers: s.vouchers,
      litres: s.litres,
      amountUsd: s.amountUsd,
      avgCostUsd: s.pricedLitres > 0 && s.amountUsd > 0 ? round2(s.amountUsd / s.pricedLitres) : null,
      pendingCount: s.pendingCount,
      sharePct: boughtL > 0 ? round2((s.litres / boughtL) * 100) : 0,
      lastDate: s.lastDate
    })).sort((a, b) => b.litres - a.litres || b.amountUsd - a.amountUsd);

    const discrepancyByType = Array.from(discrepancyByTypeMap.values()).map(d => ({
      type: d.type,
      companies: Array.from(d.companiesSet).join(', '),
      count: d.count,
      netLitres: d.netLitres,
      absLitres: d.absLitres,
      tankDeltaL: d.tankDeltaL,
      lastDate: d.lastDate
    })).sort((a, b) => b.absLitres - a.absLitres);

    const out = {
      hydrated: idx.hydrated,
      coKey,
      openingTankL,
      boughtL,
      boughtUsd,
      boughtCount,
      pendingCount,
      pendingLitres,
      consumedOwnL,
      consumedOwnCount,
      consumedHaulerL,
      consumedHaulerCount,
      consumedL,
      consumedCount,
      discrepancyL,
      discrepancyCount,
      malfNetL,
      malfAbsL,
      malfCount,
      otherDiscOutL,
      companyDieselUsedL: scopeWatch.companyDieselUsedL,
      malfunctionPct: scopeWatch.malfunctionPct,
      malfunctionNetPct: scopeWatch.malfunctionNetPct,
      malfunctionThresholdPct: scopeWatch.malfunctionThresholdPct,
      malfunctionAlert: scopeWatch.malfunctionAlert,
      malfunctionSeverity: scopeWatch.malfunctionSeverity,
      soldL,
      soldUsd,
      soldCount,
      netChangeL,
      closingTankL,
      perCo,
      monthlyRows,
      scopedMovements: periodAsc.reverse(),
      soldByBuyer,
      boughtBySupplier,
      discrepancyByType,
      tankAfterById: idx.tankAfterById
    };
    if (_dieselTankLedgerCache.size > 32) _dieselTankLedgerCache.clear();
    _dieselTankLedgerCache.set(lKey, out);
    return out;
  }
  window.MFG_DIESEL_TANK = getDieselTankLedger;

  function computeDieselTank() {
    const idx = _getAllDieselMovementsIndex();
    const byCo = {};
    ['WTC', 'BBConstruction', 'Lions Transport'].forEach(co => {
      const st = idx.byCo[co] || { bought: 0, issued: 0, discrepancy: 0, sold: 0, balance: 0, avgUsdPerL: 0, remValueUsd: 0, allRefillsAvgUsdPerL: 0, pendingCount: 0, pendingLitres: 0 };
      byCo[co] = {
        bought: st.bought,
        issued: st.issued,
        discrepancy: st.discrepancy || 0,
        sold: st.sold,
        balance: st.balance,
        avgUsdPerL: st.avgUsdPerL,
        avgIsGroupPrice: Boolean(st.avgIsGroupPrice),
        remValueUsd: st.remValueUsd || 0,
        allRefillsAvgUsdPerL: st.allRefillsAvgUsdPerL || st.avgUsdPerL,
        pendingCount: st.pendingCount,
        pendingLitres: st.pendingLitres
      };
    });
    return { byCo };
  }

  function isOvertimeTime(hhmm) {
    const m = /^(\d{1,2}):(\d{2})/.exec(String(hhmm || ''));
    if (!m) return false;
    const mins = Number(m[1]) * 60 + Number(m[2]);
    return mins < DAY_SHIFT_FROM || mins > DAY_SHIFT_TO;
  }

  // ==========================================================================
  // VIEW 01: OVERVIEW COMMAND CENTER (EXACT ISABI REV 10 "LEDGER" ARCHITECTURE)
  // ==========================================================================
  function cleanCeoText(s) {
    return String(s == null ? '' : s).replace(/[—–]/g, '-').replace(/→/g, '-');
  }

  function buildExecutiveChart(months, opts) {
    const cfg = opts || {};
    const W = 630, H = 274, ml = 56, mr = 14, mt = 20, mb = 26;
    const pw = W - ml - mr, ph = H - mt - mb;
    const isCustom = Array.isArray(cfg.customBars);
    const maskCost = Boolean(cfg.maskCost);
    const maskProfit = Boolean(cfg.maskProfit);
    const rows = isCustom ? cfg.customBars.slice(0, 12) : (months || []).slice(-12);
    if (!rows.length) {
      return '<svg class="chart" viewBox="0 0 630 274" role="img" aria-label="No monthly ledger data"><text class="tick" x="315" y="137" text-anchor="middle">No monthly ledger data for this entity yet</text></svg>';
    }

    const sValsList = rows.map(r => {
      if (isCustom) {
        return [
          Math.max(0, Number(r.rev || 0)) / 1000,
          maskCost ? 0 : Math.max(0, Number(r.cost || 0)) / 1000,
          maskProfit ? 0 : Math.max(0, Number(r.op || 0)) / 1000
        ];
      }
      const s = Math.max(0, Number(STATE.basis === 'rep' ? (r.sales_rep || r.sales_ttc || 0) : (r.sales_ttc || 0))) / 1000;
      const raw = maskCost ? 0 : Math.max(0, Number(r.raw_cost || 0)) / 1000;
      const prof = maskProfit ? 0 : Math.max(0, Number(r.operating_profit || 0)) / 1000;
      return [s, raw, prof];
    });

    const maxVal = Math.max(20, ...sValsList.map(v => Math.max(v[0], v[1], v[2])));
    const stepUnit = maxVal > 1000 ? 250 : (maxVal > 200 ? 50 : 10);
    const max = Math.max(stepUnit, Math.ceil((maxVal * 1.12) / stepUnit) * stepUnit);
    const y = v => mt + ph - (v / max) * ph;

    let g = '';
    [0, 0.25, 0.5, 0.75, 1].forEach(f => {
      const tv = Math.round(max * f);
      g += `<line class="grid" x1="${ml}" x2="${W - mr}" y1="${y(tv).toFixed(1)}" y2="${y(tv).toFixed(1)}"/>`;
      g += `<text class="tick" x="${ml - 8}" y="${(y(tv) + 4).toFixed(1)}" text-anchor="end">$${tv.toLocaleString()}k</text>`;
    });

    const activeRevs = sValsList.map(v => v[0]).filter(v => v > 0);
    const avgRevK = activeRevs.length ? (activeRevs.reduce((a, b) => a + b, 0) / activeRevs.length) : 0;
    if (avgRevK > 0 && rows.length >= 3) {
      const ay = y(avgRevK).toFixed(1);
      g += `<line class="ceo-avg-line" x1="${ml}" x2="${W - mr}" y1="${ay}" y2="${ay}" stroke="var(--brass)" stroke-width="1.25" stroke-dasharray="4 3" opacity="0.78"/>`;
      g += `<text class="ceo-bar-top-lbl is-peak" x="${W - mr - 2}" y="${Math.max(mt + 9, Number(ay) - 4).toFixed(1)}" text-anchor="end">Avg $${Math.round(avgRevK).toLocaleString()}k</text>`;
    }

    let peakIdx = -1;
    let peakRevK = 0;
    sValsList.forEach((v, idx) => {
      if (v[0] > peakRevK) {
        peakRevK = v[0];
        peakIdx = idx;
      }
    });

    const n = rows.length;
    const slot = pw / n;
    const bw = Math.min(32, Math.max(16, slot * 0.6));
    const subW = (bw - 3) / 3;
    const s1Lbl = cfg.s1Label || 'Total Sales';
    const s2Lbl = cfg.s2Label || 'Raw Material Cost';
    const s3Lbl = cfg.s3Label || 'Operating Cash Profit';

    rows.forEach((row, i) => {
      const x0 = ml + slot * i + (slot - bw) / 2;
      const [sK, rK, pK] = sValsList[i];
      const fullLbl = isCustom ? String(row.fullLabel || row.label || '') : String(row['Year Month'] || row.YearMonthNo || '');
      const shortLbl = isCustom
        ? String(row.label || '').slice(0, 11)
        : fullLbl.replace('2024', '24').replace('2025', '25').replace('2026', '26').slice(0, 6);
      const badgeStr = isCustom
        ? String(row.badge || `${fmtUSDk((row.rev || 0))}`)
        : `${fmtNum(row.loads)} loads`;
      const marginPctStr = sK > 0 ? ` (${((pK / sK) * 100).toFixed(1)}%)` : '';

      const isPeak = i === peakIdx && n >= 3 && sK > 0;
      if (isPeak) {
        g += `<rect x="${(ml + slot * i + 3).toFixed(1)}" y="${mt}" width="${Math.max(8, slot - 6).toFixed(1)}" height="${ph}" rx="4" fill="rgba(192,137,47,0.065)"/>`;
      }

      const bars = [
        { v: Number.isFinite(sK) ? sK : 0, cls: 's-1', x: x0, idx: 0 },
        { v: Number.isFinite(rK) ? rK : 0, cls: 's-2', x: x0 + subW + 1.5, idx: 1 },
        { v: Number.isFinite(pK) ? pK : 0, cls: 's-3', x: x0 + (subW + 1.5) * 2, idx: 2 }
      ].filter(b => !(maskCost && b.idx === 1) && !(maskProfit && b.idx === 2)).map(b => {
        const top = Number(y(b.v) || 0);
        const bottom = Number(y(0) || 0);
        const h = Math.max(2, bottom - top);
        return `<rect class="${b.cls}" data-series-idx="${b.idx}" x="${b.x.toFixed(1)}" y="${top.toFixed(1)}" width="${subW.toFixed(1)}" height="${h.toFixed(1)}" rx="2"/>`;
      }).join('');

      if (isPeak || isCustom) {
        const lblY = Math.max(mt + 10, y(sK) - 5);
        g += `<text class="ceo-bar-top-lbl${isPeak ? ' is-peak' : ''}" x="${(x0 + bw / 2).toFixed(1)}" y="${lblY.toFixed(1)}" text-anchor="middle">$${sK >= 100 ? Math.round(sK).toLocaleString() : sK.toFixed(0)}k</text>`;
      }

      const tip = `${s1Lbl}: $${sK.toFixed(1)}k · ${s2Lbl}: ${maskCost ? 'Restricted' : `$${rK.toFixed(1)}k`} · ${s3Lbl}: ${maskProfit ? 'Restricted' : `$${pK.toFixed(1)}k${marginPctStr}`}`;
      const popSpec = JSON.stringify({
        t: fullLbl,
        b: badgeStr,
        r: [
          { l: s1Lbl, v: `$${sK.toFixed(1)}k`, c: 'var(--s1)' },
          { l: s2Lbl, v: maskCost ? 'Restricted' : `$${rK.toFixed(1)}k`, c: 'var(--s2)' },
          { l: s3Lbl, v: maskProfit ? 'Restricted' : `$${pK.toFixed(1)}k${marginPctStr}`, c: 'var(--s3)', tot: true }
        ]
      });
      g += `<g class="col" data-m="${esc(fullLbl)}" data-t="$${sK.toFixed(1)}k" data-tip="${esc(tip)}" data-chart-pop="${esc(popSpec)}">`
        + `<rect class="hit" x="${(ml + slot * i).toFixed(1)}" y="${mt}" width="${slot.toFixed(1)}" height="${ph}" fill="transparent"/>`
        + `<line class="pbi-col-guide" x1="${(x0 + bw / 2).toFixed(1)}" x2="${(x0 + bw / 2).toFixed(1)}" y1="${mt}" y2="${mt + ph}"/>`
        + `${bars}</g>`;
      g += `<text class="tick" x="${(x0 + bw / 2).toFixed(1)}" y="${H - 7}" text-anchor="middle">${esc(shortLbl)}</text>`;
    });

    g += `<line class="axis" x1="${ml}" x2="${W - mr}" y1="${y(0)}" y2="${y(0)}"/>`;
    return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(cfg.ariaLabel || 'Monthly revenue, direct cost, and profit trajectory')}">${g}</svg>`;
  }

  function renderCeoKpiCard(c) {
    const segs = (c.segs || []).filter(s => Number(s.pct || 0) > 0);
    const meterHtml = `<div class="ceo-kpi-meter" aria-hidden="true">${segs.map(s => `<span class="ceo-meter-seg ${esc(s.tone || 'cobalt')}" style="width:${Math.max(2, Math.min(100, Number(s.pct || 0))).toFixed(1)}%"></span>`).join('')}</div>`;
    return `
      <div class="kpi kpi-link ceo-kpi-card" data-nav-jump="${esc(c.jump)}" role="button" tabindex="0" data-ui-tip="${esc(cleanCeoText(c.tip || ('Open ' + c.k)))}">
        <div class="ceo-kpi-head">
          <span class="ceo-kpi-lbl"><i class="ceo-kpi-ico" aria-hidden="true">${ic(c.icon || 'overview')}</i><span class="k">${esc(cleanCeoText(c.k))}</span></span>
          ${c.badge ? `<span class="ceo-kpi-pill ${esc(c.badgeTone || 'brass')}">${esc(cleanCeoText(c.badge))}</span>` : ''}
        </div>
        <div class="ceo-kpi-val-row">
          <span class="v num">${cleanCeoText(c.v)}</span>${c.subVal ? `<small class="ceo-kpi-subval">${cleanCeoText(c.subVal)}</small>` : ''}
        </div>
        ${meterHtml}
        <span class="d ${esc(c.cls || 'good')}">${cleanCeoText(c.d)}</span>
      </div>`;
  }

  function renderCeoPnlBridge(bridge) {
    if (!bridge || !Array.isArray(bridge.steps) || !bridge.steps.length) return '';
    return `
      <div class="ceo-pnl-bridge">
        <div class="ceo-bridge-hdr">
          <span class="ceo-bridge-title">${esc(cleanCeoText(bridge.title || 'Consolidated P&L Value Bridge'))}</span>
          <div class="ceo-bridge-hdr-actions">
            ${bridge.meta ? `<span class="ceo-bridge-meta">${esc(cleanCeoText(bridge.meta))}</span>` : ''}
            <button type="button" class="ceo-variance-brief-btn ceo-whatif-btn" id="ceoWhatIfBtn" data-whatif-open="1" data-wi-source="overview" aria-expanded="false" title="Open Interactive What-If Margin, FX & Working-Capital Scenario Simulator">${ic('sliders')}<span class="ceo-wi-lbl">What-If Studio</span></button>
            <button type="button" class="ceo-variance-brief-btn ceo-collection-btn" id="ceoCollectionForecastBtn" data-collection-forecast-open="1" data-cf-source="overview" aria-expanded="false" title="Open Counterparty Payment-Behavior & Cash-Collection Forecast Studio">${ic('customers')}<span class="ceo-cf-lbl">Collection Forecast</span></button>
            <button type="button" class="ceo-variance-brief-btn ceo-payables-btn" id="ceoPayablesOptimizerBtn" data-payables-optimizer-open="1" data-po-source="overview" aria-expanded="false" title="Open Supplier Payables, 3-Leg Cash-Outflow & Early-Settlement Optimizer Studio">${ic('suppliers')}<span class="ceo-po-lbl">Payables Optimizer</span></button>
            <button type="button" class="ceo-variance-brief-btn ceo-treasury-btn" id="ceoTreasuryForecastBtn" data-treasury-forecast-open="1" data-tf-source="overview" aria-expanded="false" data-ui-tip="Open Rolling 13-Week Cash-Flow & Liquidity Runway Forecast Studio">${ic('cashflow')}<span class="ceo-tf-lbl">13W Runway</span></button>
            <button type="button" class="ceo-variance-brief-btn ceo-inventory-btn" id="ceoInventoryOptimizerBtn" data-inventory-optimizer-open="1" data-io-source="overview" aria-expanded="false" data-ui-tip="Open Inventory Turnover, Stock Reorder & Working-Capital Carrying-Cost Studio">${ic('warehouse')}<span class="ceo-io-lbl">Stock &amp; EOQ</span></button>
            <button type="button" class="ceo-variance-brief-btn" id="ceoVarianceBriefBtn" data-ceo-variance-brief="1" aria-expanded="false" title="Open grounded Period Variance Commentary">${ic('sparkles')}<span class="ceo-vb-lbl">Variance</span></button>
            <button type="button" class="ceo-period-summary-btn" id="ceoPeriodSummaryBtn" data-ceo-period-summary="1" aria-pressed="false" title="Play a spoken summary of the active period's P&L bridge, prior-period variance, cash till, and active Sentinel flags">${ic('audio')}<span class="ceo-ps-lbl">Listen to Period Summary</span></button>
          </div>
        </div>
        <div class="ceo-bridge-grid">
          ${bridge.steps.map(st => {
            const pct = Math.max(4, Math.min(100, Number(st.barPct || 0)));
            return `
              <div class="ceo-bridge-step${st.isFinal ? ' is-final' : ''}${st.jump ? ' kpi-link' : ''}" ${st.jump ? `data-nav-jump="${esc(st.jump)}" role="button" tabindex="0"` : ''}>
                <div class="ceo-bridge-top">
                  <span class="ceo-bridge-lbl">${st.op ? `<b class="ceo-bridge-op">${esc(st.op)}</b> ` : ''}${esc(cleanCeoText(st.label))}</span>
                  <span class="ceo-bridge-pct ${esc(st.pctTone || '')}">${esc(cleanCeoText(st.pctTxt || ''))}</span>
                </div>
                <div class="ceo-bridge-val num">${cleanCeoText(st.valHtml)}</div>
                <div class="ceo-bridge-track" aria-hidden="true"><span class="ceo-bridge-fill ${esc(st.barTone || 'cobalt')}" style="width:${pct.toFixed(1)}%"></span></div>
                ${st.sub ? `<div class="ceo-bridge-sub">${esc(cleanCeoText(st.sub))}</div>` : ''}
              </div>`;
          }).join('')}
        </div>
      </div>`;
  }

  function resolveCeoPriorPeriodWindow(curRange, pRaw) {
    if (!curRange || !curRange.from || !curRange.to) return null;
    const fp = formatDateSegParts(curRange.from, MIN_DATE);
    const tp = formatDateSegParts(curRange.to, MAX_DATE);
    const pStr = String(pRaw || '');
    if (pStr.startsWith('year:') || (fp.mm === '01' && fp.dd === '01' && tp.mm === '12' && tp.dd === '31' && fp.yrNum === tp.yrNum)) {
      const prevYr = Math.max(2023, fp.yrNum - 1);
      return {
        periodSpec: `year:${prevYr}`,
        from: `${prevYr}-01-01`,
        to: `${prevYr}-12-31`,
        label: `FY ${prevYr}`,
        grain: 'year'
      };
    }
    const lastDayCur = lastDayOfMonth(tp.yrNum, tp.moNum);
    if (pStr.startsWith('month:') || pStr === 'mtd' || pStr === 'prev_m1' || pStr === 'prev_m2'
      || (fp.yrNum === tp.yrNum && fp.moNum === tp.moNum && fp.dd === '01' && tp.dayNum === lastDayCur)) {
      const totMo = fp.yrNum * 12 + (fp.moNum - 1) - 1;
      const py = Math.floor(totMo / 12);
      const pm = (totMo % 12) + 1;
      const pmStr = String(pm).padStart(2, '0');
      const pld = String(lastDayOfMonth(py, pm)).padStart(2, '0');
      return {
        periodSpec: `month:${py}-${pmStr}`,
        from: `${py}-${pmStr}-01`,
        to: `${py}-${pmStr}-${pld}`,
        label: `${MONTH_LONG[pm - 1] || 'Month'} ${py}`,
        grain: 'month'
      };
    }
    if (pStr.startsWith('day:') || curRange.from === curRange.to) {
      const prevMs = Date.UTC(fp.yrNum, fp.moNum - 1, fp.dayNum) - 86400000;
      const pIso = new Date(prevMs).toISOString().slice(0, 10);
      return {
        periodSpec: `day:${pIso}`,
        from: pIso,
        to: pIso,
        label: fmtDayLabel(pIso),
        grain: 'day'
      };
    }
    const startMs = Date.UTC(fp.yrNum, fp.moNum - 1, fp.dayNum);
    const endMs = Date.UTC(tp.yrNum, tp.moNum - 1, tp.dayNum);
    const spanMs = Math.max(86400000, (endMs - startMs) + 86400000);
    const prevEndMs = startMs - 86400000;
    const prevStartMs = prevEndMs - (spanMs - 86400000);
    const pfIso = new Date(prevStartMs).toISOString().slice(0, 10);
    const ptIso = new Date(prevEndMs).toISOString().slice(0, 10);
    const isWeek = pStr.startsWith('week:') || pStr === 'wtd' || pStr === 'last_week' || Math.round(spanMs / 86400000) === 7;
    return {
      periodSpec: isWeek ? `week:${pfIso}..${ptIso}` : 'custom',
      from: pfIso,
      to: ptIso,
      label: isWeek ? `Week ${cleanCeoText(fmtWeekLabel(pfIso, ptIso))}` : `${pfIso} to ${ptIso}`,
      grain: isWeek ? 'week' : 'custom'
    };
  }

  function evalMfgKpiWindow(coKey, periodSpec, fromIso, toIso) {
    const savedP = STATE.period;
    const savedF = STATE.dateFrom;
    const savedT = STATE.dateTo;
    let k = {};
    try {
      STATE.period = periodSpec || 'all';
      if (periodSpec === 'custom') {
        STATE.dateFrom = fromIso || '';
        STATE.dateTo = toIso || '';
      } else if (!periodSpec || periodSpec === 'all') {
        STATE.dateFrom = '';
        STATE.dateTo = '';
      }
      k = getKPI(coKey) || {};
    } finally {
      STATE.period = savedP;
      STATE.dateFrom = savedF;
      STATE.dateTo = savedT;
    }
    const revUsd = round2(Number(STATE.basis === 'rep' ? (k.sales_rep_date != null ? k.sales_rep_date : k.sales_ttc) : k.sales_ttc) || 0);
    const netSalesUsd = round2(Number(k.net_sales != null ? k.net_sales : revUsd) || 0);
    const directCostUsd = round2(Number(STATE.basis === 'rep' ? (k.raw_rep_date != null ? k.raw_rep_date : k.raw_cost) : k.raw_cost) || 0);
    const grossMarginUsd = round2(Number(k.gross_margin != null ? k.gross_margin : (netSalesUsd - directCostUsd)) || 0);
    const opProfitUsd = round2(Number(STATE.basis === 'rep' ? (k.op_profit_rep_date != null ? k.op_profit_rep_date : k.operating_profit) : k.operating_profit) || 0);
    const expRaw = round2(Number(STATE.basis === 'rep' ? (k.exp_rep_date != null ? k.exp_rep_date : k.expenses) : k.expenses) || 0);
    const opExUsd = round2(Math.max(0, round2(grossMarginUsd - opProfitUsd)) || expRaw);
    const clampPct = v => Math.max(-100, Math.min(100, round2(Number(v) || 0)));
    const den = Math.max(1, Math.abs(netSalesUsd || revUsd));
    const gmPct = (netSalesUsd || revUsd) > 0 ? clampPct((grossMarginUsd / den) * 100) : 0;
    const opMarginPct = (netSalesUsd || revUsd) > 0 ? clampPct((opProfitUsd / den) * 100) : 0;
    return {
      revUsd,
      netSalesUsd,
      directCostUsd,
      grossMarginUsd,
      gmPct,
      opExUsd,
      opProfitUsd,
      opMarginPct,
      txCount: Math.round(Number(k.loads || 0)),
      cashTillUsd: round2(Number(k.cash_till_usd != null ? k.cash_till_usd : k.cash_till) || 0),
      arBalanceUsd: round2(Number(k.ar_balance || 0)),
      arOverdueUsd: round2(Math.max(0, Number(k.ar_overdue || 0))),
      hasActivity: Math.abs(revUsd) > 0.01 || Math.abs(directCostUsd) > 0.01 || Math.abs(opExUsd) > 0.01
    };
  }

  function computeCeoPeriodBridgeSnapshot(coOverride, periodOverride) {
    ensureMultiIndustrySpineSeeded();
    const coKey = coOverride || STATE.company || 'manufacturing-group';
    const ind = getActiveIndustry(coKey) || 'Manufacturing';
    const rawPeriod = periodOverride !== undefined ? periodOverride : STATE.period;
    const curRange = periodRange(rawPeriod);
    const prevWin = curRange ? resolveCeoPriorPeriodWindow(curRange, rawPeriod) : null;
    const periodLabel = curRange ? cleanCeoText(curRange.label || `${curRange.from} to ${curRange.to}`) : 'All-Time';
    const grain = !curRange ? 'all' : (prevWin ? prevWin.grain : (STATE.dateGrain || 'month'));

    const clampPct = v => Math.max(-100, Math.min(100, round2(Number(v) || 0)));
    const bridgeUser = typeof activeUser === 'function' ? activeUser() : null;
    const bridgeLens = seatLens(bridgeUser);
    const redactBridgeWin = w => {
      if (!w) return w;
      const out = Object.assign({}, w);
      if (out.latestWindow) out.latestWindow = redactBridgeWin(out.latestWindow);
      if (!bridgeLens.expenses && !bridgeLens.profit) out.opExUsd = null;
      if (!bridgeLens.profit) {
        out.directCostUsd = null;
        out.grossMarginUsd = null;
        out.gmPct = null;
        out.opProfitUsd = null;
        out.opMarginPct = null;
        if (!bridgeLens.tax) out.netSalesUsd = out.revUsd;
      }
      if (!bridgeLens.books) {
        out.cashTillUsd = null;
      }
      return out;
    };
    const todayYm = String(todayISO() || '').slice(0, 7);
    const allSn = bridgeLens.sentinels ? (buildSentinelItems() || []) : [];
    const openSn = allSn.filter(s => s && s.severity && s.severity !== 'ok');
    const critSn = openSn.filter(s => s.severity === 'crit');

    if (ind === 'Manufacturing') {
      const effCo = (!modelHasLedger(coKey) && coKey === 'lionstransport') ? 'manufacturing-group' : coKey;
      const cur = evalMfgKpiWindow(effCo, curRange ? (rawPeriod === 'all' ? 'custom' : rawPeriod) : 'all', curRange ? curRange.from : '', curRange ? curRange.to : '');
      let prev = null;
      let compareLabel = '';
      if (prevWin) {
        prev = evalMfgKpiWindow(effCo, prevWin.periodSpec, prevWin.from, prevWin.to);
        compareLabel = prevWin.label;
      } else {
        const m = SEED.models[resolveEffectiveModelKey(effCo)] || SEED.models['manufacturing-group'] || {};
        const ymStr = r => {
          const rawYm = String((r && (r.YearMonthNo || r['Year Month'])) || '');
          const mHit = rawYm.match(/(20\d{2})[-/]?(\d{2})/);
          return mHit ? `${mHit[1]}-${mHit[2]}` : '';
        };
        const mosRaw = getScopedMonthly(m.monthly || [], 24).filter(r => Number(STATE.basis === 'rep' ? (r.sales_rep || r.sales_ttc || 0) : (r.sales_ttc || 0)) > 0 && ymStr(r));
        const mosDone = todayYm ? mosRaw.filter(r => ymStr(r) < todayYm) : mosRaw;
        const mos = mosDone.length >= 2 ? mosDone : mosRaw;
        if (mos.length >= 2) {
          const lastM = mos[mos.length - 1];
          const prevM = mos[mos.length - 2];
          const ymCur = ymStr(lastM);
          const ymPrev = ymStr(prevM);
          if (ymCur && ymPrev) {
            const mCurSnap = evalMfgKpiWindow(effCo, `month:${ymCur}`, '', '');
            const mPrevSnap = evalMfgKpiWindow(effCo, `month:${ymPrev}`, '', '');
            prev = Object.assign({}, mPrevSnap, { isMomentumPair: true, latestWindow: mCurSnap, latestLabel: cleanCeoText((periodRange(`month:${ymCur}`) || {}).label || ymCur) });
            compareLabel = cleanCeoText((periodRange(`month:${ymPrev}`) || {}).label || ymPrev);
          }
        }
      }
      const mModel = SEED.models[resolveEffectiveModelKey(effCo)] || SEED.models['manufacturing-group'] || {};
      const topCust = getScopedModelCustomers(mModel).filter(c => Number(c.sales_ttc || 0) > 0).sort((a, b) => Number(b.sales_ttc || 0) - Number(a.sales_ttc || 0))[0];
      const topProd = getScopedModelProducts(mModel).filter(p => Number(p.sales_ttc || 0) > 0).sort((a, b) => Number(b.sales_ttc || 0) - Number(a.sales_ttc || 0))[0];
      return {
        industry: ind,
        company: coKey,
        companyLabel: cleanCeoText(COMPANY_LABELS[coKey] || ind),
        grain,
        basis: STATE.basis || 'tx',
        periodKey: String(rawPeriod || 'all'),
        periodLabel,
        compareLabel,
        isAllTime: !curRange,
        cur: redactBridgeWin(cur),
        prev: redactBridgeWin(prev),
        books: bridgeLens.books ? { cashTillUsd: cur.cashTillUsd, arBalanceUsd: cur.arBalanceUsd, arOverdueUsd: cur.arOverdueUsd } : null,
        topDriver: topCust ? { kind: 'client', name: cleanCeoText(topCust.Customer), usd: round2(Number(topCust.sales_ttc || 0)), secondary: topProd ? cleanCeoText(topProd.Product) : '' } : null,
        sentinels: bridgeLens.sentinels ? { openCount: openSn.length, critCount: critSn.length, topTitle: openSn[0] ? cleanCeoText(openSn[0].title || '') : '' } : null
      };
    }

    // Sibling Industries 2..6: All-Time exact bridge + Dated Window Slicer
    const kSnap = getIndustryKpiSnapshot(ind, coKey, {});
    const buMatch = COMPANY_BU_MATCH[coKey] || '';
    const matchBu = rowCo => {
      if (!buMatch || String(coKey).startsWith('industry:') || coKey === 'holding') return true;
      return String(rowCo || '').trim().toLowerCase() === String(buMatch).trim().toLowerCase();
    };
    const expRowsAll = filterRecords(SEED.records.expenses || [], { ignorePeriod: true, ignoreSearch: true, tableKey: 'expenses' }).filter(r => matchBu(r.company));

    const datedEvents = []; // { date, rev, net, direct, opex, tx }
    const addEv = (dt, rev, net, direct, opex, tx = 0) => {
      const iso = String(dt || '').slice(0, 10);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return;
      datedEvents.push({
        date: iso,
        ym: iso.slice(0, 7),
        rev: Number(rev || 0),
        net: Number(net != null ? net : rev || 0),
        direct: Number(direct || 0),
        opex: Number(opex || 0),
        tx: Number(tx || 0)
      });
    };

    let allTimeBridge = null;
    let topDriver = null;
    let annualContractedRent = 0;
    let annualDirectRatio = 0.25;
    let annualOpexRatio = 0.08;

    if (ind === 'Holding & Treasury') {
      const rollup = computeEnterpriseRollup();
      const { totals, icRes, byIndustry } = rollup;
      const revUsd = round2(Number(totals.sales_ttc || 0));
      const netSalesUsd = round2(Number(totals.net_sales || revUsd));
      const directCostUsd = round2(Math.max(0, Number(totals.raw_cost || 0)));
      const grossMarginUsd = round2(Number(totals.gross_margin || (netSalesUsd - directCostUsd)));
      const opExUsd = round2(Math.max(0, Number(totals.expenses || 0) + Number(totals.salaries || 0)));
      const opProfitUsd = round2(Number(totals.operating_profit || (grossMarginUsd - opExUsd)));
      const revBase = netSalesUsd || revUsd;
      const den = Math.max(1, revBase);
      allTimeBridge = {
        revUsd, netSalesUsd, directCostUsd, grossMarginUsd,
        gmPct: revBase > 0 ? clampPct((grossMarginUsd / den) * 100) : 0,
        opExUsd, opProfitUsd,
        opMarginPct: revBase > 0 ? clampPct((opProfitUsd / den) * 100) : 0,
        txCount: Math.round(Number(icRes.matchedCount || totals.loads || 0)),
        cashTillUsd: kSnap.till_tracked === false ? null : round2(Number(totals.cash_till || 0)),
        arBalanceUsd: round2(Number(totals.ar_balance || 0)),
        arOverdueUsd: round2(Number(icRes.totalNetUnpaidUsd || 0)),
        hasActivity: true
      };
      const ic = computeIntercompanyInteractions({ ignoreSearch: true });
      (ic.events || []).forEach(ev => {
        if (ev && ev.date) {
          if (ev.side === 'In') addEv(ev.date, ev.usd, ev.usd, 0, 0, 1);
          else addEv(ev.date, 0, 0, ev.usd, 0, 0);
        }
      });
      topDriver = { kind: 'sector', name: 'Manufacturing', usd: round2(Number(byIndustry.mfg && byIndustry.mfg.sales_ttc || 0)), secondary: 'Hospitality & Resorts' };
    } else if (ind === 'Hospitality & Resorts') {
      const hsp = computeHospitalityOperations({ company: coKey, ignoreSearch: true });
      const s = hsp.summary;
      const totRev = round2(s.totalRevenueTtc + s.totalMemContract);
      const totHt = round2(s.totalRevenueHt + s.totalMemContract);
      const directCostUsd = round2(s.totalStockUsage);
      const grossMarginUsd = round2(totHt - directCostUsd);
      const opExUsd = round2(s.totalMaintUsd);
      const opProfitUsd = round2(grossMarginUsd - opExUsd);
      const revBase = totHt || totRev;
      const den = Math.max(1, revBase);
      annualDirectRatio = revBase > 0 ? Math.min(0.65, Math.max(0.18, directCostUsd / den)) : 0.30;
      allTimeBridge = {
        revUsd: totRev, netSalesUsd: totHt, directCostUsd, grossMarginUsd,
        gmPct: revBase > 0 ? clampPct((grossMarginUsd / den) * 100) : 0,
        opExUsd, opProfitUsd,
        opMarginPct: revBase > 0 ? clampPct((opProfitUsd / den) * 100) : 0,
        txCount: Math.round((hsp.venueRows || []).length + (hsp.membershipRows || []).length),
        cashTillUsd: kSnap.till_tracked === false ? null : round2(Number(kSnap.cash_till || 0)),
        arBalanceUsd: round2(Number(s.totalMemArrears || 0)),
        arOverdueUsd: round2(Number(s.totalMemArrears || 0)),
        hasActivity: true
      };
      (hsp.venueRows || []).forEach(r => addEv(r.date, r.ttc_usd, r.ht_usd != null ? r.ht_usd : r.ttc_usd, 0, 0, 1));
      (hsp.stockRows || []).forEach(r => addEv(r.date, 0, 0, r.recipe_usage_usd, 0, 0));
      (hsp.maintRows || []).forEach(r => addEv(r.date, 0, 0, 0, r.cost_usd, 0));
      const topMem = (hsp.membershipRows || []).slice().sort((a, b) => Number(b.contract_usd || 0) - Number(a.contract_usd || 0))[0];
      topDriver = topMem ? { kind: 'member', name: cleanCeoText(topMem.member), usd: round2(Number(topMem.contract_usd || 0)), secondary: cleanCeoText(topMem.company || '') } : null;
    } else if (ind === 'Automotive & Heavy Trading') {
      const trd = computeTradingOperations({ company: coKey, ignoreSearch: true });
      const s = trd.summary;
      const revUsd = round2(s.totalSalesTtc);
      const netSalesUsd = round2(s.totalSalesNet || revUsd);
      const directCostUsd = round2(s.totalSalesCost);
      const grossMarginUsd = round2(s.totalSalesMargin);
      const opExUsd = round2(s.totalLandedAddUsd * 0.35);
      const opProfitUsd = round2(grossMarginUsd - opExUsd);
      const revBase = revUsd || netSalesUsd;
      const den = Math.max(1, revBase);
      allTimeBridge = {
        revUsd, netSalesUsd, directCostUsd, grossMarginUsd,
        gmPct: revBase > 0 ? clampPct(Number(s.avgMarginPct || ((grossMarginUsd / den) * 100))) : 0,
        opExUsd, opProfitUsd,
        opMarginPct: revBase > 0 ? clampPct((opProfitUsd / den) * 100) : 0,
        txCount: (trd.salesRows || []).filter(r => !r.is_gap).length,
        cashTillUsd: kSnap.till_tracked === false ? null : round2(Number(kSnap.cash_till || 0)),
        arBalanceUsd: round2(Number(s.grossArUsd || 0)),
        arOverdueUsd: round2(Math.max(0, Number(s.grossArUsd || 0) - Number(s.activePromisesUsd || 0))),
        hasActivity: true
      };
      (trd.salesRows || []).filter(r => !r.is_gap).forEach(r => addEv(r.date, r.ttc_usd, r.net_usd || r.ttc_usd, r.cost_usd, 0, 1));
      (trd.importRows || []).forEach(r => addEv(r.date, 0, 0, 0, Number(r.landed_add_usd || 0) * 0.35, 0));
      const topBuyer = (trd.receivableRows || []).slice().sort((a, b) => Number(b.gross_ar_usd || 0) - Number(a.gross_ar_usd || 0))[0];
      topDriver = topBuyer ? { kind: 'buyer', name: cleanCeoText(topBuyer.customer), usd: round2(Number(topBuyer.gross_ar_usd || 0)), secondary: cleanCeoText(topBuyer.company || '') } : null;
    } else if (ind === 'Real Estate & Property') {
      const re = computeRealEstateOperations({ company: coKey, ignoreSearch: true });
      const s = re.summary;
      const revUsd = round2(s.contractedAnnualRentUsd);
      const directCostUsd = round2(s.woActualUsd);
      const grossMarginUsd = round2(revUsd - directCostUsd);
      const opExUsd = round2(s.woActualUsd * 0.25);
      const opProfitUsd = round2(grossMarginUsd - opExUsd);
      const den = Math.max(1, revUsd);
      annualContractedRent = revUsd;
      annualDirectRatio = revUsd > 0 ? Math.min(0.45, directCostUsd / den) : 0.12;
      annualOpexRatio = revUsd > 0 ? Math.min(0.20, opExUsd / den) : 0.04;
      allTimeBridge = {
        revUsd, netSalesUsd: revUsd, directCostUsd, grossMarginUsd,
        gmPct: revUsd > 0 ? clampPct((grossMarginUsd / den) * 100) : 0,
        opExUsd, opProfitUsd,
        opMarginPct: revUsd > 0 ? clampPct((opProfitUsd / den) * 100) : 0,
        txCount: (re.leases || []).length,
        cashTillUsd: kSnap.till_tracked === false ? null : round2(Number(kSnap.cash_till || 0)),
        arBalanceUsd: round2(Number(s.openRentArUsd || 0) + Number(s.salesOpenUsd || 0)),
        arOverdueUsd: round2(Number(s.openRentArUsd || 0)),
        hasActivity: true
      };
      (re.invoices || []).forEach(r => addEv(r.date, r.amount_ttc_usd, r.amount_ht_usd || r.amount_ttc_usd, 0, 0, 1));
      (re.sales || []).forEach(r => addEv(r.date, r.paid_usd || r.contract_usd, r.paid_usd || r.contract_usd, 0, 0, 1));
      (re.workorders || []).forEach(r => addEv(r.date, 0, 0, r.actual_usd, Number(r.actual_usd || 0) * 0.25, 0));
      const topLease = (re.leases || []).slice().sort((a, b) => Number(b.annual_ttc_usd || 0) - Number(a.annual_ttc_usd || 0))[0];
      topDriver = topLease ? { kind: 'tenant', name: cleanCeoText(topLease.tenant), usd: round2(Number(topLease.annual_ttc_usd || 0)), secondary: cleanCeoText(topLease.property || '') } : null;
    } else {
      // Insurance & Brokerage
      const ins = computeInsuranceOperations();
      const s = ins.summary;
      const grossComm = round2(s.grossComm7063Usd + s.policyFees7064Usd);
      const rebates = round2(s.discount7065Usd);
      const netRev = round2(s.netCommUsd + s.policyFees7064Usd);
      const opExUsd = 11400;
      const opProfitUsd = round2(netRev - opExUsd);
      const revBase = grossComm || netRev;
      const den = Math.max(1, revBase);
      allTimeBridge = {
        revUsd: round2(s.gwpUsd),
        netSalesUsd: netRev,
        directCostUsd: rebates,
        grossMarginUsd: netRev,
        gmPct: revBase > 0 ? clampPct((netRev / den) * 100) : 0,
        opExUsd,
        opProfitUsd,
        opMarginPct: netRev > 0 ? clampPct((opProfitUsd / Math.max(1, netRev)) * 100) : 0,
        txCount: Math.round(Number(s.totalPolicyCount || (ins.policies || []).length)),
        cashTillUsd: kSnap.till_tracked === false ? null : round2(Number(kSnap.cash_till || 0)),
        arBalanceUsd: round2(Number(s.openClientAr4112Usd || 0)),
        arOverdueUsd: 0,
        hasActivity: true
      };
      (ins.policies || []).forEach(p => {
        const netC = Number(p.net_comm_usd || 0) + Number(p.policy_fee_usd || 0);
        addEv(p.date, p.gross_prem_usd, netC, p.discount_usd || 0, 0, 1);
      });
      const topPol = (ins.policies || []).slice().sort((a, b) => Number(b.gross_prem_usd || 0) - Number(a.gross_prem_usd || 0))[0];
      topDriver = topPol ? { kind: 'insured', name: cleanCeoText(topPol.client), usd: round2(Number(topPol.gross_prem_usd || 0)), secondary: cleanCeoText(topPol.carrier || '') } : null;
    }

    expRowsAll.forEach(r => addEv(r.date || r.rep_date, 0, 0, 0, r.total_ttc || r.amount || 0, 0));

    const sliceSiblingWindow = (winSpec) => {
      if (!winSpec || !winSpec.from || !winSpec.to) return allTimeBridge;
      const fIso = winSpec.from;
      const tIso = winSpec.to;
      if (ind === 'Holding & Treasury') {
        const mfgSub = evalMfgKpiWindow('manufacturing-group', winSpec.periodSpec || 'custom', fIso, tIso);
        const subEvs = datedEvents.filter(e => e.date >= fIso && e.date <= tIso);
        const icIn = round2(subEvs.reduce((a, e) => a + e.rev, 0));
        const icOut = round2(subEvs.reduce((a, e) => a + e.direct, 0));
        const extraOp = round2(subEvs.reduce((a, e) => a + e.opex, 0));
        const revUsd = round2(mfgSub.revUsd + icIn);
        const netSalesUsd = round2(mfgSub.netSalesUsd + icIn);
        const directCostUsd = round2(mfgSub.directCostUsd + icOut * 0.4);
        const grossMarginUsd = round2(netSalesUsd - directCostUsd);
        const opExUsd = round2(mfgSub.opExUsd + extraOp);
        const opProfitUsd = round2(grossMarginUsd - opExUsd);
        const den = Math.max(1, Math.abs(netSalesUsd || revUsd));
        return {
          revUsd, netSalesUsd, directCostUsd, grossMarginUsd,
          gmPct: (netSalesUsd || revUsd) > 0 ? clampPct((grossMarginUsd / den) * 100) : 0,
          opExUsd, opProfitUsd,
          opMarginPct: (netSalesUsd || revUsd) > 0 ? clampPct((opProfitUsd / den) * 100) : 0,
          txCount: mfgSub.txCount + subEvs.reduce((a, e) => a + e.tx, 0),
          cashTillUsd: allTimeBridge.cashTillUsd,
          arBalanceUsd: allTimeBridge.arBalanceUsd,
          arOverdueUsd: allTimeBridge.arOverdueUsd,
          hasActivity: mfgSub.hasActivity || subEvs.length > 0
        };
      }
      const hits = datedEvents.filter(e => e.date >= fIso && e.date <= tIso);
      const fp = formatDateSegParts(fIso, MIN_DATE);
      const tp = formatDateSegParts(tIso, MAX_DATE);
      const spanDays = Math.max(1, Math.round((Date.UTC(tp.yrNum, tp.moNum - 1, tp.dayNum) - Date.UTC(fp.yrNum, fp.moNum - 1, fp.dayNum)) / 86400000) + 1);
      let revUsd = round2(hits.reduce((a, e) => a + e.rev, 0));
      let netSalesUsd = round2(hits.reduce((a, e) => a + e.net, 0));
      let directCostUsd = round2(hits.reduce((a, e) => a + e.direct, 0));
      let opExUsd = round2(hits.reduce((a, e) => a + e.opex, 0));
      let txCount = hits.reduce((a, e) => a + e.tx, 0);

      if (ind === 'Real Estate & Property' && revUsd <= 0 && annualContractedRent > 0 && spanDays >= 7 && fIso >= '2025-01-01' && fIso <= '2027-12-31') {
        revUsd = round2(annualContractedRent * (spanDays / 365));
        netSalesUsd = revUsd;
        if (directCostUsd <= 0) directCostUsd = round2(revUsd * annualDirectRatio);
        if (opExUsd <= 0) opExUsd = round2(revUsd * annualOpexRatio);
        txCount = allTimeBridge.txCount;
      } else if (ind === 'Hospitality & Resorts' && revUsd > 0 && directCostUsd <= 0) {
        directCostUsd = round2(netSalesUsd * annualDirectRatio);
      } else if (ind === 'Insurance & Brokerage' && (revUsd > 0 || netSalesUsd > 0) && opExUsd <= 0) {
        opExUsd = round2(11400 * Math.min(1, spanDays / 365));
      }

      const grossMarginUsd = ind === 'Insurance & Brokerage'
        ? netSalesUsd
        : round2((netSalesUsd || revUsd) - directCostUsd);
      const opProfitUsd = round2(grossMarginUsd - opExUsd);
      const den = Math.max(1, Math.abs(netSalesUsd || revUsd));
      return {
        revUsd,
        netSalesUsd: netSalesUsd || revUsd,
        directCostUsd,
        grossMarginUsd,
        gmPct: (netSalesUsd || revUsd) > 0 ? clampPct((grossMarginUsd / den) * 100) : 0,
        opExUsd,
        opProfitUsd,
        opMarginPct: (netSalesUsd || revUsd) > 0 ? clampPct((opProfitUsd / den) * 100) : 0,
        txCount,
        cashTillUsd: allTimeBridge.cashTillUsd,
        arBalanceUsd: allTimeBridge.arBalanceUsd,
        arOverdueUsd: allTimeBridge.arOverdueUsd,
        hasActivity: hits.length > 0 || revUsd > 0
      };
    };

    const cur = curRange
      ? sliceSiblingWindow({ periodSpec: rawPeriod, from: curRange.from, to: curRange.to })
      : allTimeBridge;
    let prev = null;
    let compareLabel = '';
    if (prevWin) {
      prev = sliceSiblingWindow(prevWin);
      compareLabel = prevWin.label;
    } else {
      const rawYms = Array.from(new Set(datedEvents.filter(e => e.rev > 0).map(e => e.ym))).sort();
      const doneYms = todayYm ? rawYms.filter(ym => ym < todayYm) : rawYms;
      const activeYms = doneYms.length >= 2 ? doneYms : rawYms;
      if (activeYms.length >= 2) {
        const ymCur = activeYms[activeYms.length - 1];
        const ymPrev = activeYms[activeYms.length - 2];
        const rCur = periodRange(`month:${ymCur}`);
        const rPrev = periodRange(`month:${ymPrev}`);
        if (rCur && rPrev) {
          const mCurSnap = sliceSiblingWindow({ periodSpec: `month:${ymCur}`, from: rCur.from, to: rCur.to });
          const mPrevSnap = sliceSiblingWindow({ periodSpec: `month:${ymPrev}`, from: rPrev.from, to: rPrev.to });
          prev = Object.assign({}, mPrevSnap, { isMomentumPair: true, latestWindow: mCurSnap, latestLabel: cleanCeoText(rCur.label || ymCur) });
          compareLabel = cleanCeoText(rPrev.label || ymPrev);
        }
      }
    }

    return {
      industry: ind,
      company: coKey,
      companyLabel: cleanCeoText(COMPANY_LABELS[coKey] || ind),
      grain,
      basis: STATE.basis || 'tx',
      periodKey: String(rawPeriod || 'all'),
      periodLabel,
      compareLabel,
      isAllTime: !curRange,
      cur: redactBridgeWin(cur),
      prev: redactBridgeWin(prev),
      books: bridgeLens.books ? { cashTillUsd: cur.cashTillUsd, arBalanceUsd: cur.arBalanceUsd, arOverdueUsd: cur.arOverdueUsd } : null,
      topDriver,
      sentinels: bridgeLens.sentinels ? { openCount: openSn.length, critCount: critSn.length, topTitle: openSn[0] ? cleanCeoText(openSn[0].title || '') : '' } : null
    };
  }

  function renderCeoPulseDeck(pulse) {
    const activeTab = ['attention', 'clients', 'mix'].includes(STATE.ceoPulseTab) ? STATE.ceoPulseTab : 'attention';
    const tabs = [
      { id: 'attention', label: cleanCeoText(pulse.attTabLabel || 'Attention'), badge: cleanCeoText(pulse.attBadge || '') },
      { id: 'clients', label: cleanCeoText(pulse.clientsTabLabel || 'Top Clients') },
      { id: 'mix', label: cleanCeoText(pulse.mixTabLabel || 'Revenue Mix') }
    ];
    const rows = activeTab === 'clients' ? (pulse.clientRows || []) : (activeTab === 'mix' ? (pulse.mixRows || []) : (pulse.attentionRows || []));
    const footLeft = cleanCeoText(activeTab === 'clients' ? (pulse.clientsFootLeft || '') : (activeTab === 'mix' ? (pulse.mixFootLeft || '') : (pulse.attFootLeft || '')));
    const footJump = activeTab === 'clients' ? (pulse.clientsJump || 'customers') : (activeTab === 'mix' ? (pulse.mixJump || 'pricing') : (pulse.attJump || 'sentinels'));
    const footJumpLbl = cleanCeoText(activeTab === 'clients' ? (pulse.clientsJumpLbl || 'All Clients') : (activeTab === 'mix' ? (pulse.mixJumpLbl || 'Full Breakdown') : (pulse.attJumpLbl || 'All Sentinels')));

    return `
      <div class="ceo-pulse-deck" id="ceoPulseDeck">
        <div class="ceo-pulse-hdr">
          <div class="ceo-pulse-title-wrap">
            <span class="ceo-pulse-title">${esc(cleanCeoText(pulse.title || 'Executive Pulse'))}</span>
            <span class="ceo-pulse-sub">${esc(cleanCeoText(activeTab === 'clients' ? (pulse.clientsSub || 'Concentration & AR exposure') : (activeTab === 'mix' ? (pulse.mixSub || 'Top revenue & margin drivers') : (pulse.attSub || 'Priority watchdogs & approvals'))))}</span>
          </div>
          <div class="ceo-pulse-tabs" role="tablist" aria-label="Executive Pulse Lenses">
            ${tabs.map(t => `
              <button type="button" role="tab" aria-selected="${activeTab === t.id ? 'true' : 'false'}" class="ceo-pulse-tab${activeTab === t.id ? ' active' : ''}" data-ceo-pulse-tab="${t.id}">${esc(t.label)}${t.badge ? `<i class="ceo-tab-cnt">${esc(t.badge)}</i>` : ''}</button>
            `).join('')}
          </div>
        </div>
        <div class="ceo-pulse-list">
          ${rows.slice(0, 4).map(r => {
            if (r.kind === 'bar') {
              const pct = Math.max(3, Math.min(100, Number(r.pct || 0)));
              return `
                <div class="ceo-pulse-row is-bar-row${r.jump ? ' kpi-link' : ''}" ${r.jump ? `data-nav-jump="${esc(r.jump)}" role="button" tabindex="0"` : ''}>
                  <span class="ceo-pr-rank">${esc(String(r.rank || ''))}</span>
                  <div class="ceo-pr-main">
                    <div class="ceo-pr-top">
                      <span class="ceo-pr-name">${r.nameHtml ? cleanCeoText(r.nameHtml) : `<b${r.noI18nName ? ' data-no-i18n="1"' : ''}>${esc(cleanCeoText(r.name || ''))}</b>`}</span>
                      <span class="ceo-pr-val num"><b>${esc(cleanCeoText(r.val || ''))}</b>${r.shareTxt ? `<small>${esc(cleanCeoText(r.shareTxt))}</small>` : ''}</span>
                    </div>
                    <div class="ceo-pr-bar-row">
                      <div class="ceo-hbar-track" aria-hidden="true"><span class="ceo-hbar-fill ${esc(r.barTone || 'cobalt')}" style="width:${pct.toFixed(1)}%"></span></div>
                      <span class="ceo-pr-meta"${r.noI18nMeta ? ' data-no-i18n="1"' : ''}>${r.metaHtml ? cleanCeoText(r.metaHtml) : esc(cleanCeoText(r.meta || ''))}</span>
                    </div>
                  </div>
                </div>`;
            }
            return `
              <div class="ceo-pulse-row is-att-row${r.jump ? ' kpi-link' : ''}" ${r.jump ? `data-nav-jump="${esc(r.jump)}" role="button" tabindex="0"` : ''}>
                <span class="ceo-att-dot ${esc(r.tone || 'good')}" aria-hidden="true">${ic(r.icon || (r.tone === 'crit' || r.tone === 'warn' ? 'warn' : 'check_circle'))}</span>
                <div class="ceo-pr-main">
                  <div class="ceo-pr-name"><b>${esc(cleanCeoText(r.title || ''))}</b></div>
                  <div class="ceo-pr-sub">${esc(cleanCeoText(r.detail || ''))}</div>
                </div>
                <span class="ceo-att-pill ${esc(r.tone || 'good')}">${esc(cleanCeoText(r.pill || 'Inspect'))}</span>
              </div>`;
          }).join('')}
        </div>
        <div class="ceo-pulse-foot">
          <span class="ceo-pf-note">${esc(footLeft)}</span>
          <button type="button" class="btn-ghost-bar ceo-pf-btn" data-nav-jump="${esc(footJump)}">${esc(footJumpLbl)}</button>
        </div>
      </div>`;
  }

