              sub: `USD Rem <b>${fmtUSD(sumRemUsd, 2)}</b> · LBP Rem <b>${fmtNum(sumRemLbp, 0)} LL</b> · Book paid <b>${fmtUSD(k.salaries_paid, 0)}</b>`,
              tone: 'brass'
