        const usd = isCfg ? round2(numVal('ide_usd')) : Math.max(0, round2(numVal('ide_usd')));
        const lbp = isCfg ? Math.round(numVal('ide_lbp')) : Math.max(0, Math.round(numVal('ide_lbp')));
        const dt = strVal('ide_date') || today;
