            physValEn = `${fmtNum(trdSum.invoiceGapCount || 0, 0)} Gaps`;
            physValAr = `${fmtNum(trdSum.invoiceGapCount || 0, 0)} فجوات`;
            physValFr = `${fmtNum(trdSum.invoiceGapCount || 0, 0)} sauts`;
