        canViewBooks: false,
        canViewExp: false,
        canViewProfit: false,
        canViewSentinels: false,
        industry: safeInd,
        industryAr: indLoc.ar,
        industryFr: indLoc.fr,
        companyKey: STATE.company || 'wtc',
        company: safeCo,
        companyEn: locCo(safeCo, 'en'),
