  function normalizeCompaniesScope(cStr) {
    const names = parseUserCompanies(cStr);
    const hasWtc = names.some(x => /^WTC$/i.test(x));
    const hasBbc = names.some(x => /^BBConstruction$/i.test(x));
    const hasLt = names.some(x => /^Lions\s*Transport$/i.test(x));
    const extra = names.filter(x => !/^(WTC|BBConstruction|Lions\s*Transport)$/i.test(x));
    if (!extra.length) {
      if (hasWtc && hasBbc && hasLt) return 'WTC, BBConstruction, Lions Transport';
      if (hasWtc && hasBbc) return 'WTC, BBConstruction';
      if (hasLt && hasWtc) return 'Lions Transport, WTC';
      if (hasBbc && hasLt) return 'BBConstruction, Lions Transport';
      if (hasBbc) return 'BBConstruction';
      if (hasLt) return 'Lions Transport';
      return 'WTC';
    }
    return names.join(', ');
  }

  function formatCompactCompaniesBadge(cStr, maxShown = 3) {
    const names = parseUserCompanies(cStr);
    const catalog = getCompanyCatalog();
    const byName = new Map(catalog.map(c => [c.name.toLowerCase(), c]));
    const indSet = new Set();
    names.forEach(n => {
      const hit = byName.get(String(n || '').toLowerCase());
      indSet.add((hit && hit.industry) || inferIndustryForCompany(n));
    });
    const indCount = Math.max(1, indSet.size);
    const fullTitle = `${names.length} ${names.length === 1 ? 'Company' : 'Companies'} (${indCount} ${indCount === 1 ? 'Industry' : 'Industries'}): ${names.join(', ')}`;
    if (names.length <= maxShown) {
      return { text: names.join(', '), shownNames: names.slice(), extraCount: 0, indCount, fullTitle, totalCount: names.length };
    }
    const extraCount = names.length - maxShown;
    return {
      text: `${names.slice(0, maxShown).join(', ')} +${extraCount} more`,
      shownNames: names.slice(0, maxShown),
      extraCount,
      indCount,
      fullTitle,
      totalCount: names.length
    };
  }

  function renderCompanyMultiSelectChipsHtml(selected) {
    if (!selected || !selected.length) {
      return '<span class="hint" style="color:var(--crit)">No company selected: pick at least 1 company</span>';
    }
    const maxChips = 8;
    const shown = selected.slice(0, maxChips);
    const extra = selected.length - shown.length;
    return shown.map(name => `
      <span class="co-multi-chip" data-co-chip="${esc(name)}">
        <span>${esc(name)}</span>
        <button type="button" class="stm-exc-chip-rm" data-remove-co="${esc(name)}" data-ui-tip="Remove company" aria-label="Remove company">${ic('trash')}</button>
      </span>
    `).join('') + (extra > 0 ? `<span class="co-multi-chip co-multi-chip-more"><span>+${extra} more selected</span></span>` : '');
  }

  function formatCompanySummaryLabel(selected, totalCount, indCount) {
    if (!selected || !selected.length) return 'Select 1 or more companies…';
    const indSuffix = indCount && indCount > 1 ? ` · ${indCount} Ind` : '';
    if (totalCount > 1 && selected.length === totalCount) {
      return `All ${totalCount} Companies${indSuffix} (${selected.slice(0, 3).join(' · ')}${selected.length > 3 ? ' +' + (selected.length - 3) + ' more' : ''})`;
    }
    if (selected.length <= 3) return selected.join(' + ') + indSuffix;
    return `${selected.slice(0, 2).join(', ')} + ${selected.length - 2} more${indSuffix}`;
  }

  function renderCompanyMultiSelectHtml(selectedRaw) {
    const catalog = getCompanyCatalog();
    const indGroups = getIndustryGroups(catalog);
    const selected = parseUserCompanies(selectedRaw);
    const selSet = new Set(selected.map(s => s.toLowerCase()));
    const selIndSet = new Set();
    catalog.forEach(c => { if (selSet.has(c.name.toLowerCase())) selIndSet.add(c.industry || 'Manufacturing'); });
    const summaryLbl = formatCompanySummaryLabel(selected, catalog.length, selIndSet.size);
    return `
      <div class="co-multi-select" id="nuCompanySelector" data-active-ind="all">
        <input type="hidden" id="nu_companies" value="${esc(selected.join(', '))}">
        <button type="button" class="co-multi-trigger" id="nuCompanyTrigger" aria-haspopup="listbox" aria-expanded="false">
          <span class="co-multi-trigger-summary" id="nuCompanySummaryText">${esc(summaryLbl)}</span>
          <span class="co-multi-trigger-meta">
            <span class="co-multi-count-pill" id="nuCompanyCountPill">${selected.length} / ${catalog.length} selected</span>
            <span class="co-multi-caret" aria-hidden="true">▾</span>
          </span>
        </button>
        <div class="co-multi-chips" id="nuCompanyChips">
          ${renderCompanyMultiSelectChipsHtml(selected)}
        </div>
        <div class="co-multi-popover" id="nuCompanyPopover" hidden>
          <div class="co-multi-toolbar">
            <input type="search" id="nuCompanySearch" class="co-multi-search" placeholder="Search ${catalog.length} companies across ${indGroups.length} ${indGroups.length === 1 ? 'industry' : 'industries'}..." autocomplete="off">
            <div class="co-multi-actions">
              <button type="button" class="co-multi-act-btn" id="nuCompanySelectAllBtn">Select All (${catalog.length})</button>
              <button type="button" class="co-multi-act-btn" id="nuCompanyClearBtn">Clear</button>
            </div>
          </div>
          <div class="co-multi-body">
            <div class="co-multi-ind-col" id="nuCompanyIndustryBar" role="tablist" aria-label="Filter by Industry">
              <button type="button" class="co-multi-ind-tab active" data-ind-tab="all">
                <span class="co-multi-ind-tab-lbl">All Industries</span>
                <em class="co-multi-ind-tab-cnt" data-ind-cnt="all">${selected.length}/${catalog.length}</em>
              </button>
              ${indGroups.map(g => {
                const selInG = g.companies.filter(c => selSet.has(c.name.toLowerCase())).length;
                return `
                  <button type="button" class="co-multi-ind-tab" data-ind-tab="${esc(g.id)}">
                    <span class="co-multi-ind-tab-lbl">${esc(g.label)}</span>
                    <em class="co-multi-ind-tab-cnt" data-ind-cnt="${esc(g.id)}">${selInG}/${g.companies.length}</em>
                  </button>
                `;
              }).join('')}
            </div>
            <div class="co-multi-list" id="nuCompanyList" role="listbox" aria-multiselectable="true">
              ${indGroups.map(g => {
                const selInG = g.companies.filter(c => selSet.has(c.name.toLowerCase())).length;
                const allInG = selInG === g.companies.length && g.companies.length > 0;
                return `
                  <div class="co-multi-ind-hdr" data-ind-hdr="${esc(g.id)}">
                    <div class="co-multi-ind-hdr-left">
                      <span class="co-multi-ind-code">${esc(g.code)}</span>
                      <b>${esc(g.label)}</b>
                      <small data-ind-hdr-count="${esc(g.id)}">${selInG} of ${g.companies.length} selected</small>
                    </div>
                    <button type="button" class="co-multi-ind-toggle" data-toggle-industry="${esc(g.id)}">${allInG ? 'Clear Industry' : `Select All (${g.companies.length})`}</button>
                  </div>
                  ${g.companies.map(co => {
                    const checked = selSet.has(co.name.toLowerCase());
                    const indName = co.industry || g.id || 'Manufacturing';
                    return `
                      <label class="co-multi-opt ${checked ? 'is-checked' : ''}" data-co-opt="${esc(co.name)}" data-co-ind="${esc(indName)}" data-co-search="${esc((co.name + ' ' + co.label + ' ' + co.sector + ' ' + indName + ' ' + co.key).toLowerCase())}">
                        <input type="checkbox" class="co-multi-cb" value="${esc(co.name)}" data-cb-ind="${esc(indName)}" ${checked ? 'checked' : ''}>
                        <span class="co-multi-opt-body">
                          <b>${esc(co.name)}</b>
                          <small>${esc(indName)} · ${esc(co.sector || co.label)}</small>
                        </span>
                        <span class="co-multi-opt-tag">${esc(co.key.toUpperCase().slice(0, 8))}</span>
                      </label>
                    `;
                  }).join('')}
                `;
              }).join('')}
            </div>
          </div>
          <div class="co-multi-foot">
            <span id="nuCompanyFootStatus">${selected.length} of ${catalog.length} ${catalog.length === 1 ? 'company' : 'companies'} assigned across ${indGroups.length} ${indGroups.length === 1 ? 'industry' : 'industries'}</span>
            <button type="button" class="btn btn-brass" style="padding:2px 9px;font-size:10.5px" id="nuCompanyDoneBtn">Done</button>
          </div>
        </div>
      </div>
    `;
  }

  function seatAccessValue(u) {
    if (!u) return 'partial|partial';
    if (String(u.pbi_access || '') === 'custom' || String(u.statements_access || '') === 'custom') return 'custom|custom';
    const v = `${u.pbi_access || 'partial'}|${u.statements_access || 'partial'}`;
    return SEAT_ACCESS_OPTIONS.some(o => o.value === v) ? v : 'partial|partial';
  }

  function seatAccessMeta(u) {
    const v = seatAccessValue(u);
    if (v === 'custom|custom' && u) {
      const m = countPermissionMetrics(getEffectivePermissions(u), u);
      return {
        value: 'custom|custom',
        label: 'Custom Dashboards & Statements (Granular Matrix)',
        short: `Custom (${m.pbiPageCount}/${m.pbiPageTotal} Dash · ${m.stmtCount}/22 Stmt)`,
        badgeCls: 'badge-brass'
      };
    }
    return SEAT_ACCESS_OPTIONS.find(o => o.value === v) || SEAT_ACCESS_OPTIONS[3];
  }

  function getEditingSeatUser() {
    if (STATE.editingUserId === '__new__') return null;
    const hit = STATE.users.find(u => u && String(u.id) === String(STATE.editingUserId));
    return hit || STATE.users[STATE.activeUserIdx] || STATE.users[0] || null;
  }

  function getDraftSeatPreviewUser(editUser, curRole, curCompanies, curAccess) {
    const resolvedUser = editUser !== undefined ? editUser : getEditingSeatUser();
    const resolvedRole = curRole || STATE.draftRoleOverride || val('nu_role') || (resolvedUser ? resolvedUser.role : 'Entry') || 'Entry';
    const resolvedCompanies = curCompanies || STATE.draftCompaniesOverride || val('nu_companies') || (resolvedUser ? resolvedUser.companies : 'WTC') || 'WTC';
    const resolvedAccess = curAccess || STATE.draftAccessOverride || val('nu_access') || (resolvedUser ? seatAccessValue(resolvedUser) : 'partial|partial') || 'partial|partial';
    const accParts = String(resolvedAccess).split('|');
    const sameRoleAsSaved = !resolvedUser || resolveCanonicalRoleKey(resolvedRole) === resolveCanonicalRoleKey(resolvedUser.role);
    const baseCustom = STATE.draftCustomPerms || ((resolvedUser && sameRoleAsSaved) ? parseUserCustomPerms(resolvedUser.custom_perms) : {});
    return {
      id: resolvedUser ? resolvedUser.id : '__new__',
      full_name: resolvedUser ? resolvedUser.full_name : 'New Team Seat',
      role: resolvedRole,
      companies: resolvedCompanies,
      pbi_access: accParts[0] || 'partial',
      statements_access: accParts[1] || 'partial',
      custom_perms: baseCustom
    };
  }

  function buildRoleCapabilityBreakdown(previewUser) {
    const perms = getEffectivePermissions(previewUser);
    const m = countPermissionMetrics(perms, previewUser);
    const accVal = seatAccessValue(previewUser);
    const accMeta = seatAccessMeta(previewUser);
    const defaultRoleAcc = perms.preset.defaultAccess || 'partial|partial';
    const hpPolicy = getEffectiveHubPagePolicy(previewUser);
    const isModifiedScope = Boolean((!perms.isCustomRole && accVal !== defaultRoleAcc && accVal !== 'custom|custom') || (hpPolicy && hpPolicy.customized));
    const canEnter = !!(perms.rights.enter_dispatch || perms.rights.enter_accounting || perms.rights.enter_master || perms.rights.enter_payroll_jv);
    const isEntryRole = perms.roleKey === 'Entry';
    const canPendingPrice = !!(perms.rights.modify_data || perms.rights.enter_dispatch || isEntryRole);
    const enterDesc = (perms.rights.enter_dispatch && perms.rights.enter_payroll_jv)
      ? 'All Forms'
      : (isEntryRole
          ? 'Ops & Till'
          : (perms.rights.enter_dispatch ? 'Ops & Billing' : (perms.rights.enter_accounting ? 'Sales & AR' : 'Read-Only')));
    const capabilities = [
      { key: 'ops', label: 'Ops & Payroll', allowed: !!perms.rights.read_ops, state: perms.rights.read_ops ? 'Allowed' : 'Hidden' },
      { key: 'fin', label: isEntryRole ? 'GL & Sentinels' : 'GL & Accounting', allowed: !!perms.rights.read_fin, state: perms.rights.read_fin ? 'Allowed' : 'Restricted' },
      { key: 'enter', label: 'Create & Post', allowed: canEnter, state: enterDesc },
      {
        key: 'modify',
        label: 'Modify Records',
        allowed: !!(perms.rights.modify_data || perms.rights.modify_text || canPendingPrice),
        partial: !perms.rights.modify_data && !!(perms.rights.modify_text || canPendingPrice),
        state: perms.rights.modify_data
          ? 'Full Modify'
          : (perms.rights.modify_text ? 'Words Only' : (canPendingPrice ? 'Pending Only' : 'Locked'))
      },
      { key: 'void', label: 'Void / Delete', allowed: !!perms.rights.void_data, state: perms.rights.void_data ? 'Allowed' : 'Locked' },
      {
        key: 'unlocks',
        label: 'Field Overrides',
        allowed: m.unlockCount > 0,
        partial: m.unlockCount > 0 && m.unlockCount < m.unlockTotal,
        state: m.unlockCount === m.unlockTotal
          ? `All ${m.unlockTotal} Free`
          : (m.unlockCount > 0 ? `${m.unlockCount}/${m.unlockTotal} Free` : 'PIN Req')
      }
    ];
    const seatInd = previewUser ? getSeatPrimaryIndustry(previewUser) : getActiveIndustry(STATE.company);
    const prevCapEvalInd = STATE._permEvalInd;
    let hubs = [];
    try {
      STATE._permEvalInd = seatInd || 'Manufacturing';
      hubs = (typeof HUB_CATALOG !== 'undefined'
        ? HUB_CATALOG.filter(h => isHubInActiveIndustry(h, seatInd))
        : []).map(h => {
        const vis = canViewHub(h.id, previewUser);
        const totalPages = (h.tabs || []).length;
        const onPages = vis ? (h.tabs || []).filter(t => canViewView(t.view, previewUser)).length : 0;
        return {
          id: h.id,
          title: h.title,
          visible: vis,
          onPages,
          totalPages
        };
      });
    } finally {
      STATE._permEvalInd = prevCapEvalInd;
    }
    const dashSuites = PERM_CATALOG.dashboards.map(d => ({
      id: d.id,
      short: DASH_SUITE_SHORT_NAMES[d.id] || d.label,
      on: !!perms.dashboards[d.id],
      count: d.count
    }));
    const stmtSuites = PERM_CATALOG.statements.map(s => ({
      id: s.id,
      short: STMT_SUITE_SHORT_NAMES[s.id] || s.label,
      on: !!perms.statements[s.id],
      count: s.count
    }));
    const scopeShortLbl = (perms.isCustomRole || accVal === 'custom|custom')
      ? `${m.pbiPageCount}/${m.pbiPageTotal} Dash · ${m.stmtCount}/${m.stmtTotal} Stmt`
      : accMeta.short;
    return {
      perms,
      m,
      accVal,
      accMeta,
      defaultRoleAcc,
      isModifiedScope,
      canEnter,
      capabilities,
      hubs,
      dashSuites,
      stmtSuites,
      scopeShortLbl
    };
  }

  function renderRoleTriggerInnerHtml(previewUser) {
    const b = buildRoleCapabilityBreakdown(previewUser);
    const roleTitle = b.perms.preset.shortTitle || b.perms.preset.title;
    const pillText = b.perms.isCustomRole ? 'Custom Matrix' : (b.isModifiedScope ? 'Custom Scope' : 'Preset');
    const pillCls = (b.perms.isCustomRole || b.isModifiedScope) ? 'is-custom' : '';
    return `
      <span class="role-perm-trigger-main" id="nuRoleSummaryText">
        <strong>${esc(roleTitle)}</strong>
        <span class="rp-trig-sep">·</span>
        <span class="rp-trig-scope">${esc(b.scopeShortLbl)}</span>
      </span>
      <span class="role-perm-trigger-meta">
        <span class="role-perm-mode-pill ${pillCls}" id="nuRoleTierPill">${esc(pillText)}</span>
        <span class="co-multi-caret" aria-hidden="true">▾</span>
      </span>
    `;
  }

  function renderRolePostureStripHtml(previewUser) {
    const b = buildRoleCapabilityBreakdown(previewUser);
    const { perms, m, canEnter } = b;
    const actionSummary = canEnter
      ? (perms.rights.modify_data && perms.rights.void_data
          ? '✓ Create · Modify · Void'
          : (perms.rights.modify_data
              ? '✓ Create & Modify'
              : (perms.rights.modify_text
                  ? (perms.roleKey === 'Entry' ? '✓ Create · Edit Words Only (No Numbers)' : '✓ Create & Edit Words Only')
                  : (perms.roleKey === 'Entry' ? '✓ Create · Payroll · Till · Pending Prices' : '✓ Create Only'))))
      : (perms.rights.void_data ? 'Read & Void Only' : (perms.rights.modify_text ? 'Read & Edit Words Only' : 'Read-Only'));
    const unlockSummary = m.unlockCount === m.unlockTotal
      ? `✓ All ${m.unlockTotal} Overrides`
      : (m.unlockCount > 0 ? `${ic('unlock')} ${m.unlockCount}/${m.unlockTotal} Overrides` : `${ic('lock')} PIN Required`);
    return `
      <button type="button" class="role-posture-pill interactive ${canEnter || perms.rights.void_data ? 'on' : 'off'}" data-role-chip-jump="rights">${actionSummary}</button>
      <button type="button" class="role-posture-pill interactive ${m.unlockCount ? 'brass' : 'off'}" data-role-chip-jump="unlocks">${unlockSummary}</button>
      <button type="button" class="role-posture-pill interactive ${m.pbiPageCount ? 'on' : 'off'}" data-role-chip-jump="dashboards">${m.hubCount} Hubs · ${m.pbiPageCount}/${m.pbiPageTotal} Dash</button>
      <button type="button" class="role-posture-pill interactive ${m.stmtCount ? 'on' : 'off'}" data-role-chip-jump="statements">${m.stmtCount}/${m.stmtTotal} Statements</button>
    `;
  }

  function buildPreviewUserForRoleKey(roleKey, baseCompanies, currentAccess, isSelectedRole) {
    const canonical = resolveCanonicalRoleKey(roleKey);
    const preset = ROLE_PRESETS[canonical] || ROLE_PRESETS['Entry'];
    if (isSelectedRole) {
      return getDraftSeatPreviewUser(undefined, canonical === 'Custom' ? 'Custom' : roleKey, baseCompanies, currentAccess);
    }
    const accStr = canonical === 'Custom' ? 'custom|custom' : (preset.defaultAccess || 'partial|partial');
    const [pTier, sTier] = accStr.split('|');
    return {
      id: '__preview__',
      full_name: preset.shortTitle || preset.title,
      role: canonical === 'Custom' ? 'Custom' : roleKey,
      companies: baseCompanies || val('nu_companies') || 'WTC, BBConstruction, Lions Transport',
      pbi_access: pTier || 'partial',
      statements_access: sTier || 'partial',
      custom_perms: canonical === 'Custom' ? (STATE.draftCustomPerms || {}) : {}
    };
  }

  function renderRolePopoverPreviewHtml(previewUser, opts = {}) {
    const b = buildRoleCapabilityBreakdown(previewUser);
    const { perms, m, accVal, defaultRoleAcc, capabilities, hubs, dashSuites, stmtSuites } = b;
    const isPreviewOnly = !!opts.isPreviewOnly;
    const visibleHubCount = hubs.filter(h => h.visible).length;
    const quickScopes = [
      { value: 'full|full', label: 'Full Executive' },
      { value: 'full|partial', label: 'All Dash + Ops Stmt' },
      { value: 'partial|full', label: 'Ops Dash + All Stmt' },
      { value: 'partial|partial', label: 'Operational Only' },
      { value: 'none|partial', label: 'Statements Only' },
      { value: 'none|none', label: 'No Reports' },
      { value: 'custom|custom', label: 'Custom Matrix' }
    ];
    return `
      <div class="rp-preview-hdr">
        <div class="rp-preview-title-row">
          <strong class="rp-preview-title">${esc(perms.preset.shortTitle || perms.preset.title)}</strong>
          <span class="badge ${isPreviewOnly ? 'badge-brass' : perms.preset.badgeCls}">${isPreviewOnly ? 'HOVER PREVIEW · CLICK TO SELECT' : 'SELECTED ROLE'}</span>
        </div>
        <p class="rp-preview-desc">${esc(perms.preset.summary)}</p>
      </div>

      <div class="rp-cap-grid">
        ${capabilities.map(c => `
          <div class="rp-cap-item ${c.allowed ? (c.partial ? 'is-partial' : 'is-on') : 'is-off'}">
            <span class="rp-cap-icon" aria-hidden="true">${c.allowed ? '✓' : '✕'}</span>
            <span class="rp-cap-lbl">${esc(c.label)}</span>
            <em class="rp-cap-state">${esc(c.state)}</em>
          </div>
        `).join('')}
      </div>

      <div class="rp-hubs-block">
        <div class="rp-sec-lbl">
          <span>Sidebar Navigation (${visibleHubCount}/${hubs.length} Hubs · ${m.hubPageCount}/${m.hubPageTotal} Pages)</span>
          ${!isPreviewOnly
            ? `<button type="button" class="rp-reset-scope-btn" data-open-hub-pages-matrix="1">${ic('sliders')} Select Tabs &amp; Pages</button>`
            : `<span>${m.tableCount}/${m.tableTotal} Tables</span>`}
        </div>
        <div class="rp-hub-tags">
          ${hubs.map(h => `
            <span class="rp-hub-tag ${h.visible ? 'on' : 'off'}">
              <i>${h.visible ? '✓' : '✕'}</i>${esc(h.title)}${h.totalPages > 1 ? ` <small>(${h.onPages}/${h.totalPages})</small>` : ''}
            </span>
          `).join('')}
        </div>
      </div>

      <div class="rp-reports-box">
        <div class="rp-sec-lbl">
          <span>Dashboards &amp; Statements (${m.pbiPageCount}/${m.pbiPageTotal} Dash · ${m.stmtCount}/${m.stmtTotal} Stmt)</span>
          ${!isPreviewOnly && !perms.isCustomRole && accVal !== defaultRoleAcc
            ? `<button type="button" class="rp-reset-scope-btn" data-quick-access="${esc(defaultRoleAcc)}">Reset to Role Default</button>`
            : `<span class="rp-scope-mode-note">${perms.isCustomRole ? 'Granular Custom Matrix' : (accVal === defaultRoleAcc ? 'Role Default' : 'Custom Scope')}</span>`}
        </div>
        <div class="rp-suite-tags">
          ${dashSuites.map(d => `<span class="rp-suite-tag ${d.on ? 'on' : 'off'}"><i>${d.on ? '✓' : '✕'}</i>${esc(d.short)}</span>`).join('')}
          ${stmtSuites.map(s => `<span class="rp-suite-tag stmt ${s.on ? 'on' : 'off'}"><i>${s.on ? '✓' : '✕'}</i>${esc(s.short)}</span>`).join('')}
        </div>
        ${!isPreviewOnly ? `
          <div class="rp-quick-scopes" role="group" aria-label="Dashboard and statement scope">
            ${quickScopes.map(qs => {
              const active = accVal === qs.value || (perms.isCustomRole && qs.value === 'custom|custom');
              const isDef = !perms.isCustomRole && qs.value === defaultRoleAcc;
              return `<button type="button" class="rp-scope-pill ${active ? 'active' : ''}" data-quick-access="${esc(qs.value)}">${esc(qs.label)}${isDef ? ' · Default' : ''}</button>`;
            }).join('')}
          </div>
        ` : ''}
      </div>
    `;
  }

  function renderRolePermSelectorHtml(previewUser, curRole, curAccess) {
    const canonicalCur = resolveCanonicalRoleKey(curRole);
    return `
      <div class="role-perm-select" id="nuRolePermsSelector">
        <select id="nu_role" data-native-select="1" hidden>
          ${SEAT_ROLE_OPTIONS.map(o => `<option value="${esc(o.value)}" ${resolveCanonicalRoleKey(curRole) === resolveCanonicalRoleKey(o.value) ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}
        </select>
        <select id="nu_access" data-native-select="1" hidden>
          ${SEAT_ACCESS_OPTIONS.map(o => `<option value="${esc(o.value)}" ${curAccess === o.value ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}
        </select>
        <button type="button" class="role-perm-trigger" id="nuRoleTrigger" aria-haspopup="dialog" aria-expanded="false">
          ${renderRoleTriggerInnerHtml(previewUser)}
        </button>
        <div class="role-posture-strip" id="nuRolePostureStrip">
          ${renderRolePostureStripHtml(previewUser)}
        </div>
        <div class="role-perm-popover" id="nuRolePopover" hidden>
          <div class="role-perm-popover-body">
            <div class="role-perm-opt-col" role="listbox" aria-label="Select Role">
              <div class="role-perm-col-hdr">Select Role · Hover to Preview</div>
              ${SEAT_ROLE_OPTIONS.map(o => {
                const isSel = canonicalCur === resolveCanonicalRoleKey(o.value);
                return `
                  <button type="button" class="role-perm-opt ${isSel ? 'is-selected is-preview' : ''}" role="option" aria-selected="${isSel ? 'true' : 'false'}" data-role-opt="${esc(o.value)}">
                    <span class="role-perm-opt-copy">
                      <b>${esc(o.label)}</b>
                      <small>${esc(o.sub)}</small>
                    </span>
                    <span class="role-perm-opt-check" aria-hidden="true">${isSel ? '✓' : '›'}</span>
                  </button>
                `;
              }).join('')}
            </div>
            <div class="role-perm-preview-col" id="nuRolePreviewPane">
              ${renderRolePopoverPreviewHtml(previewUser, { isPreviewOnly: false })}
            </div>
          </div>
          <div class="role-perm-foot">
            <button type="button" class="role-perm-custom-btn" id="nuRoleOpenMatrixBtn">${ic('sliders')} Customize Granular Permissions</button>
            <button type="button" class="btn btn-brass" style="padding:3px 11px;font-size:11px" id="nuRoleDoneBtn">Done</button>
          </div>
        </div>
      </div>
    `;
  }

  let _roleHoverHideTimer = null;
  let _roleHoverAnchor = null;

  function ensureRoleHoverCardEl() {
    let el = document.getElementById('roleHoverPreviewCard');
    if (!el) {
      el = document.createElement('div');
      el.id = 'roleHoverPreviewCard';
      el.className = 'role-hover-card';
      el.setAttribute('role', 'region');
      el.setAttribute('aria-label', 'Role and permissions breakdown');
      el.hidden = true;
      el.addEventListener('mouseenter', () => {
        if (_roleHoverHideTimer) { clearTimeout(_roleHoverHideTimer); _roleHoverHideTimer = null; }
      });
      el.addEventListener('mouseleave', () => {
        hideRoleHoverCard(false);
      });
      el.addEventListener('click', e => {
        const closeBtn = e.target && e.target.closest ? e.target.closest('[data-hover-close]') : null;
        if (closeBtn) {
          e.stopPropagation();
          hideRoleHoverCard(true);
          return;
        }
        const quickRoleBtn = e.target && e.target.closest ? e.target.closest('[data-hover-quick-role]') : null;
        if (quickRoleBtn) {
          e.stopPropagation();
          if (!isOwner()) return;
          const targetUid = quickRoleBtn.getAttribute('data-hover-uid') || '';
          const nextRole = quickRoleBtn.getAttribute('data-hover-quick-role') || 'Entry';
          const u = STATE.users.find(x => String(x.id) === String(targetUid));
          if (!u) return;
          if (resolveCanonicalRoleKey(nextRole) === 'Custom') {
            hideRoleHoverCard(true);
            selectSeatForEdit(u.id, { scroll: true, openPerms: true, permTab: 'all' });
            const roleEl = document.getElementById('nu_role');
            if (roleEl && roleEl.value !== 'Custom') {
              roleEl.value = 'Custom';
              roleEl.dispatchEvent(new Event('change', { bubbles: true }));
            }
            return;
          }
          const canon = resolveCanonicalRoleKey(nextRole);
          const preset = ROLE_PRESETS[canon] || ROLE_PRESETS['Entry'];
          const [pTier, sTier] = String(preset.defaultAccess || 'partial|partial').split('|');
          u.role = nextRole;
          u.pbi_access = pTier || 'partial';
          u.statements_access = sTier || 'partial';
          u.seat_updated_at = new Date().toISOString();
          saveLocalAuthAndRecords();
          if (hasServerApi() && !isDemoScopeActive()) { try { edgeApiFetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: u }) }).catch(() => {}); } catch (_) {} }
          syncWithCloud(true);
          if (STATE.showAddUserForm && String(STATE.editingUserId) === String(u.id)) {
            STATE.draftRoleOverride = u.role;
            STATE.draftAccessOverride = `${u.pbi_access}|${u.statements_access}`;
            updateSeatEditorDom();
          } else {
            const tbody = $('usersDirectoryTbody');
            if (tbody) {
              tbody.innerHTML = renderUsersDirectoryRowsHtml();
              wireUsersDirectoryActions(tbody);
            }
          }
          const newAnchor = document.querySelector('#usersDirectoryTbody [data-role-hover-user="' + u.id + '"]') || _roleHoverAnchor;
          if (newAnchor) showRoleHoverCard(newAnchor, u, { seatName: u.full_name, userId: u.id, focusCat: 'all' });
          toast(`Updated ${u.full_name} · ${preset.shortTitle || preset.title}`);
          return;
        }
        const quickAccBtn = e.target && e.target.closest ? e.target.closest('[data-hover-quick-access]') : null;
        if (quickAccBtn) {
          e.stopPropagation();
          if (!isOwner()) return;
          const targetUid = quickAccBtn.getAttribute('data-hover-uid') || '';
          const nextAcc = quickAccBtn.getAttribute('data-hover-quick-access') || 'partial|partial';
          const u = STATE.users.find(x => String(x.id) === String(targetUid));
          if (!u) return;
          const [pTier, sTier] = String(nextAcc).split('|');
          if (resolveCanonicalRoleKey(u.role) === 'Custom') {
            const cp = parseUserCustomPerms(u.custom_perms);
            cp.dashboards = dashboardsFromAccessTier(pTier || 'partial');
            cp.statements = statementsFromAccessTier(sTier || 'partial');
            u.custom_perms = JSON.stringify(cp);
          } else {
            u.pbi_access = pTier || 'partial';
            u.statements_access = sTier || 'partial';
          }
          u.seat_updated_at = new Date().toISOString();
          saveLocalAuthAndRecords();
          if (hasServerApi() && !isDemoScopeActive()) { try { edgeApiFetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: u }) }).catch(() => {}); } catch (_) {} }
          syncWithCloud(true);
          if (STATE.showAddUserForm && String(STATE.editingUserId) === String(u.id)) {
            STATE.draftAccessOverride = `${u.pbi_access}|${u.statements_access}`;
            updateSeatEditorDom();
          } else {
            const tbody = $('usersDirectoryTbody');
            if (tbody) {
              tbody.innerHTML = renderUsersDirectoryRowsHtml();
              wireUsersDirectoryActions(tbody);
            }
          }
          const newAnchor = document.querySelector('#usersDirectoryTbody [data-role-hover-user="' + u.id + '"]') || _roleHoverAnchor;
          if (newAnchor) showRoleHoverCard(newAnchor, u, { seatName: u.full_name, userId: u.id, focusCat: 'all' });
          toast(`Updated report scope for ${u.full_name}`);
          return;
        }
        const btn = e.target && e.target.closest ? e.target.closest('[data-hover-open-perms]') : null;
        if (!btn) return;
        e.stopPropagation();
        const targetUid = btn.getAttribute('data-hover-open-perms');
        const targetTab = btn.getAttribute('data-hover-perm-tab') || 'all';
        hideRoleHoverCard(true);
        if (!isOwner()) return;
        if (targetUid && targetUid !== '__draft__') {
          selectSeatForEdit(targetUid, { scroll: true, openPerms: true, permTab: targetTab });
        } else {
          STATE.showRolePermMatrix = true;
          STATE.permMatrixTab = targetTab;
          refreshRoleAndAccessMatrixUi($('seatEditorWrap') || document);
          const mw = $('rolePermissionsMatrixWrap');
          if (mw) scrollWorkspaceTo(mw);
        }
      });
      document.body.appendChild(el);
    }
    return el;
  }

  function getSeatRoleTierMeta(perms) {
    if (!perms) return { tierCls: 'tier-entry', icon: ic('edit') };
    if (perms.isCustomRole) return { tierCls: 'tier-custom', icon: ic('sliders') };
    const rk = perms.roleKey;
    if (rk === 'Full Access (Owner)') return { tierCls: 'tier-owner', icon: ic('shield') };
    if (rk === 'Supervisor + Entry') return { tierCls: 'tier-sup-entry', icon: ic('check_circle') };
    if (rk === 'Supervisor') return { tierCls: 'tier-supervisor', icon: ic('check_circle') };
    if (rk === 'Sales') return { tierCls: 'tier-sales', icon: ic('pricing') };
    return { tierCls: 'tier-entry', icon: ic('edit') };
  }

  function getSeatMonogram(fullName) {
    const clean = String(fullName || '').replace(/\([^)]*\)/g, '').trim();
    const parts = clean.split(/\s+/).filter(w => /[a-z0-9]/i.test(w));
    if (!parts.length) return 'US';
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }

  function renderRoleHoverCardBodyHtml(userObj, opts = {}) {
    const b = buildRoleCapabilityBreakdown(userObj);
    const { perms, m, accVal, capabilities, hubs, dashSuites, stmtSuites, scopeShortLbl } = b;
    const owner = isOwner(activeUser());
    const visibleHubs = hubs.filter(h => h.visible);
    const hiddenHubs = hubs.filter(h => !h.visible);
    const seatName = opts.seatName || (userObj && userObj.id && userObj.id !== '__preview__' && userObj.id !== '__new__' ? userObj.full_name : '');
    const actionUid = opts.userId || '';
    const focusCat = opts.focusCat || 'all';
    const isRealSeat = Boolean(owner && actionUid && actionUid !== '__draft__' && actionUid !== '__preview__' && actionUid !== '__new__');
    const tierMeta = getSeatRoleTierMeta(perms);
    const initials = getSeatMonogram(seatName || perms.preset.shortTitle || perms.preset.title);
    const tagline = perms.preset.tagline || perms.preset.summary;
    const quickRoles = [
      { key: 'Entry', label: 'Entry' },
      { key: 'Supervisor', label: 'Supervisor' },
      { key: 'Supervisor + Entry', label: 'Sup+Entry' },
      { key: 'Full Access (Owner)', label: 'Admin' },
      { key: 'Sales', label: 'Sales/AR' },
      { key: 'Custom', label: 'Custom' }
    ];
    const quickScopes = [
      { value: 'full|full', label: 'Full Exec' },
      { value: 'full|partial', label: 'All Dash' },
      { value: 'partial|full', label: 'All Stmt' },
      { value: 'partial|partial', label: 'Ops Only' },
      { value: 'none|partial', label: 'Stmt Only' },
      { value: 'none|none', label: 'None' }
    ];
    return `
      <div class="rhc-head ${tierMeta.tierCls}">
        <div class="rhc-identity">
          <span class="user-dir-avatar rhc-avatar ${tierMeta.tierCls}" aria-hidden="true">${esc(initials)}</span>
          <div class="rhc-title-wrap">
            <div class="rhc-title-row">
              ${seatName ? `<strong class="rhc-seat-name">${esc(seatName)}</strong>` : ''}
              <span class="urp-role-pill ${tierMeta.tierCls}"><i class="urp-role-ico" aria-hidden="true">${tierMeta.icon}</i><strong>${esc(perms.preset.shortTitle || perms.preset.title)}</strong></span>
              ${userObj && getUserBookScope(userObj) === 'official' ? '<span class="badge badge-ok">Official 11% VAT</span>' : ''}
            </div>
            <div class="rhc-tagline">${esc(tagline)}</div>
          </div>
        </div>
        <div class="rhc-head-actions">
          ${owner && actionUid ? `<button type="button" class="btn btn-brass rhc-customize-btn" data-hover-open-perms="${esc(actionUid)}" data-hover-perm-tab="${esc(focusCat)}">${ic('sliders')}<span>Customize</span></button>` : ''}
          <button type="button" class="rhc-close-btn" data-hover-close="1" aria-label="Close preview">✕</button>
        </div>
      </div>

      <div class="rp-cap-grid compact">
        ${capabilities.map(c => {
          const capTab = c.key === 'unlocks' ? 'unlocks' : 'rights';
          return `
          <div class="rp-cap-item ${c.allowed ? (c.partial ? 'is-partial' : 'is-on') : 'is-off'} ${owner && actionUid ? 'is-clickable' : ''}" ${owner && actionUid ? `data-hover-open-perms="${esc(actionUid)}" data-hover-perm-tab="${capTab}"` : ''}>
            <span class="rp-cap-icon" aria-hidden="true">${c.allowed ? '✓' : '✕'}</span>
            <span class="rp-cap-lbl">${esc(c.label)}</span>
            <em class="rp-cap-state">${esc(c.state)}</em>
          </div>`;
        }).join('')}
      </div>

      <div class="rhc-suite-table">
        <div class="rhc-suite-row ${owner && actionUid ? 'is-clickable' : ''}" ${owner && actionUid ? `data-hover-open-perms="${esc(actionUid)}" data-hover-perm-tab="rights"` : ''}>
          <span class="rhc-suite-hdr"><span>Hubs</span><b>${visibleHubs.length}/${hubs.length}</b></span>
          <div class="rhc-hub-summary">
            ${hiddenHubs.length === 0
              ? `<span class="rhc-hub-all-ok">✓ All ${hubs.length} operational, financial &amp; shared hubs visible</span>`
              : `<span class="rhc-hub-vis-pill">✓ ${visibleHubs.length} Visible</span><span class="rhc-hidden-note">Hidden: ${esc(hiddenHubs.map(h => h.title).join(' · '))}</span>`}
          </div>
        </div>
        <div class="rhc-suite-row">
          <span class="rhc-suite-hdr"><span>Dashboards</span><b>${m.pbiPageCount}/${m.pbiPageTotal}</b></span>
          <div class="rp-suite-tags is-dash-grid">
            ${dashSuites.map(d => `<span class="rp-suite-tag ${d.on ? 'on' : 'off'}" ${owner && actionUid ? `data-hover-open-perms="${esc(actionUid)}" data-hover-perm-tab="dashboards"` : ''}><i>${d.on ? '✓' : '✕'}</i>${esc(d.short)}</span>`).join('')}
          </div>
        </div>
        <div class="rhc-suite-row">
          <span class="rhc-suite-hdr"><span>Statements</span><b>${m.stmtCount}/${m.stmtTotal}</b></span>
          <div class="rp-suite-tags is-stmt-row">
            ${stmtSuites.map(s => `<span class="rp-suite-tag stmt ${s.on ? 'on' : 'off'}" ${owner && actionUid ? `data-hover-open-perms="${esc(actionUid)}" data-hover-perm-tab="statements"` : ''}><i>${s.on ? '✓' : '✕'}</i>${esc(s.short)}</span>`).join('')}
          </div>
        </div>
      </div>

      ${isRealSeat ? `
        <div class="rhc-quick-deck">
          <div class="rhc-quick-row">
            <span class="rhc-quick-lbl">Role</span>
            <div class="rhc-quick-pills">
              ${quickRoles.map(qr => {
                const active = (perms.isCustomRole && qr.key === 'Custom') || (!perms.isCustomRole && perms.roleKey === qr.key);
                return `<button type="button" class="rhc-quick-pill ${active ? 'active' : ''}" data-hover-quick-role="${esc(qr.key)}" data-hover-uid="${esc(actionUid)}">${esc(qr.label)}</button>`;
              }).join('')}
            </div>
          </div>
          <div class="rhc-quick-row">
            <span class="rhc-quick-lbl">Reports</span>
            <div class="rhc-quick-pills">
              ${quickScopes.map(qs => {
                const active = !perms.isCustomRole && accVal === qs.value;
                return `<button type="button" class="rhc-quick-pill scope ${active ? 'active' : ''}" data-hover-quick-access="${esc(qs.value)}" data-hover-uid="${esc(actionUid)}">${esc(qs.label)}</button>`;
              }).join('')}
            </div>
          </div>
        </div>
      ` : ''}
    `;
  }

  function showRoleHoverCard(anchorEl, userObj, opts = {}) {
    if (!anchorEl || !userObj) return;
    if (getUserDirectoryScopeTier(activeUser()) === 'entry') return;
    if (_roleHoverHideTimer) { clearTimeout(_roleHoverHideTimer); _roleHoverHideTimer = null; }
    if (typeof window.__mfgHideUiTooltip === 'function') window.__mfgHideUiTooltip();
    if (!anchorEl.closest || !anchorEl.closest('#nuRolePermsSelector')) {
      const rWrap = document.getElementById('nuRolePermsSelector');
      if (rWrap && rWrap.classList.contains('open')) {
        rWrap.classList.remove('open');
        const rPop = document.getElementById('nuRolePopover');
        if (rPop) rPop.hidden = true;
        const rTrig = document.getElementById('nuRoleTrigger');
        if (rTrig) rTrig.setAttribute('aria-expanded', 'false');
      }
    }
    const card = ensureRoleHoverCardEl();
    if (_roleHoverAnchor && _roleHoverAnchor !== anchorEl) {
      _roleHoverAnchor.classList.remove('is-hover-open');
    }
    _roleHoverAnchor = anchorEl;
    anchorEl.classList.add('is-hover-open');
    card.innerHTML = renderRoleHoverCardBodyHtml(userObj, opts);
    const vw = window.innerWidth || document.documentElement.clientWidth || 1280;
    const vh = window.innerHeight || document.documentElement.clientHeight || 768;
    const rect = anchorEl.getBoundingClientRect();
    const inDirTable = !!(anchorEl.closest && anchorEl.closest('#usersDirectoryTbody'));
    const spaceRight = vw - rect.right - 14;
    const spaceLeft = rect.left - 14;

    let cardW = Math.min(448, Math.max(250, vw - 24));
    if (inDirTable && spaceRight >= 390 && spaceRight < 448) {
      cardW = Math.floor(spaceRight);
    }
    card.style.boxSizing = 'border-box';
    card.style.width = `${cardW}px`;
    card.style.maxHeight = `${Math.max(180, vh - 24)}px`;
    card.style.left = '12px';
    card.style.top = '12px';
    card.classList.remove('dock-right', 'dock-left', 'dock-above', 'dock-below');
    card.hidden = false;

    const cRect = card.getBoundingClientRect();
    const actualW = cRect.width || cardW;
    const actualH = cRect.height || 280;

    let left = rect.left;
    let top = rect.bottom + 8;
    let dockCls = 'dock-below';

    if (inDirTable && spaceRight >= actualW) {
      left = rect.right + 10;
      top = Math.round(rect.top + (rect.height / 2) - (actualH / 2));
      dockCls = 'dock-right';
    } else if (rect.bottom + actualH + 8 <= vh - 12) {
      left = rect.left;
      top = rect.bottom + 8;
      dockCls = 'dock-below';
    } else if (rect.top - actualH - 8 >= 12) {
      left = rect.left;
      top = rect.top - actualH - 8;
      dockCls = 'dock-above';
    } else if (spaceRight >= actualW) {
      left = rect.right + 10;
      top = Math.round(rect.top + (rect.height / 2) - (actualH / 2));
      dockCls = 'dock-right';
    } else if (spaceLeft >= actualW) {
      left = rect.left - actualW - 10;
      top = Math.round(rect.top + (rect.height / 2) - (actualH / 2));
      dockCls = 'dock-left';
    }

    if (left + actualW > vw - 12) left = Math.max(12, vw - actualW - 12);
    if (left < 12) left = 12;
    if (top + actualH > vh - 12) top = Math.max(12, vh - actualH - 12);
    if (top < 12) top = 12;

    const arrowY = Math.max(20, Math.min(actualH - 20, Math.round((rect.top + rect.height / 2) - top)));
    card.style.setProperty('--rhc-arrow-y', `${arrowY}px`);
    card.classList.add(dockCls);
    card.style.left = `${Math.round(left)}px`;
    card.style.top = `${Math.round(top)}px`;
  }

  function hideRoleHoverCard(immediate) {
    if (_roleHoverHideTimer) { clearTimeout(_roleHoverHideTimer); _roleHoverHideTimer = null; }
    const doHide = () => {
      const card = document.getElementById('roleHoverPreviewCard');
      if (card) card.hidden = true;
      if (_roleHoverAnchor) {
        _roleHoverAnchor.classList.remove('is-hover-open');
        _roleHoverAnchor = null;
      }
    };
    if (immediate) doHide();
    else _roleHoverHideTimer = setTimeout(doHide, 130);
  }

  function renderRolePermissionsMatrixHtml(previewUser, curAccess) {
    const isOpen = !!STATE.showRolePermMatrix;
    if (!isOpen) return '';
    const perms = getEffectivePermissions(previewUser);
    const m = countPermissionMetrics(perms, previewUser);
    const activeCat = STATE.permMatrixTab || 'all';
    const roleTabs = [
      { key: 'Entry', label: 'Entry Operator' },
      { key: 'Supervisor', label: 'Supervisor' },
      { key: 'Supervisor + Entry', label: 'Supervisor + Entry' },
      { key: 'Full Access (Owner)', label: 'Admin / Owner' },
      { key: 'Sales', label: 'Commercial & AR' },
      { key: 'Custom', label: 'Custom Role', icon: 'sliders' }
    ];

    const previewSeatInd = typeof getSeatPrimaryIndustry === 'function' ? getSeatPrimaryIndustry(previewUser) : getActiveIndustry(STATE.company);
    const validInds = ['Manufacturing', 'Holding & Treasury', 'Hospitality & Resorts', 'Automotive & Heavy Trading', 'Real Estate & Property', 'Insurance & Brokerage'];
    const activeHubMatrixInd = (STATE.permHubIndFilter && validInds.includes(STATE.permHubIndFilter))
      ? STATE.permHubIndFilter
      : previewSeatInd;
    const prevEvalInd = STATE._permEvalInd;
    let hubVisibilityList = [];
    try {
      STATE._permEvalInd = previewSeatInd;
      hubVisibilityList = (typeof HUB_CATALOG !== 'undefined'
        ? HUB_CATALOG.filter(h => isHubInActiveIndustry(h, previewSeatInd))
        : []).map(h => {
        const vis = canViewHub(h.id, previewUser);
        const visTabs = (h.tabs || []).filter(t => (!t.mfgOnly || previewSeatInd === 'Manufacturing') && (t.view !== 'entities' || hasMultipleComparisonEntities(previewUser, previewSeatInd)) && !(t.view === 'void_log' && !canViewVoidLog(previewUser)));
        const totalP = visTabs.length;
        const onP = vis ? visTabs.filter(t => canViewView(t.view, previewUser)).length : 0;
        return {
          id: h.id,
          title: h.title,
          visible: vis,
          onPages: onP,
          totalPages: totalP
        };
      });
    } finally {
      STATE._permEvalInd = prevEvalInd;
    }
    let matrixHubList = [];
    try {
      STATE._permEvalInd = activeHubMatrixInd;
      matrixHubList = (typeof HUB_CATALOG !== 'undefined'
        ? HUB_CATALOG.filter(h => isHubInActiveIndustry(h, activeHubMatrixInd))
        : []).map(h => {
        const vis = canViewHub(h.id, previewUser);
        const tabStates = (h.tabs || [])
          .filter(t => (!t.mfgOnly || activeHubMatrixInd === 'Manufacturing') && (t.view !== 'entities' || hasMultipleComparisonEntities(previewUser, activeHubMatrixInd)))
          .map(t => {
            const lockedRole = t.view === 'void_log' && !canViewVoidLog(previewUser);
            return {
              view: t.view,
              label: t.label,
              on: !lockedRole && (t.view === 'approvals' ? canViewView(t.view, previewUser) : (vis && canViewView(t.view, previewUser))),
              lockedSelf: isSelfActiveAdminUsersCheck(t.view, previewUser),
              lockedRole
            };
          });
        const onCount = tabStates.filter(t => t.on).length;
        const eligibleCount = tabStates.filter(t => !t.lockedRole).length;
        return {
          id: h.id,
          title: h.title,
          shortLabel: h.shortLabel || h.title,
          group: h.group || 'ops',
          visible: vis && onCount > 0,
          lockedSelf: isSelfActiveAdminUsersCheck(h.id, previewUser),
          tabs: tabStates,
          onPages: onCount,
          totalPages: eligibleCount,
          allPagesOn: vis && eligibleCount > 0 && onCount === eligibleCount,
          partialPages: vis && onCount > 0 && onCount < eligibleCount
        };
      });
    } finally {
      STATE._permEvalInd = prevEvalInd;
    }
    const totalMatrixHubs = matrixHubList.length;
    const enabledMatrixHubs = matrixHubList.filter(h => h.visible).length;
    const totalMatrixPages = matrixHubList.reduce((acc, h) => acc + h.totalPages, 0);
    const enabledMatrixPages = matrixHubList.reduce((acc, h) => acc + h.onPages, 0);
    const hpEff = getEffectiveHubPagePolicy(previewUser);
    const allTabsAndPagesSelected = Boolean(
      (hpEff && hpEff.selectAll) ||
      (totalMatrixPages > 0 && enabledMatrixPages === totalMatrixPages && enabledMatrixHubs === totalMatrixHubs)
    );
    const scopeMode = STATE.permHubScopeMode === 'seat' ? 'seat' : 'role';
    const indTabsList = [
      { id: 'Manufacturing', short: 'Manufacturing' },
      { id: 'Holding & Treasury', short: 'Holding' },
      { id: 'Hospitality & Resorts', short: 'Hospitality' },
      { id: 'Automotive & Heavy Trading', short: 'Trading' },
      { id: 'Real Estate & Property', short: 'Real Estate' },
      { id: 'Insurance & Brokerage', short: 'Insurance' }
    ];

    return `
      <div class="perm-matrix-card ${perms.isCustomRole ? 'is-custom' : ''}" id="rolePermissionsMatrixPanel">
        <div class="perm-matrix-hdr">
          <div class="perm-matrix-title-wrap">
            <div class="perm-matrix-eyebrow">GRANULAR ROLES &amp; PERMISSIONS MATRIX</div>
            <div class="perm-matrix-title">
              <span>${esc(perms.preset.shortTitle || perms.preset.title)}</span>
              <span class="badge ${perms.isCustomRole ? 'badge-brass' : perms.preset.badgeCls}">${perms.isCustomRole ? 'CUSTOM GRANULAR MATRIX' : 'PRESET · TOGGLE ANY ITEM TO CUSTOMIZE'}</span>
              ${activeCat !== 'all' ? `<button type="button" class="perm-mini-btn" data-perm-tab="all">Show All 4 Sections</button>` : ''}
            </div>
            <div class="perm-matrix-sub">${esc(perms.preset.summary)}</div>
          </div>
          <div class="perm-matrix-hdr-actions">
            <div class="perm-role-switcher" role="tablist" aria-label="Hover to preview or click to switch role preset">
              ${roleTabs.map(rt => `
                <button type="button" class="perm-role-tab ${perms.roleKey === rt.key ? 'active' : ''} ${rt.key === 'Custom' ? 'custom-tab' : ''}" data-matrix-role="${esc(rt.key)}">
                  ${rt.icon ? ic(rt.icon) + ' ' : ''}${esc(rt.label)}
                </button>
              `).join('')}
            </div>
            <button type="button" class="btn perm-close-btn" id="collapsePermMatrixBtn">✕ Done</button>
          </div>
        </div>

        <div class="perm-summary-strip">
          <div class="perm-summary-cell interactive ${activeCat === 'rights' ? 'is-focused' : ''}" role="button" tabindex="0" data-perm-tab="${activeCat === 'rights' ? 'all' : 'rights'}">
            <span class="perm-sum-lbl">01 · Hub &amp; Data Rights</span>
            <strong class="perm-sum-val" id="permSumRights">${m.rightsCount} / ${m.rightsTotal} Enabled</strong>
            <small>${m.hubCount}/${m.hubTotal} Sidebar Hubs · ${m.hubPageCount}/${m.hubPageTotal} Pages · ${m.tableCount}/${m.tableTotal} Tables</small>
          </div>
          <div class="perm-summary-cell interactive ${activeCat === 'unlocks' ? 'is-focused' : ''}" role="button" tabindex="0" data-perm-tab="${activeCat === 'unlocks' ? 'all' : 'unlocks'}">
            <span class="perm-sum-lbl">02 · Policy-Locked Fields</span>
            <strong class="perm-sum-val brass" id="permSumUnlocks">${m.unlockCount} / ${m.unlockTotal} Unlockable</strong>
            <small>${m.unlockCount === 9 ? 'All 9 locks open without Admin PIN' : (m.unlockCount > 0 ? `${m.unlockCount} field locks open without Admin PIN` : 'All 9 locks require Supervisor authorization')}</small>
          </div>
          <div class="perm-summary-cell interactive ${activeCat === 'dashboards' ? 'is-focused' : ''}" role="button" tabindex="0" data-perm-tab="${activeCat === 'dashboards' ? 'all' : 'dashboards'}">
            <span class="perm-sum-lbl">03 · Executive Dashboards</span>
            <strong class="perm-sum-val" id="permSumDash">${m.pbiPageCount} / ${m.pbiPageTotal} Dashboards</strong>
            <small>${Object.values(perms.dashboards).filter(Boolean).length} of 6 Analytics &amp; Hub Suites</small>
          </div>
          <div class="perm-summary-cell interactive ${activeCat === 'statements' ? 'is-focused' : ''}" role="button" tabindex="0" data-perm-tab="${activeCat === 'statements' ? 'all' : 'statements'}">
            <span class="perm-sum-lbl">04 · Printable A4 Statements</span>
            <strong class="perm-sum-val" id="permSumStmts">${m.stmtCount} / ${m.stmtTotal} Statements</strong>
            <small>${Object.values(perms.statements).filter(Boolean).length} of 5 Statement &amp; Voucher Suites</small>
          </div>
        </div>

        <div class="perm-hub-preview-bar">
          <span class="perm-hub-preview-lbl">Visible Sidebar Hubs (${m.hubCount}/${m.hubTotal}):</span>
          <div class="perm-hub-preview-pills">
            ${hubVisibilityList.map(h => `
              <span class="perm-hub-pill ${h.visible ? 'is-visible' : 'is-hidden'}">
                <i>${h.visible ? '✓' : '🔒'}</i>
                <span>${esc(h.title)}</span>
              </span>
            `).join('')}
          </div>
        </div>

        <div class="perm-sec-box perm-hub-access-sec" id="permSecHubsPages" ${activeCat !== 'all' && activeCat !== 'hubs' && activeCat !== 'rights' ? 'hidden' : ''}>
          <div class="perm-sec-head perm-hub-access-head">
            <div>
              <span class="perm-sec-num">00</span>
              <strong>Sidebar Tabs &amp; Sub-Pages Access</strong> <span class="perm-sec-cnt">(${enabledMatrixHubs}/${totalMatrixHubs} · ${enabledMatrixPages}/${totalMatrixPages})</span>
              <small class="perm-hub-access-sub">Select which sidebar tabs this role type can access, or uncheck Select All on any tab to choose which pages inside that tab are accessible.</small>
            </div>
            <div class="perm-sec-quick perm-hub-access-controls">
              <div class="perm-hub-scope-switch" role="group" aria-label="Sidebar tab policy scope">
                <button type="button" class="perm-mini-btn ${scopeMode === 'role' ? 'active' : ''}" data-perm-hub-scope="role"><span>Apply to Role Type</span> · <span>${esc(perms.preset.shortTitle || perms.roleKey)}</span></button>
                <button type="button" class="perm-mini-btn ${scopeMode === 'seat' ? 'active' : ''}" data-perm-hub-scope="seat">This User Seat Only</button>
              </div>
              <label class="perm-select-all-toggle ${allTabsAndPagesSelected ? 'is-on' : ''}">
                <input type="checkbox" class="perm-cb" id="permSelectAllTabsPagesCb" data-perm-tabs-select-all="1" ${allTabsAndPagesSelected ? 'checked' : ''}>
                <span>Select All Tabs &amp; Pages</span>
              </label>
              <button type="button" class="perm-mini-btn" data-perm-tabs-action="ops">Ops Tabs Only</button>
              <button type="button" class="perm-mini-btn" data-perm-tabs-action="reset">Reset Role Default</button>
            </div>
          </div>
          <div class="perm-hub-ind-bar" role="tablist" aria-label="Industry sidebar tabs">
            ${indTabsList.map(ind => `
              <button type="button" class="perm-hub-ind-tab ${activeHubMatrixInd === ind.id ? 'active' : ''}" data-perm-hub-ind="${esc(ind.id)}">
                <span>${esc(ind.short)}</span>
                ${ind.id === previewSeatInd ? '<em class="perm-ind-seat-tag">Primary</em>' : ''}
              </button>
            `).join('')}
          </div>
          <div class="perm-hub-card-grid" id="permHubCardsGrid">
            ${matrixHubList.map(h => `
              <div class="perm-hub-card ${h.visible ? (h.partialPages ? 'is-partial' : 'is-on') : 'is-off'}" data-hub-card="${esc(h.id)}">
                <div class="perm-hub-card-head">
                  <label class="perm-hub-main-toggle">
                    <input type="checkbox" class="perm-cb" data-perm-hub="${esc(h.id)}" ${h.visible ? 'checked' : ''} ${h.lockedSelf ? 'disabled' : ''}>
                    <span class="perm-hub-card-title">${esc(h.title)}</span>
                  </label>
                  ${h.totalPages > 1 ? `
                    <label class="perm-hub-all-toggle ${h.allPagesOn ? 'is-all' : (h.partialPages ? 'is-partial' : 'is-off')}">
                      <input type="checkbox" class="perm-cb-sm" data-perm-hub-all="${esc(h.id)}" ${h.allPagesOn ? 'checked' : ''}>
                      <span>Select All</span> <span>(${h.onPages}/${h.totalPages})</span>
                    </label>
                  ` : `
                    <span class="perm-hub-single-badge ${h.visible ? 'on' : 'off'}">${h.visible ? '1/1' : '<span>Hidden</span>'}</span>
                  `}
                </div>
                <div class="perm-hub-pages-list ${h.allPagesOn && h.totalPages > 1 ? 'is-all-selected' : 'is-custom-pages'}">
                  ${h.tabs.map(t => `
                    <label class="perm-page-chip ${t.on ? 'is-on' : 'is-off'} ${t.lockedRole ? 'is-role-locked' : ''}">
                      <input type="checkbox" class="perm-cb-page" data-perm-page="${esc(t.view)}" data-perm-parent-hub="${esc(h.id)}" ${t.on ? 'checked' : ''} ${(t.lockedSelf || t.lockedRole) ? 'disabled' : ''}>
                      <span class="perm-page-chip-lbl">${esc(t.label)}</span>
                    </label>
                  `).join('')}
                </div>
              </div>
            `).join('')}
          </div>
        </div>

        <div class="perm-section-grid ${activeCat !== 'all' ? 'is-single-focus' : ''}">
          <!-- SECTION 1: DATA READ, ENTER, MODIFY & VOID RIGHTS -->
          <div class="perm-sec-box" id="permSecRights" ${activeCat !== 'all' && activeCat !== 'rights' ? 'hidden' : ''}>
            <div class="perm-sec-head">
              <div>
                <span class="perm-sec-num">01</span>
                <strong>Hub Access, Data Entry, Modify &amp; Void Rights</strong>
              </div>
              <div class="perm-sec-quick">
                <button type="button" class="perm-mini-btn" data-perm-bulk="rights:all">All On</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="rights:ops">Ops Entry</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="rights:readonly">Read-Only</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="rights:off">Clear</button>
              </div>
            </div>
            <div class="perm-items-list">
              ${PERM_CATALOG.rights.map(item => {
                const checked = !!perms.rights[item.id];
                return `
                  <label class="perm-item-row ${checked ? 'is-on' : 'is-off'}">
                    <input type="checkbox" class="perm-cb" data-perm-cat="rights" data-perm-id="${esc(item.id)}" data-perm-group="rights" data-perm-key="${esc(item.id)}" ${checked ? 'checked' : ''}>
                    <div class="perm-item-copy">
                      <div class="perm-item-title">
                        <b>${esc(item.label)}</b>
                        <span class="perm-state-pill ${checked ? 'on' : 'off'}">${checked ? '✓ ALLOWED' : 'LOCKED'}</span>
                      </div>
                      <small>${esc(item.sub)}</small>
                    </div>
                  </label>
                `;
              }).join('')}
            </div>
          </div>

          <!-- SECTION 2: POLICY-LOCKED ITEMS THEY CAN UNLOCK -->
          <div class="perm-sec-box" id="permSecUnlocks" ${activeCat !== 'all' && activeCat !== 'unlocks' ? 'hidden' : ''}>
            <div class="perm-sec-head">
              <div>
                <span class="perm-sec-num">02</span>
                <strong>Policy-Locked Form Fields This Role Can Override (No Admin PIN)</strong>
              </div>
              <div class="perm-sec-quick">
                <button type="button" class="perm-mini-btn" data-perm-bulk="unlocks:all">Unlock All 9</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="unlocks:pricing">Pricing &amp; Qty</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="unlocks:off">Require PIN</button>
              </div>
            </div>
            <div class="perm-items-list">
              ${PERM_CATALOG.unlocks.map(item => {
                const checked = !!perms.unlocks[item.id];
                return `
                  <label class="perm-item-row ${checked ? 'is-on' : 'is-off'}">
                    <input type="checkbox" class="perm-cb" data-perm-cat="unlocks" data-perm-id="${esc(item.id)}" data-perm-group="unlocks" data-perm-key="${esc(item.id)}" ${checked ? 'checked' : ''}>
                    <div class="perm-item-copy">
                      <div class="perm-item-title">
                        <b>${esc(item.label)}</b>
                        <span class="perm-rule-code">${esc(item.rule)}</span>
                        <span class="perm-state-pill ${checked ? 'brass' : 'off'}">${checked ? `${ic('unlock')} CAN UNLOCK` : `${ic('lock')} SUPV PIN REQ`}</span>
                      </div>
                      <small>${esc(item.sub)}</small>
                    </div>
                  </label>
                `;
              }).join('')}
            </div>
          </div>

          <!-- SECTION 3: LINKED EXECUTIVE DASHBOARDS & HUB ANALYTICS -->
          <div class="perm-sec-box" id="permSecDashboards" ${activeCat !== 'all' && activeCat !== 'dashboards' ? 'hidden' : ''}>
            <div class="perm-sec-head">
              <div>
                <span class="perm-sec-num">03</span>
                <strong>Executive Dashboards &amp; Hub Analytics (${m.pbiPageTotal} Interactive Dashboards)</strong>
              </div>
              <div class="perm-sec-quick">
                <button type="button" class="perm-mini-btn" data-perm-bulk="dashboards:full">All ${m.pbiPageTotal} Dashboards</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="dashboards:ops">Ops Only (${m.pbiPageTotal === 12 ? 10 : 9})</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="dashboards:off">None</button>
              </div>
            </div>
            <div class="perm-items-list">
              ${PERM_CATALOG.dashboards.map(item => {
                const checked = !!perms.dashboards[item.id];
                return `
                  <label class="perm-item-row ${checked ? 'is-on' : 'is-off'}">
                    <input type="checkbox" class="perm-cb" data-perm-cat="dashboards" data-perm-id="${esc(item.id)}" data-perm-group="dashboards" data-perm-key="${esc(item.id)}" ${checked ? 'checked' : ''}>
                    <div class="perm-item-copy">
                      <div class="perm-item-title">
                        <b>${esc(item.label)}</b>
                        <span class="perm-rule-code">${esc(item.badge)}</span>
                        <span class="perm-state-pill ${checked ? 'on' : 'off'}">${checked ? '✓ VISIBLE' : 'HIDDEN'}</span>
                      </div>
                      <small>${esc(item.sub)}</small>
                    </div>
                  </label>
                `;
              }).join('')}
            </div>
          </div>

          <!-- SECTION 4: LINKED PRINTABLE A4 STATEMENTS (22 REPORTS) -->
          <div class="perm-sec-box" id="permSecStatements" ${activeCat !== 'all' && activeCat !== 'statements' ? 'hidden' : ''}>
            <div class="perm-sec-head">
              <div>
                <span class="perm-sec-num">04</span>
                <strong>Printable A4 Financial &amp; Operational Statements (22 Reports)</strong>
              </div>
              <div class="perm-sec-quick">
                <button type="button" class="perm-mini-btn" data-perm-bulk="statements:full">All 22 Stmts</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="statements:ops">Ops Only (13)</button>
                <button type="button" class="perm-mini-btn" data-perm-bulk="statements:off">None</button>
              </div>
            </div>
            <div class="perm-items-list">
              ${PERM_CATALOG.statements.map(item => {
                const checked = !!perms.statements[item.id];
                return `
                  <label class="perm-item-row ${checked ? 'is-on' : 'is-off'}">
                    <input type="checkbox" class="perm-cb" data-perm-cat="statements" data-perm-id="${esc(item.id)}" data-perm-group="statements" data-perm-key="${esc(item.id)}" ${checked ? 'checked' : ''}>
                    <div class="perm-item-copy">
                      <div class="perm-item-title">
                        <b>${esc(item.label)}</b>
                        <span class="perm-rule-code">${esc(item.badge)}</span>
                        <span class="perm-state-pill ${checked ? 'on' : 'off'}">${checked ? '✓ PERMITTED' : 'HIDDEN'}</span>
                      </div>
                      <small>${esc(item.sub)}</small>
                    </div>
                  </label>
                `;
              }).join('')}
            </div>
          </div>
        </div>
      </div>
    `;
  }

  function renderSeatEditorHtml() {
    const owner = isOwner(activeUser());
    if (!owner) return '';
    const uCount = STATE.users.length;
    if (!STATE.showAddUserForm) {
      return `
        <div class="panel-card seat-editor-collapsed" style="margin-bottom:16px">
          <div class="seat-collapsed-inner">
            <div>
              <strong>Team Seat Inspector &amp; Multi-Device Access Editor</strong>
              <span class="seat-collapsed-sub"> · Inspect and update Full Name, Login Email, PIN, Roles &amp; Permissions, and Assigned Companies (RLS) for any of the ${uCount} current users.</span>
            </div>
            <div style="display:flex;gap:6px;flex-wrap:wrap">
              <button type="button" class="btn btn-brass" id="openSeatInspectorBtn">${ic('edit')} Check / Update Current Users (${uCount})</button>
              <button type="button" class="btn btn-primary" id="openNewSeatBarBtn">+ New Team Login</button>
            </div>
          </div>
        </div>
      `;
    }

    const editUser = getEditingSeatUser();
    const editIdx = editUser ? STATE.users.findIndex(u => String(u.id) === String(editUser.id)) : -1;
    const isNewMode = !editUser;
    const curRole = STATE.draftRoleOverride || (editUser ? (editUser.role || 'Entry') : 'Entry');
    const curCompanies = STATE.draftCompaniesOverride || (editUser ? normalizeCompaniesScope(editUser.companies) : 'WTC');
    const curAccess = STATE.draftAccessOverride || (editUser ? seatAccessValue(editUser) : 'partial|partial');
    const curBookScope = STATE.draftBookScopeOverride || (editUser ? getUserBookScope(editUser) : 'all');
    const curStatus = editUser ? (editUser.status || 'Active') : 'Active';
    const isRedactedPinEdit = Boolean(editUser && editUser.pin_redacted && !editUser.pin_code);
    const curPin = editUser ? (isRedactedPinEdit ? '' : (editUser.pin_code || '')) : (STATE.newDraftPin || '3564');
    const isSelfOwner = editUser && editIdx === STATE.activeUserIdx;
    const fSamples = editUser ? userFaceSamples(editUser) : [];
    const previewUser = getDraftSeatPreviewUser(editUser, curRole, curCompanies, curAccess);
    const previewPerms = getEffectivePermissions(previewUser);

    return `
      <div class="panel-card seat-editor-card" id="seatEditorPanel" style="margin-bottom:16px;border-color:var(--brass)">
        <div class="panel-head seat-editor-head">
          <div class="panel-title" style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <span>CREATE OR UPDATE MULTI-DEVICE TEAM LOGIN SEAT</span>
            ${editUser
              ? `<span class="badge badge-ok" id="nuModeBadge">SEAT ${editIdx + 1} OF ${uCount} · ${esc(editUser.full_name)}</span>`
              : `<span class="badge badge-brass" id="nuModeBadge">NEW TEAM LOGIN SEAT</span>`}
          </div>
          <div class="seat-head-actions">
            <button type="button" class="btn" id="nuPrevSeatBtn" style="padding:3px 8px;font-size:11px">‹ Prev User</button>
            <button type="button" class="btn" id="nuNextSeatBtn" style="padding:3px 8px;font-size:11px">Next User ›</button>
            <button type="button" class="btn ${isNewMode ? 'btn-brass' : ''}" id="nuNewBlankBtn" style="padding:3px 9px;font-size:11px">+ New Blank Seat</button>
            <button type="button" class="btn" id="cancelAddUserBtn" style="padding:3px 9px;font-size:11px">✕ Hide</button>
          </div>
        </div>

        <div class="seat-picker-bar">
          <div class="seat-picker-top">
            <label class="seat-picker-lbl" for="nu_seat_select">Select Current User to Check or Update (${uCount} Seats)</label>
            <select id="nu_seat_select" class="seat-select-dropdown">
              ${STATE.users.map((u, idx) => {
                const cBadge = formatCompactCompaniesBadge(u.companies, 3);
                const dispPin = (STATE.demoVisitor || !u.pin_code) ? '••••' : u.pin_code;
                const uPerms = getEffectivePermissions(u);
                return `
                <option value="${esc(u.id)}" ${!isNewMode && String(u.id) === String(editUser.id) ? 'selected' : ''}>
                  ${idx + 1}. ${esc(u.full_name)} (${esc(u.email)}) · PIN ${esc(dispPin)} · ${esc(uPerms.preset.shortTitle || u.role)} · ${esc(cBadge.text)}
                </option>`;
              }).join('')}
              <option value="__new__" ${isNewMode ? 'selected' : ''}>+ Create New Team Login Seat (Blank Form)</option>
            </select>
          </div>
          <div class="seat-pill-strip" role="tablist" aria-label="Team login seats">
            ${STATE.users.map((u, idx) => {
              const active = !isNewMode && String(u.id) === String(editUser.id);
              const dispPin = (STATE.demoVisitor || !u.pin_code) ? '••••' : u.pin_code;
              return `<button type="button" class="seat-pick-pill ${active ? 'active' : ''} ${u.status === 'Suspended' ? 'suspended' : ''}" data-pick-seat="${esc(u.id)}">
                <span class="seat-pick-num">${idx + 1}</span>
                <span class="seat-pick-name">${esc(u.full_name)}</span>
                <small class="mono">${esc(dispPin)}</small>
              </button>`;
            }).join('')}
            <button type="button" class="seat-pick-pill new-seat ${isNewMode ? 'active' : ''}" data-pick-seat="__new__">
              <span>+ New Seat</span>
            </button>
          </div>
        </div>

        <div style="padding:14px 16px 6px">
          <div class="form-grid-3">
            <div class="form-field">
              <label for="nu_name">Full Name *</label>
              <input type="text" id="nu_name" value="${esc(editUser ? editUser.full_name : '')}" placeholder="e.g. Rami Haddad (WTC Scale)" autocomplete="off">
            </div>
            <div class="form-field">
              <label for="nu_email">Email Address (Login ID) *</label>
              <input type="email" id="nu_email" value="${esc(editUser ? editUser.email : '')}" placeholder="name@company.com" autocomplete="off">
              <span class="hint">${editUser ? `Seat ID: ${esc(editUser.id)} · Last login: ${esc(editUser.last_login_at || 'Never')}` : 'An existing email updates that seat instead of creating a new one.'}</span>
            </div>
            <div class="form-field">
              <label for="nu_pin">Access PIN (4 to 12 Digits) *</label>
              <input type="text" inputmode="numeric" pattern="[0-9]{4,12}" maxlength="12" id="nu_pin" value="${esc(curPin)}" placeholder="${isRedactedPinEdit ? 'Leave blank to keep current PIN' : ''}" class="mono" autocomplete="off">
            </div>
            <div class="form-field" id="nuRolePermsField">
              <div class="field-lbl-with-btn">
                <label for="nuRoleTrigger">Roles &amp; Permissions *</label>
                <button type="button" class="role-inspect-btn ${STATE.showRolePermMatrix ? 'active' : ''}" id="checkRolePermsBtn">
                  ${STATE.showRolePermMatrix ? `${ic('shield')} Hide Matrix` : `${ic('sliders')} Customize`}
                </button>
              </div>
              ${renderRolePermSelectorHtml(previewUser, curRole, curAccess)}
            </div>
            <div class="form-field">
              <label for="nuCompanyTrigger">Assigned Companies (Row-Level Security) *</label>
              ${renderCompanyMultiSelectHtml(curCompanies)}
            </div>
            <div class="form-field">
              <label for="nu_auth_mode">Sign-In Requirement (PIN / Face ID)</label>
              <select id="nu_auth_mode">
                <option value="inherit" ${(!editUser || !editUser.auth_mode || editUser.auth_mode === 'inherit') ? 'selected' : ''}>Workspace Default (${esc((AUTH_MODE_OPTIONS.find(o => o.value === getWorkspaceAuthMode()) || AUTH_MODE_OPTIONS[1]).short)})</option>
                ${AUTH_MODE_OPTIONS.map(o => `<option value="${esc(o.value)}" ${(editUser && editUser.auth_mode === o.value) ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}
              </select>
              <span class="hint">Choose Either (PIN or Face ID), Both (2FA), Face ID Only (3+ live frames), or PIN Only.</span>
            </div>
          </div>

          <div id="rolePermissionsMatrixWrap">
            ${renderRolePermissionsMatrixHtml(previewUser, curAccess)}
          </div>

          <div id="nuErrors" class="form-errors" hidden></div>
          <div class="seat-editor-foot">
            <div class="seat-editor-meta">
              <label class="seat-status-inline" for="nu_status">
                <span>Seat Status:</span>
                <select id="nu_status" ${isSelfOwner ? 'disabled' : ''}>
                  <option value="Active" ${curStatus !== 'Suspended' ? 'selected' : ''}>Active (Can Sign In)</option>
                  <option value="Suspended" ${curStatus === 'Suspended' ? 'selected' : ''}>Suspended (Sign-In Blocked)</option>
                </select>
              </label>
              <label class="seat-status-inline" for="nu_book_scope">
                <span>Book Scope:</span>
                <select id="nu_book_scope">
                  <option value="all" ${curBookScope !== 'official' ? 'selected' : ''}>All Books (Complete Ledger)</option>
                  <option value="official" ${curBookScope === 'official' ? 'selected' : ''}>Official / Fiscal (11% VAT Only)</option>
                </select>
              </label>
              <label class="seat-status-inline" for="nu_entry_edit_mode">
                <span>Record Edit Mode:</span>
                <select id="nu_entry_edit_mode" ${previewPerms.rights.modify_data ? 'disabled' : ''}>
                  ${previewPerms.rights.modify_data
                    ? '<option value="full" selected>Supervisor Full Edit (Words &amp; Numbers)</option>'
                    : `<option value="words_only" ${previewPerms.rights.modify_text ? 'selected' : ''}>Words Only (Numbers Locked to Supervisor)</option>
                       <option value="locked" ${!previewPerms.rights.modify_text ? 'selected' : ''}>Locked (New Entries &amp; Pending Prices Only)</option>`}
                </select>
              </label>
              ${editUser ? `
                <span class="badge ${userHasFaceId(editUser) && effectiveSeatAuthMode(editUser) !== 'pin_only' ? 'badge-ok' : 'badge-warn'}">${esc(seatAuthBadgeLabel(editUser))}</span>
                <button type="button" class="btn" style="padding:3px 9px;font-size:11px" data-enrol-user="${esc(editUser.id)}">Configure Face ID ↓</button>
              ` : ''}
            </div>
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
              ${editUser ? `<button type="button" class="btn" id="resetSeatEditBtn">↺ Revert Changes</button>` : ''}
              <button type="button" class="btn btn-primary" id="saveNewUserBtn">${editUser ? `✓ Update ${esc(editUser.full_name)} &amp; Sync Across All Devices` : '✓ Save New Seat &amp; Sync Across All Devices'}</button>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  function renderUsersDirectoryRowsHtml() {
    const me = activeUser();
    const tier = getUserDirectoryScopeTier(me);
    const owner = isOwner(me);
    const hideRoleAndRlsCols = tier === 'entry';
    const visUsers = getVisibleDirectoryUsers(me);
    const editUser = getEditingSeatUser();
    const editId = (!STATE.showAddUserForm || STATE.editingUserId === '__new__' || !editUser) ? '' : String(editUser.id);
    return visUsers.map(u => {
      const idx = STATE.users.findIndex(x => x && String(x.id) === String(u.id));
      const isSelf = idx === STATE.activeUserIdx || String(u.id) === String(me.id);
      const canManageFace = owner || tier === 'supervisor' || isSelf;
      const faceCnt = userFacePoseCount(u);
      const faceActive = faceCnt > 0 && effectiveSeatAuthMode(u) !== 'pin_only';
      const isTarget = String(u.id) === String(enrolTargetUser().id);
      const isEditing = String(u.id) === editId;
      const scopedCoList = filterCompaniesForViewer(u.companies, me);
      const compBadge = formatCompactCompaniesBadge(scopedCoList, 3);
      const shownCoNames = Array.isArray(compBadge.shownNames) && compBadge.shownNames.length
        ? compBadge.shownNames
        : scopedCoList.slice(0, 3);
      const b = buildRoleCapabilityBreakdown(u);
      const { perms, m: pm, scopeShortLbl } = b;
      const roleTitle = perms.preset.shortTitle || u.role;
      const tierMeta = getSeatRoleTierMeta(perms);
      const initials = getSeatMonogram(u.full_name);
      const authMode = effectiveSeatAuthMode(u);
      const faceCompactLbl = (!faceActive || authMode === 'pin_only')
        ? 'PIN Only'
        : (authMode === 'face_only'
            ? `${faceCnt}/3 · Face Only`
            : (authMode === 'both' ? `${faceCnt}/3 · 2FA` : `${faceCnt}/3 · PIN/Face`));
      const poseDotsHtml = `<span class="face-pose-dots" aria-hidden="true">${[0, 1, 2].map(i => `<i class="${i < faceCnt ? (faceActive ? 'on' : 'saved') : ''}"></i>`).join('')}</span>`;
      const rawLogin = String(u.last_login_at || 'Never').trim();
      const loginParts = rawLogin !== 'Never' && rawLogin.includes(' ') ? rawLogin.split(/\s+/) : null;
      const loginHtml = loginParts
        ? `<span class="user-last-login mono"><span class="ull-date">${esc(loginParts[0])}</span><span class="ull-time"> ${esc(loginParts.slice(1).join(' '))}</span></span>`
        : `<span class="user-last-login is-never">${esc(rawLogin)}</span>`;
      const roleCellInner = `
        <span class="urp-top-bar">
          <span class="urp-role-lead">
            <span class="urp-role-pill ${tierMeta.tierCls}">
              <i class="urp-role-ico" aria-hidden="true">${tierMeta.icon}</i>
              <span class="urp-role-name">${esc(roleTitle)}</span>
            </span>
            <span class="urp-lock-badge ${pm.unlockCount ? 'brass' : 'locked'}">
              <i class="urp-cap-ico" aria-hidden="true">${pm.unlockCount ? ic('unlock') : ic('lock')}</i>
              <span>${pm.unlockCount ? `${pm.unlockCount}/${pm.unlockTotal}` : 'PIN'}</span>
            </span>
            ${getUserBookScope(u) === 'official' ? '<span class="urp-tag official">Official</span>' : ''}
          </span>
          <span class="urp-interactive-cue" aria-hidden="true">
            ${ic('sliders')}<i class="urp-caret">▾</i>
          </span>
        </span>
        <span class="urp-bottom-bar">
          <span class="urp-cap-pill reports">
            <i class="urp-cap-ico" aria-hidden="true">${ic('reports')}</i>
            <span class="urp-scope-lbl">${esc(scopeShortLbl)}</span>
          </span>
          <span class="urp-cap-pill hubs">
            <span>${pm.hubCount}/${pm.hubTotal} Hubs</span>
          </span>
        </span>
      `;
      return `
      <tr class="user-dir-row ${isTarget ? 'enrol-selected-row' : ''} ${isEditing ? 'seat-editing-row' : ''}" data-user-row="${esc(u.id)}">
        <td class="user-dir-name-cell">
          <div class="user-dir-identity">
            <span class="user-dir-avatar ${hideRoleAndRlsCols ? 'tier-entry' : tierMeta.tierCls}" aria-hidden="true">${esc(initials)}</span>
            <div class="user-dir-name-stack">
              <div class="user-dir-name-line">
                <strong>${esc(u.full_name)}</strong>${isSelf ? ' <span class="badge badge-ok user-you-badge">you</span>' : ''}
              </div>
            </div>
          </div>
        </td>
        <td class="user-dir-email-cell"><span class="user-email-pill mono">${esc(u.email)}</span></td>
        ${owner && !STATE.demoVisitor ? `<td class="user-dir-pin-cell"><span class="badge badge-info user-pin-keycap mono">${esc(u.pin_code || '••••')}</span></td>` : ''}
        <td class="user-dir-face-cell">
          ${canManageFace
            ? `<button type="button" class="user-face-capsule ${faceActive ? 'is-enrolled' : 'is-pin-only'} ${isTarget ? 'is-target' : ''}" data-enrol-user="${esc(u.id)}">${poseDotsHtml}<span>${esc(faceCompactLbl)}</span></button>`
            : `<span class="user-face-capsule ${faceActive ? 'is-enrolled' : 'is-pin-only'} is-readonly">${poseDotsHtml}<span>${esc(faceCompactLbl)}</span></span>`}
        </td>
        ${hideRoleAndRlsCols ? '' : `
        <td class="user-role-perm-cell">
          ${owner
            ? `<button type="button" class="user-role-perm-btn ${tierMeta.tierCls} ${isEditing && STATE.showRolePermMatrix ? 'is-active' : ''}" data-check-perms="${esc(u.id)}" data-role-hover-user="${esc(u.id)}">${roleCellInner}</button>`
            : `<div class="user-role-perm-btn ${tierMeta.tierCls} is-readonly" tabindex="0" data-role-hover-user="${esc(u.id)}">${roleCellInner}</div>`}
        </td>
        <td class="user-dir-rls-cell">
          <div class="rls-co-cell ${owner ? 'is-interactive' : ''}" ${owner ? `role="button" tabindex="0" data-edit-rls-user="${esc(u.id)}"` : ''}>
            <div class="rls-co-chips">
              ${shownCoNames.map((coName, cIdx) => {
                const isLast = cIdx === shownCoNames.length - 1;
                return `<span class="rls-co-chip"><strong>${esc(coName)}</strong>${!isLast ? '<span class="sr-only">, </span>' : ''}</span>`;
              }).join('')}
              ${compBadge.extraCount > 0 ? `<span class="rls-co-chip more"> +${compBadge.extraCount} more</span>` : ''}
            </div>
            ${compBadge.indCount > 1 ? `<span class="badge badge-info">${compBadge.indCount} Ind</span>` : ''}
          </div>
        </td>
        `}
        <td class="user-dir-status-cell"><span class="badge ${u.status === 'Suspended' ? 'badge-err' : 'badge-ok'} user-status-pill"><i class="user-status-dot" aria-hidden="true"></i>${esc(u.status || 'Active')}</span></td>
        <td class="user-dir-login-cell">${loginHtml}</td>
        <td class="user-actions-cell">
          <div class="user-actions-wrap">
            ${owner ? `<button type="button" class="btn user-act-btn ${isEditing ? 'btn-primary' : ''}" data-edit-user="${esc(u.id)}">${ic('edit')}<span>Edit</span></button>` : ''}
            ${canManageFace ? `<button type="button" class="btn user-act-btn ${isTarget ? 'btn-brass' : ''}" data-enrol-user="${esc(u.id)}">${ic('camera')}<span>Face ID</span></button>` : ''}
            ${owner && idx >= 0 ? `
              <button type="button" class="btn user-act-btn ${STATE.activeUserIdx === idx ? 'is-active-seat' : ''}" data-sim-user="${idx}">${STATE.activeUserIdx === idx ? '● Active' : `${ic('user')}<span>Impersonate</span>`}</button>
              <button type="button" class="btn user-act-btn" data-invite-user="${idx}">${ic('link')}<span>Invite Link</span></button>
              <button type="button" class="btn user-act-btn ${u.status === 'Suspended' ? 'is-activate' : 'is-suspend'}" data-toggle-user="${idx}">${u.status === 'Suspended' ? 'Activate' : 'Suspend'}</button>
            ` : ''}
          </div>
        </td>
      </tr>`;
    }).join('');
  }

  function renderUsers() {
    const me = activeUser();
    const tier = getUserDirectoryScopeTier(me);
    const owner = isOwner(me);
    const hideRoleAndRlsCols = tier === 'entry';
    const canSwitchEnrolTarget = owner || tier === 'supervisor';
    const visUsers = getVisibleDirectoryUsers(me);
    const visSessions = getVisibleDirectorySessions(me);
    const uCount = visUsers.length;
    const sbConfigured = !!(STATE.supabaseCfg.url && STATE.supabaseCfg.anonKey);
    const enrolUser = enrolTargetUser();
    syncEnrolBufferFromUser(enrolUser, false);
    const faceCount = visUsers.filter(userHasFaceId).length;
    const enrolSavedCount = userFacePoseCount(enrolUser);
    const capCount = effectiveEnrolPoseCount(enrolUser);
    const poseComplete = capCount >= 3;
    const showcaseHref = (IS_LOCAL && !location.pathname.includes('/app/')) ? '/showcase/' : '../';
    const supScopeLbl = tier === 'supervisor' ? (getSupervisorScopedBus(me).join(' · ') || 'Your Business Unit') : '';

    return `
      <div class="cockpit-banner has-insights">
        <div class="cockpit-title-block sr-only">
          <div class="cockpit-eyebrow">MULTI-DEVICE TEAM AUTHENTICATION · FACE ID · BUSINESS-UNIT RLS</div>
          <div class="cockpit-title">Users &amp; Security</div>
        </div>
        <div class="cockpit-pills insight-grid cols-3">
          ${insightCard({
            label: 'Active Web Seats',
            badge: hideRoleAndRlsCols ? 'Personal Account' : (tier === 'supervisor' ? 'BU Scoped RLS' : 'Multi-Device RLS'),
            badgeCls: 'brass',
            val: hideRoleAndRlsCols ? '1 Seat (You)' : `${uCount} ${uCount === 1 ? 'User' : 'Users'}`,
            valCls: 'brass',
            sub: hideRoleAndRlsCols
              ? `Your personal sign-in profile &amp; biometric security`
              : (tier === 'supervisor'
                ? `Team seats scoped to ${esc(supScopeLbl)}`
                : `Scoped across phones, tablets &amp; laptops with BU Row-Level Security`),
            tone: 'brass'
          })}
          ${insightCard({
            label: 'Face ID Biometric 2FA',
            badge: `${uCount ? Math.round((faceCount / uCount) * 100) : 0}% Enrolled`,
            badgeCls: faceCount ? 'emerald' : 'amber',
            val: `${faceCount} / ${uCount} Enrolled`,
            valCls: faceCount ? 'emerald' : 'amber',
            pct: uCount ? (faceCount / uCount) * 100 : 0,
            sub: `128-D live neural face descriptors with blink/turn liveness`,
            tone: faceCount ? 'emerald' : 'amber',
            id: 'enrolCockpitCount'
          })}
          ${insightCard({
            label: 'Cloud Relay Status',
            badge: /Live/.test(STATE.cloudStatus) ? 'Connected' : 'Local Cache',
            badgeCls: /Live/.test(STATE.cloudStatus) ? 'emerald' : 'amber',
            val: esc(STATE.cloudStatus),
            valCls: /Live/.test(STATE.cloudStatus) ? 'emerald' : 'amber',
            sub: `Real-time seat, PIN &amp; entry synchronization across devices`,
            tone: 'steel'
          })}
        </div>
      </div>

      <div id="seatEditorWrap">
        ${renderSeatEditorHtml()}
      </div>

      <div class="panel-card mfg-enrol-studio" id="faceEnrolPanel" style="margin-bottom:16px">
        <div class="enrol-console-hdr">
          <div class="enrol-console-brand">
            <div class="enrol-console-icon">${ENROL_SVGS.reticle}</div>
            <div>
              <div class="enrol-console-title">Face ID Enrolment</div>
            </div>
          </div>
          <div class="enrol-console-actions">
            ${canViewView('alert_rules') ? `<button type="button" class="btn-sn-act" data-nav-jump="alert_rules">${ic('sliders')} Alerts &amp; Thresholds</button>` : ''}
            <span class="enrol-seat-pill ${enrolSavedCount ? 'enrolled' : 'pending'}" id="enrolHeaderBadge">
              ${enrolSavedCount ? `✓ ${esc(enrolUser.full_name)} · ${enrolSavedCount}/3 Poses Saved` : `${esc(enrolUser.full_name)} · Not Enrolled`}
            </span>
          </div>
        </div>

        <div class="enrol-studio-grid">
          <div class="enrol-cam-col">
            <div class="enrol-cam-viewport" id="enrolCamViewport">
              <video id="enrolFaceVideo" autoplay playsinline muted poster="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7"></video>
              <canvas id="enrolFaceOverlay"></canvas>
              <div class="enrol-cam-vignette"></div>
              <div class="enrol-hud-corners" aria-hidden="true">
                <i class="tl"></i><i class="tr"></i><i class="bl"></i><i class="br"></i>
                <div class="enrol-hud-oval"></div>
              </div>
              <div class="enrol-hud-top">
                <span class="enrol-hud-pill" id="enrolHudStatusPill">
                  <span class="enrol-hud-dot ${FACE_STATE.enrolCamActive ? 'live' : ''}" id="enrolHudDot"></span>
                  <span id="enrolHudTelemetry">${FACE_STATE.enrolCamActive ? (poseComplete ? 'LIVE VERIFY · LOOK AT CAMERA' : 'CAMERA LIVE') : (capCount ? `${capCount}/3 POSES SAVED` : 'CAMERA STANDBY')}</span>
                </span>
                <button type="button" class="enrol-hud-stop-btn" id="enrolStartCamBtn" ${FACE_STATE.enrolCamActive ? '' : 'hidden'}>
                  ${ENROL_SVGS.stop}<span>Stop Camera</span>
                </button>
              </div>
              <div class="enrol-shutter-flash" id="enrolShutterFlash"></div>
              <div class="enrol-cam-placeholder" id="enrolCamPlaceholder" ${FACE_STATE.enrolCamActive ? 'hidden' : ''}>
                <div class="enrol-cam-reticle-badge">${ENROL_SVGS.reticle}</div>
                <div class="enrol-cam-placeholder-title" id="enrolCamPlaceholderTitle">${poseComplete ? 'Live Camera &amp; Recognition' : 'Face ID Camera'}</div>
                <small id="enrolCamPlaceholderSub">${poseComplete ? `Verify ${esc(enrolUser.full_name)} in real time or retake any pose` : 'Guided 3-pose capture (straight, slight left, slight right)'}</small>
                <span class="enrol-cam-wake-pill" id="enrolCamWakePill">${ENROL_SVGS.cam}<span>${poseComplete ? 'Click for Live Verify or Retake' : 'Click to Enable Camera'}</span></span>
              </div>
            </div>
            <div class="enrol-thumb-strip" id="enrolThumbStrip">
              ${renderEnrolThumbStripHtml()}
            </div>
          </div>

          <div class="enrol-controls-col">
            <div class="enrol-config-grid">
              <div class="enrol-config-card">
                <div class="enrol-config-lbl-row">
                  <label class="enrol-config-lbl" for="enrolUserSelect">${hideRoleAndRlsCols ? 'My Account' : 'Seat or Active Staff'}</label>
                  ${canSwitchEnrolTarget ? `
                    <div class="enrol-seat-step-btns">
                      <button type="button" class="enrol-step-btn" id="enrolOpenStaffStudioBtn">${ic('camera')} Staff Studio</button>
                      <button type="button" class="enrol-step-btn" id="enrolPrevUserBtn" aria-label="Previous seat or staff">‹ Prev</button>
                      <button type="button" class="enrol-step-btn" id="enrolNextUserBtn" aria-label="Next seat or staff">Next ›</button>
                    </div>
                  ` : ''}
                </div>
                <select id="enrolUserSelect" class="enrol-select" ${canSwitchEnrolTarget ? '' : 'disabled'}>
                  ${hideRoleAndRlsCols ? `
                    <option value="${esc(me.id)}" selected>
                      ${esc(me.full_name)} (${userFacePoseCount(me) ? userFacePoseCount(me) + '/3 poses' : 'no Face ID'})
                    </option>
                  ` : `
                    <optgroup label="Team Login Seats">
                      ${visUsers.filter(u => u.status !== 'Suspended').map(u => `
                        <option value="${esc(u.id)}" ${String(u.id) === String(enrolUser.id) ? 'selected' : ''}>
                          ${esc(u.full_name)} (${userFacePoseCount(u) ? userFacePoseCount(u) + '/3 poses' : 'no Face ID'})
                        </option>
                      `).join('')}
                    </optgroup>
                    <optgroup label="Active Staff (Kiosk Face ID)">
                      ${getKioskStaffDirectory({ scopeByActiveIndustry: true }).filter(s => !s.userObj).map(s => {
                        const stVal = 'stfbio:' + norm(s.name);
                        const fCnt = s.faceCount || 0;
                        return `
                          <option value="${esc(stVal)}" ${String(enrolUser.id) === stVal ? 'selected' : ''}>
                            ${esc(s.name)} · ${esc(s.company)} (${fCnt ? fCnt + '/3 poses' : 'no Face ID'})
                          </option>
                        `;
                      }).join('')}
                    </optgroup>
                  `}
                </select>
                <label class="enrol-config-lbl" for="enrolSeatAuthModeSelect" style="margin-top:6px">Seat Sign-In Requirement</label>
                <select id="enrolSeatAuthModeSelect" class="enrol-select" ${(owner && !enrolUser.isKioskStaffOnly) ? '' : 'disabled'}>
                  <option value="inherit" ${(!enrolUser.auth_mode || enrolUser.auth_mode === 'inherit') ? 'selected' : ''}>Workspace Default (${esc((AUTH_MODE_OPTIONS.find(o => o.value === getWorkspaceAuthMode()) || AUTH_MODE_OPTIONS[1]).short)})</option>
                  ${AUTH_MODE_OPTIONS.map(o => `<option value="${esc(o.value)}" ${enrolUser.auth_mode === o.value ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}
                </select>
              </div>
              <div class="enrol-config-card enrol-policy-card">
                <span class="enrol-config-lbl">Workspace Sign-In &amp; Liveness Policy${owner ? '' : ' (Owner Policy)'}</span>
                <div class="enrol-policy-subgrid">
                  <div class="enrol-policy-field enrol-policy-field-wide">
                    <label for="enrolAuthModeSelect">Workspace Default Sign-In</label>
                    <select id="enrolAuthModeSelect" class="enrol-select" ${owner ? '' : 'disabled'}>
                      ${AUTH_MODE_OPTIONS.map(o => `<option value="${esc(o.value)}" ${getWorkspaceAuthMode() === o.value ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}
                    </select>
                  </div>
                  <div class="enrol-policy-field">
                    <label for="enrolLivenessModeSelect">Anti-Screenshot Liveness</label>
                    <select id="enrolLivenessModeSelect" class="enrol-select" ${owner ? '' : 'disabled'}>
                      ${LIVENESS_MODE_OPTIONS.map(o => `<option value="${esc(o.value)}" ${(STATE.faceSettings.liveness === false ? 'off' : (STATE.faceSettings.livenessMode || 'blink_or_turn')) === o.value ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}
                    </select>
                  </div>
                  <div class="enrol-policy-field">
                    <label for="enrolConfirmFramesSelect">Multi-Frame Lock</label>
                    <select id="enrolConfirmFramesSelect" class="enrol-select" ${owner ? '' : 'disabled'}>
                      <option value="3" ${Math.max(3, Number(STATE.faceSettings.confirmFrames || 3)) === 3 ? 'selected' : ''}>3 Frames (Fast · 0.5s)</option>
                      <option value="4" ${Number(STATE.faceSettings.confirmFrames) === 4 ? 'selected' : ''}>4 Consecutive Frames</option>
                      <option value="5" ${Number(STATE.faceSettings.confirmFrames) === 5 ? 'selected' : ''}>5 Frames (Max Security)</option>
                    </select>
                  </div>
                </div>
                <input type="checkbox" id="enrolRequire2faCb" ${getWorkspaceAuthMode() === 'both' ? 'checked' : ''} hidden aria-hidden="true">
                <input type="checkbox" id="enrolLivenessCb" ${STATE.faceSettings.liveness !== false ? 'checked' : ''} hidden aria-hidden="true">
              </div>
            </div>

            ${(() => {
              const pgm = getEnrolPoseGuideModel();
              return `
                <div class="mfg-pose-guide ${pgm.stateCls}" id="enrolPoseGuide">
                  <div class="mfg-pose-main" id="enrolPoseMain">
                    ${renderEnrolPoseGuideInnerHtml()}
                  </div>
                  <div class="mfg-pose-actions">
                    <button type="button" class="btn btn-brass enrol-action-btn enrol-capture-cta" id="enrolCaptureBtn">${pgm.capBtnHtml}</button>
                    <button type="button" class="btn enrol-action-btn enrol-clear-btn" id="enrolClearBtn" ${(enrolSavedCount || capCount) ? '' : 'hidden'} aria-label="Clear Face ID">${ENROL_SVGS.trash}<span>Clear</span></button>
                  </div>
                </div>
              `;
            })()}

            <div class="enrol-status-bar sr-only" id="enrolStatusBar" hidden>${esc(FACE_STATE.enrolStatusText)}</div>

            <div id="enrolCalibWrap" ${FACE_STATE.calibReportHtml ? '' : 'hidden'}>${FACE_STATE.calibReportHtml}</div>
          </div>
        </div>
      </div>

      ${(window.ISABI_PASSKEYS && typeof window.ISABI_PASSKEYS.renderPasskeysPanelHtml === 'function')
        ? window.ISABI_PASSKEYS.renderPasskeysPanelHtml({
            activeUser: me,
            users: STATE.users,
            isOwner: owner,
            isDemo: isDemoScopeActive(),
            hasServerApi: hasServerApi()
          })
        : ''}

      <div class="panel-card" style="margin-bottom:14px">
        <div class="panel-head">
          <div class="panel-title"><span>${hideRoleAndRlsCols ? 'MY ACCOUNT &amp; SIGN-IN SECURITY' : (tier === 'supervisor' ? 'BUSINESS-UNIT TEAM LOGIN DIRECTORY' : 'TEAM LOGIN DIRECTORY &amp; ROW-LEVEL SECURITY (RLS) SCOPES')}</span></div>
          <div style="display:flex;gap:6px">
            <button class="btn" style="padding:4px 10px;font-size:11px" id="syncCloudNowBtn">↻ Sync Cloud Now</button>
            ${owner ? `<button class="btn btn-primary" style="padding:4px 10px;font-size:11px" id="addWebUserBtn">+ New Team Login</button>` : ''}
          </div>
        </div>
        <div class="table-wrap">
          <table class="ledger-table">
            <thead>
              <tr>
                <th>User Name</th>
                <th>Login Email</th>
                ${owner && !STATE.demoVisitor ? '<th>PIN</th>' : ''}
                <th>Face ID (2FA)</th>
                ${hideRoleAndRlsCols ? '' : `
                <th>Roles &amp; Permissions</th>
                <th>Allowed Companies (RLS)</th>
                `}
                <th>Status</th>
                <th>Last Login</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody id="usersDirectoryTbody">
              ${renderUsersDirectoryRowsHtml()}
            </tbody>
          </table>
        </div>
      </div>

      <div class="split-grid-2">
        <div class="panel-card" id="usersSessionAuditPanel">
          <div class="panel-head">
            <div class="panel-title"><span>${hideRoleAndRlsCols ? 'MY RECENT SIGN-IN ACTIVITY' : (tier === 'supervisor' ? 'BUSINESS-UNIT SESSION AUDIT LOG' : 'LIVE MULTI-DEVICE SESSION AUDIT LOG')}</span></div>
            <span class="badge ${/Live/.test(STATE.cloudStatus) ? 'badge-ok' : 'badge-warn'}">${/Live/.test(STATE.cloudStatus) ? 'CLOUD SYNCED' : 'LOCAL ONLY'}</span>
          </div>
          <div class="table-wrap">
            <table class="ledger-table">
              <thead>
                <tr>
                  <th>Timestamp</th>
                  <th>Team Member</th>
                  <th>Auth Method</th>
                  ${hideRoleAndRlsCols ? '' : '<th>Role / Scope</th>'}
                  <th>Device</th>
                </tr>
              </thead>
              <tbody id="usersSessionAuditTbody">
                ${visSessions.map(s => {
                  const sBadge = formatCompactCompaniesBadge(filterCompaniesForViewer(s.companies, me), 3);
                  return `
                  <tr>
                    <td class="mono" style="font-size:10.5px">${esc(s.logged_in_at)}</td>
                    <td><strong>${esc(s.full_name)}</strong></td>
                    <td><span class="badge ${/Face/i.test(s.method || '') ? 'badge-ok' : 'badge-info'}">${esc(s.method || 'PIN')}${s.confidence ? ` · ${Math.round(Number(s.confidence))}%` : ''}</span></td>
                    ${hideRoleAndRlsCols ? '' : `<td><span class="badge badge-brass" data-ui-tip="${esc(sBadge.fullTitle)}">${esc(sBadge.text)}</span></td>`}
                    <td class="mono" style="font-size:10.5px">${esc(s.device)}</td>
                  </tr>`;
                }).join('') || emptyRow(hideRoleAndRlsCols ? 4 : 5, 'No sign-ins recorded yet')}
              </tbody>
            </table>
          </div>
        </div>

        <div class="panel-card">
          <div class="panel-head">
            <div class="panel-title"><span>CLOUD DATABASE BACKENDS (DUAL-DRIVER)</span></div>
            <span class="badge badge-ok">ACTIVE</span>
          </div>
          <div style="font-size:12px;display:flex;flex-direction:column;gap:0">
            <div class="sentinel-item ${/Live/.test(STATE.cloudStatus) ? 'ok' : 'warn'}">
              <div>
                <div class="sentinel-title">Driver 1: BHFIRMS Multi-Device Cloud Relay + Local SQLite</div>
                <div class="sentinel-detail">Active across phones, tablets &amp; laptops at <code class="mono">isabisystems.com/app</code>; on the LAN host <code class="mono">server.py</code> also writes every entry into <code class="mono">data/mfg.db</code>. Syncs seats, PINs, sessions and app entries with 0 licenses.</div>
              </div>
              <span class="badge ${/Live/.test(STATE.cloudStatus) ? 'badge-ok' : 'badge-warn'}">${/Live/.test(STATE.cloudStatus) ? 'CONNECTED' : esc(STATE.cloudStatus.replace('● ', '').toUpperCase())}</span>
            </div>
            <div class="sentinel-item ${sbConfigured ? 'ok' : ''}">
              <div style="width:100%">
                <div class="sentinel-title">Driver 2: Dedicated Supabase / PostgreSQL Cloud (Optional)</div>
                <div class="sentinel-detail" style="margin-bottom:6px">Run <code class="mono">data/schema_postgres.sql</code> in a Supabase project and paste the URL &amp; anon key. The keys are kept on this device only; the Postgres writer ships in a later build.</div>
                ${owner ? `<div style="display:flex;gap:6px;flex-wrap:wrap">
                  <input type="url" id="sb_url" class="search-input" style="min-width:170px;flex:1;padding:4px 8px;font-size:11px" value="${esc(STATE.supabaseCfg.url)}" placeholder="https://xyz.supabase.co">
                  <input type="text" id="sb_key" class="search-input" style="min-width:140px;flex:1;padding:4px 8px;font-size:11px" value="${esc(STATE.supabaseCfg.anonKey)}" placeholder="Supabase anon key...">
                  <button class="btn" id="saveSbCfgBtn" style="padding:4px 9px;font-size:11px">Save</button>
                </div>` : ''}
              </div>
              <span class="badge ${sbConfigured ? 'badge-ok' : 'badge-neutral'}">${sbConfigured ? 'KEYS SAVED' : 'NOT CONFIGURED'}</span>
            </div>
          </div>
        </div>
      </div>

      ${(owner || tier === 'supervisor') ? renderGeoAuditPanelHtml('usersGeoAuditPanel', 'userGeoAuditFilter', { industry: 'all', company: 'all' }) : ''}

      <div class="panel-card system-showcase-card" id="systemShowcasePanel">
        <div class="system-showcase-inner">
          <div class="system-showcase-lead">
            <div class="system-showcase-crest" aria-hidden="true">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="-9.5 -78.8 74.66 109.7" width="32" height="32" focusable="false">
                <g fill="currentColor">
                  <path transform="translate(-8.45,0)" d="M8.45 0V-68.75H28.81V0Z"/>
                  <path transform="translate(-10.45,0)" d="M45.75 0V-68.75H66.11V0Z"/>
                </g>
                <g fill="var(--badge-rule, #B88228)">
                  <rect x="0" y="9.5" width="55.66" height="3.4"/>
                  <rect x="0" y="17.5" width="55.66" height="3.4"/>
                </g>
              </svg>
            </div>
            <div class="system-showcase-copy">
              <div class="system-showcase-head">
                <div class="system-showcase-title">ISABI Systems Public Showcase &amp; Architecture Blueprints</div>
                <div class="system-showcase-tags">
                  <span class="badge badge-neutral">8 Industry Blueprints</span>
                  <span class="badge badge-neutral">18 Custom Modules</span>
                  <span class="badge badge-neutral">Custom Setup + Per-Seat</span>
                </div>
              </div>
              <div class="system-showcase-sub">Explore the public ISABI Systems overview, interactive multi-industry ERP and executive analytics blueprints, live sandbox tours, and tailored setup + per-seat plans.</div>
              <div class="system-showcase-links">
                <span class="sys-link-pill"><strong>Client Website:</strong> <a href="${esc(showcaseHref)}" class="sys-link-url">isabisystems.com</a> <button type="button" class="sys-link-copy-btn" data-copy-isabi-url="https://isabisystems.com/">Copy</button></span>
                <span class="sys-link-pill"><strong>ISABI App:</strong> <a href="./" class="sys-link-url">isabisystems.com/app</a> <button type="button" class="sys-link-copy-btn" data-copy-isabi-url="https://isabisystems.com/app/">Copy</button></span>
              </div>
            </div>
          </div>
          <a href="${esc(showcaseHref)}" class="btn system-showcase-btn" id="railShowcaseLink" aria-label="Public Showcase">
            <i class="nav-ico" aria-hidden="true">${ic('showcase')}</i>
            <span>Client Website</span>
          </a>
        </div>
      </div>
    `;
  }

  // ==========================================================================
  // SMART ENTRY DESK — SIX FORMS WITH THE DATAVERSE FORM RULES
  // ==========================================================================
  const FORM_TITLES = Object.assign({
    sales: 'New Sales Ticket',
    raw: 'New Raw Material Ticket',
    receipt: 'New Customer Settlement',
    fuel: 'New Fuel & Lubricant Intake',
    malfunction: 'New Malfunction & Discrepancy',
    expense: 'New Expense',
    warehousestock: 'Warehouse Shelf Stock & Adjustment',
    settlement: 'New Supplier Settlement',
    repair: 'New Equipment Repair (Warehouse & Outside)',
    oillog: 'New Equipment Oil & Service Log',
    item: 'New Item & Spare Part (Universal Catalog)',
    staff: 'New Staff Member (Universal Registry)',
    staffrole: 'New Staff Role (Universal Registry)',
    staffassignment: 'Log Staff Role & Equipment Assignment',
    workshift: 'New Shift & Clock Timing',
    document: 'Save Document, Invoice or Receipt'
  }, (window.MFG_FORMS && window.MFG_FORMS.FORM_TITLES) || {});
  const FORM_CR_KEY = Object.assign({
    sales: 'sales_tickets', raw: 'raw_purchases', receipt: 'receipts',
    fuel: 'fuel_intakes', malfunction: 'fuel_malfunctions', expense: 'expenses',
    recurringexpense: 'recurring_expenses',
    warehousestock: 'warehouse_movements', settlement: 'settlements',
    repair: 'equipment_repairs', oillog: 'equipment_oil_logs', item: 'items',
    staff: 'staff_members', staffrole: 'staff_roles', staffassignment: 'staff_assignments',
    workshift: 'work_shifts', document: 'documents'
  }, (window.MFG_FORMS && window.MFG_FORMS.FORM_CR_KEY) || {});

  function secHdr(title, sub, opts = {}) {
    return `<div class="pa-form-sec-hdr"${opts.id ? ` id="${esc(opts.id)}"` : ''}><span>${title}</span>${opts.rightHtml || (sub ? `<small>${sub}</small>` : '')}</div>`;
  }
  function fld(label, inner, opts = {}) {
    const lockAttr = opts.lockField ? ` data-policy-lock="${esc(opts.lockField)}" data-lock-reason="${esc(opts.lockReason || 'Locked by business rule')}"` : '';
    const lockPill = opts.lockField ? `<span class="pa-lock-pill locked" data-lock-pill="${esc(opts.lockField)}" data-toggle-field-lock="${esc(opts.lockField)}" title="${esc(opts.lockReason || 'Locked by policy')}">${ic('lock')} <span class="lp-short">Locked</span><span class="sr-only"> LOCKED</span></span>` : '';
    return `<div class="form-field${opts.span ? ' span-3' : ''}${opts.cls ? ' ' + opts.cls : ''}${opts.lockField ? ' is-policy-locked' : ''}"${opts.id ? ` id="${opts.id}"` : ''}${lockAttr}${opts.hidden ? ' hidden' : ''}><label><span class="pa-fld-lbl">${label}</span>${lockPill}</label>${inner}${opts.afterHtml || ''}${opts.hint != null ? `<span class="hint"${opts.hintId ? ` id="${opts.hintId}"` : ''}>${opts.hint}</span>` : ''}</div>`;
  }
  function inp(id, type, value, attrs = '') {
    if (type === 'time') {
      const normTime = value == null || value === '' ? '' : normalize24hClockTime(value, String(value));
      return `<input type="text" data-time24="1" inputmode="numeric" maxlength="5" placeholder="HH:MM" class="pa-time24-input mono" id="${id}" value="${esc(normTime)}" autocomplete="off" ${attrs}>`;
    }
    return `<input type="${type}" id="${id}" value="${esc(value == null ? '' : value)}" autocomplete="off" ${attrs}>`;
  }
  function sel(id, options, value, attrs = '') {
    return `<select id="${id}" ${attrs}>${options.map(o => {
      const [v, l] = Array.isArray(o) ? o : [o, o];
      return `<option value="${esc(v)}" ${String(v) === String(value) ? 'selected' : ''}>${esc(l)}</option>`;
    }).join('')}</select>`;
  }
  function dl(id, values) {
    if (!values || !values.length) return `<datalist id="${id}"></datalist>`;
    let inner = values._dlHtml;
    if (inner === undefined) {
      inner = values.map(v => `<option value="${esc(v)}">`).join('');
      if (Array.isArray(values)) values._dlHtml = inner;
    }
    return `<datalist id="${id}">${inner}</datalist>`;
  }
  function dlMeta(id, items) {
    if (!items || !items.length) return `<datalist id="${id}"></datalist>`;
    let inner = items._dlMetaHtml;
    if (inner === undefined) {
      inner = items.map(it => {
        const [v, m] = Array.isArray(it) ? it : [it, ''];
        return `<option value="${esc(v)}"${m ? ` data-meta="${esc(m)}"` : ''}>`;
      }).join('');
      if (Array.isArray(items)) items._dlMetaHtml = inner;
    }
    return `<datalist id="${id}">${inner}</datalist>`;
  }
  function nowHHMM() {
    const d = new Date();
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  }

  function formatProductMetaBadge(prodObj, fallbackName) {
    const p = prodObj || productInfo(fallbackName);
    const u = p ? (p.uom || 'm³') : 'm³';
    const tf = resolveProductTonFactor(p, fallbackName || (p && p.name));
    const tfMeta = tf > 0 && tf !== 1 ? ` · 1 m³ = ${tf} t` : '';
    return `${u}${tfMeta}`;
  }

  function salesProductMetaItems(company) {
    return productList(true, 'sales', company).map(p => [p.name, formatProductMetaBadge(p, p.name)]);
  }

  function rawProductMetaItems(company) {
    const fIdx = getFreqIndex();
    const seen = new Set();
    const names = [];
    const pushName = nm => {
      const s = String(nm || '').trim();
      const k = norm(s);
      if (k && !seen.has(k)) { seen.add(k); names.push(s); }
    };
    (SEED.records.raw_purchases || []).forEach(r => { if (r && !r.voided) pushName(r.product); });
    (SEED.records.products || []).forEach(p => {
      if (!p || !p.name) return;
      if (p.ticket_product !== false && (!p.type || /material/i.test(p.type) || (fIdx.productRawTickets.get(norm(p.name)) || 0) > 0 || (fIdx.productRawRules.get(norm(p.name)) || 0) > 0)) {
        pushName(p.name);
      }
    });
    names.sort((a, b) => compareProductByDomain(a, b, 'raw', company, fIdx));
    return names.map(nm => [nm, formatProductMetaBadge(null, nm)]);
  }

  function domainProductMetaItems(side, company) {
    const fIdx = getFreqIndex();
    const seen = new Set();
    const names = [];
    const pushName = nm => {
      const s = String(nm || '').trim();
      const k = norm(s);
      if (k && !seen.has(k)) { seen.add(k); names.push(s); }
    };
    (SEED.records.products || []).forEach(p => { if (p && p.name) pushName(p.name); });
    if (side === 'raw') {
      (SEED.records.raw_purchases || []).forEach(r => { if (r && !r.voided) pushName(r.product); });
    } else if (side === 'sales' || side === 'comm') {
      (SEED.records.sales_tickets || []).forEach(r => { if (r && !r.voided) pushName(r.product); });
    }
    names.sort((a, b) => compareProductByDomain(a, b, side, company, fIdx));
    return names.map(nm => [nm, formatProductMetaBadge(null, nm)]);
  }

  function fuelProductMetaItems(company) {
    const fIdx = getFreqIndex();
    const base = [
      ['Diesel', 'Bulk Fuel (L)'],
      ['Oil 68', 'Hydraulic 68 (L)'],
      ['Oil 15W40', 'Engine Oil (L)'],
      ['Grease', 'Daily Chassis & Pin Grease (kg)'],
      ['Oil 90', 'Gear / Diff 80W-90 (L)'],
      ['Oil ATF / Gearbox', 'Transmission / Steering (L)'],
      ['Other lubricant', 'Lubricant (L)']
    ];
    return base.slice().sort((a, b) => {
      if (a[0] === 'Other lubricant') return 1;
      if (b[0] === 'Other lubricant') return -1;
      return compareProductByDomain(a[0], b[0], 'fuel', company, fIdx);
    });
  }

  const ORIGIN_COMPASS_SVG = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><polygon points="16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76"/></svg>';
  const ORIGIN_HOME_SVG = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 10.5L12 3l9 7.5"/><path d="M5 9.8V20h14V9.8"/></svg>';
  const ORIGIN_BU_SVG = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 20V8h6v12"/></svg>';
  const ORIGIN_PIN_SVG = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s7-6.2 7-12a7 7 0 1 0-14 0c0 5.8 7 12 7 12z"/><circle cx="12" cy="9" r="2.5"/></svg>';
  const ORIGIN_MAP_SVG = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6"/><line x1="8" y1="2" x2="8" y2="18"/><line x1="16" y1="6" x2="16" y2="22"/></svg>';

  function buildOriginModePillsInnerHtml(company, mode, originBu) {
    const allBus = (window.MFG_GEO && Array.isArray(window.MFG_GEO.BU_LIST))
      ? window.MFG_GEO.BU_LIST
      : ['WTC', 'BBConstruction', 'Lions Transport'];
    const sibBus = allBus.filter(b => norm(b) !== norm(company));
    return `
      <button type="button" class="origin-pill${mode === 'company' ? ' active' : ''}" data-origin-mode="company">${ORIGIN_HOME_SVG}<span id="originDefaultBuLbl">${esc(company)}</span></button>
      ${sibBus.map(b => `<button type="button" class="origin-pill${mode === 'bu' && norm(originBu) === norm(b) ? ' active' : ''}" data-origin-mode="bu" data-origin-bu="${esc(b)}">${ORIGIN_BU_SVG}<span>${esc(b)}</span></button>`).join('')}
      <button type="button" class="origin-pill${mode === 'site' ? ' active' : ''}" data-origin-mode="site">${ORIGIN_PIN_SVG}<span>Other Site</span></button>
    `;
  }

  function renderOriginDispatchBarHtml(company, side) {
    const initOriginSites = [];
    return `
      <div class="origin-dispatch-card" id="wrap_f_origin_bar" data-origin-side="${esc(side)}" data-active-mode="company"${side === 'sales' ? ' hidden' : ''}>
        <div class="origin-dispatch-top">
          <div class="origin-dispatch-left">
            <span class="origin-dispatch-lbl">${ORIGIN_COMPASS_SVG}Starting Point</span>
            <div class="origin-mode-pills" id="originModePills" role="group" aria-label="Starting Point" data-rendered-co="${esc(company)}" data-rendered-mode="company:">
              ${buildOriginModePillsInnerHtml(company, 'company', '')}
            </div>
          </div>
          <div class="origin-top-actions">
            <span class="origin-km-badge" id="originKmBadge" hidden></span>
            <span class="origin-eta-pill" id="originEtaPill" hidden></span>
            <button type="button" class="origin-edit-km-btn" id="originEditKmBtn" hidden>Set KM</button>
            <button type="button" class="origin-map-toggle-btn" id="toggleOriginMiniMapBtn" aria-expanded="false">${ORIGIN_MAP_SVG}<span>Route Map</span></button>
          </div>
        </div>
        <div class="origin-km-edit-bar" id="originKmEditBar" hidden>
          <span style="font-weight:600;color:var(--ink)">Exact One-Way KM:</span>
          <div style="display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap">
            <input type="number" id="originInlineKmInp" step="0.1" min="0" placeholder="km">
            <button type="button" class="geo-mini-btn primary" id="originSaveKmBtn">Save KM</button>
            <button type="button" class="geo-mini-btn" id="originResetKmBtn">Auto Map KM</button>
          </div>
        </div>
        <div class="origin-minimap-drawer" id="originMiniMapDrawer" hidden>
          <div class="origin-minimap-bar">
            <div class="origin-minimap-targets">
              <span style="font-weight:700;color:var(--muted)">Map Click Action:</span>
              <button type="button" class="origin-map-target-pill active" data-origin-map-target="dest" id="originMapTargetDestBtn">${side === 'raw' ? 'Set Site' : 'Set Destination'}</button>
              <button type="button" class="origin-map-target-pill" data-origin-map-target="origin" id="originMapTargetOrigBtn">Set Starting Point</button>
            </div>
            <span class="muted" id="originMiniMapHint" style="font-size:0.7rem">Click any pin or BU hub on map</span>
          </div>
          <div class="origin-minimap-canvas" id="originMiniMapCanvas"></div>
        </div>
        <div class="origin-site-drawer" id="wrap_origin_site_fields" hidden>
          <div class="origin-freq-strip" id="originFreqStrip"></div>
          <div class="origin-site-subgrid">
            ${fld('Starting Site *', inp('f_origin_site', 'text', '', 'list="dl_origin_sites" placeholder="Search site by frequency (Raw & Sales)..."') + dlMeta('dl_origin_sites', initOriginSites), { id: 'wrap_f_origin_site', hintId: 'hint_origin_site', hint: '' })}
            ${fld('Prior Ticket # (Last 24h · Optional)', inp('f_origin_ticket', 'text', '', 'list="dl_origin_tickets" placeholder="Select 24h Raw or Sales ticket (optional)..."') + dlMeta('dl_origin_tickets', []), { id: 'wrap_f_origin_ticket', hintId: 'hint_origin_ticket', hint: '' })}
          </div>
          <div class="origin-24h-cards-wrap" id="origin24hCardsWrap" hidden></div>
        </div>
        <div class="origin-redirect-banner" id="originRedirectBanner" hidden></div>
      </div>
    `;
  }

  function syncOriginDispatchUI(side, allowAutoFill = true) {
    const company = val('f_company') || defaultEntryCompany();
    const originBarEl = $('wrap_f_origin_bar');
    if (!window.MFG_GEO || !originBarEl) {
      return {
        originType: 'company',
        originName: company,
        originSite: '',
        originTicketNo: '',
        originTicketKind: '',
        originTicketId: '',
        estKm: null,
        estRoundTripKm: null,
        priorDisposition: 'keep',
        matchedPrior: null
      };
    }

    let mode = FORM_UI.originMode || 'company';
    let originBu = FORM_UI.originBu || '';
    if (mode === 'bu' && (!originBu || norm(originBu) === norm(company))) {
      mode = 'company';
      originBu = '';
      FORM_UI.originMode = 'company';
      FORM_UI.originBu = '';
    }
    originBarEl.setAttribute('data-active-mode', mode);

    const pillsEl = $('originModePills');
    const modeStamp = `${mode}:${originBu}`;
    if (pillsEl && (pillsEl.dataset.renderedCo !== company || pillsEl.dataset.renderedMode !== modeStamp)) {
      pillsEl.innerHTML = buildOriginModePillsInnerHtml(company, mode, originBu);
      pillsEl.dataset.renderedCo = company;
      pillsEl.dataset.renderedMode = modeStamp;
    }

    const siteSubEl = $('wrap_origin_site_fields');
    if (siteSubEl) siteSubEl.hidden = mode !== 'site';

    const effDate = (FORM_UI.repDateManual && val('f_repdate')) ? val('f_repdate') : (val('f_date') || todayISO());
    const effTime = val('f_time') || nowHHMM();
    const curTruck = val('f_truck');
    let _stats = null;
    const getStats = () => _stats || (_stats = window.MFG_GEO.getUnifiedSiteStats(SEED, STATE));
    let originSite = '';
    let matchedPrior = null;
    let rawTktVal = '';

    if (mode === 'site') {
      const stats = getStats();
      const dlSitesEl = $('dl_origin_sites');
      const sitesCacheKey = `${company}|${effDate}|${effTime}|${curTruck}|${SEED._customRev || 0}`;
      let metaItems = null;
      if (dlSitesEl && dlSitesEl.dataset.cacheKey !== sitesCacheKey) {
        metaItems = window.MFG_GEO.getUnifiedSiteMetaItems(SEED, STATE, {
          side: 'both',
          date: effDate,
          time: effTime,
          truck: curTruck
        });
        dlSitesEl.innerHTML = metaItems.map(([v, m]) => `<option value="${esc(v)}"${m ? ` data-meta="${esc(m)}"` : ''}>`).join('');
        dlSitesEl.dataset.cacheKey = sitesCacheKey;
      }

      originSite = val('f_origin_site');
      const freqStripEl = $('originFreqStrip');
      const freqStamp = `${sitesCacheKey}|${norm(originSite)}`;
      if (freqStripEl && freqStripEl.dataset.cacheKey !== freqStamp) {
        if (!metaItems) {
          metaItems = window.MFG_GEO.getUnifiedSiteMetaItems(SEED, STATE, {
            side: 'both',
            date: effDate,
            time: effTime,
            truck: curTruck
          });
        }
        const topSites = metaItems.slice(0, 6);
        freqStripEl.innerHTML = topSites.length
          ? `<span class="origin-freq-lbl">Frequent Sites:</span>` + topSites.map(([sName, sMeta]) => {
              const isAct = Boolean(originSite && norm(originSite) === norm(sName));
              const isTruckStop = /stop \(/i.test(String(sMeta || ''));
              const stRow = stats && stats.byNorm ? stats.byNorm.get(norm(sName)) : null;
              const cntBadge = isTruckStop ? '24h Truck' : (stRow && stRow.total > 0 ? fmtNum(stRow.total) : '');
              return `<button type="button" class="origin-freq-chip${isTruckStop ? ' is-truck-stop' : ''}${isAct ? ' active' : ''}" data-pick-origin-site="${esc(sName)}"><span>${esc(sName)}</span>${cntBadge ? `<span class="origin-freq-chip-cnt">${esc(cntBadge)}</span>` : ''}</button>`;
            }).join('')
          : '';
        freqStripEl.dataset.cacheKey = freqStamp;
      }

      const stObj = originSite && stats && stats.byNorm ? stats.byNorm.get(norm(originSite)) : null;
      if (originSite && stObj) {
        setHint('hint_origin_site', `${stObj.region ? 'Zone: ' + stObj.region + ' · ' : ''}${fmtNum(stObj.raw)} Raw · ${fmtNum(stObj.sales)} Sales loads`, '');
      } else if (originSite) {
        setHint('hint_origin_site', 'Custom starting site', '');
      } else {
        setHint('hint_origin_site', 'Click a frequent site above or search by Raw & Sales frequency', '');
      }

      const recent24h = originSite
        ? window.MFG_GEO.getSiteLast24hTickets(SEED, STATE, { site: originSite, date: effDate, time: effTime, truck: curTruck })
        : [];
      const noCounts = new Map();
      recent24h.forEach(t => noCounts.set(norm(t.ticket_no), (noCounts.get(norm(t.ticket_no)) || 0) + 1));

      const dlTktsEl = $('dl_origin_tickets');
      const tktsCacheKey = `${norm(originSite)}|${effDate}|${effTime}|${curTruck}|${recent24h.length}|${SEED._customRev || 0}`;
      if (dlTktsEl && dlTktsEl.dataset.cacheKey !== tktsCacheKey) {
        dlTktsEl.innerHTML = recent24h.map(t => {
          const optVal = (noCounts.get(norm(t.ticket_no)) > 1) ? `${t.ticket_no} (${t.kindLabel})` : t.ticket_no;
          return `<option value="${esc(optVal)}" data-meta="${esc(t.metaLabel)}">`;
        }).join('');
        dlTktsEl.dataset.cacheKey = tktsCacheKey;
      }

      rawTktVal = val('f_origin_ticket');
      if (rawTktVal) {
        matchedPrior = recent24h.find(t =>
          norm(t.ticket_no) === norm(rawTktVal) ||
          norm(`${t.ticket_no} (${t.kindLabel})`) === norm(rawTktVal)
        ) || null;
      }

      if (!rawTktVal) {
        FORM_UI.lastAutoFilledOriginTicket = '';
      } else if (allowAutoFill && matchedPrior && FORM_UI.lastAutoFilledOriginTicket !== matchedPrior.id) {
        FORM_UI.lastAutoFilledOriginTicket = matchedPrior.id;
        if (!val('f_truck') && matchedPrior.truck && $('f_truck')) {
          if (side === 'sales' && $('f_saletype') && val('f_saletype') === 'Pickup' && !val('f_customer')) {
            $('f_saletype').value = 'Delivery';
          }
          const eq = equipInfo(matchedPrior.truck, company, false);
          const isOwn = eq ? isOwnUnit(eq, company) : /^company/i.test(matchedPrior.transport_by || '');
          if ($('f_transportby')) {
            $('f_transportby').value = isOwn ? 'Company fleet' : 'Third-party truck';
          }
          $('f_truck').value = matchedPrior.truck;
          FORM_UI.qtyManual = false;
          FORM_UI.driverManual = false;
        }
        if (!val('f_product') && matchedPrior.product && $('f_product')) {
          $('f_product').value = matchedPrior.product;
          if (!isFieldAdminUnlocked('f_unitprice')) FORM_UI.priceManual = false;
        }
      }

      const cardsWrapEl = $('origin24hCardsWrap');
      if (cardsWrapEl) {
        if (originSite && recent24h.length > 0) {
          cardsWrapEl.hidden = false;
          const cardsStamp = `${tktsCacheKey}|${norm(rawTktVal)}|${matchedPrior ? matchedPrior.id : ''}`;
          if (cardsWrapEl.dataset.cacheKey !== cardsStamp) {
            cardsWrapEl.innerHTML = `
              <div class="origin-24h-hdr">
                <span>Last 24h at <b>${esc(originSite)}</b> (${recent24h.length} ${recent24h.length === 1 ? 'ticket' : 'tickets'} · click to link or clear)</span>
                ${matchedPrior ? `<span class="origin-autofill-pill">Linked ${esc(matchedPrior.kindLabel)} #${esc(matchedPrior.ticket_no)}${matchedPrior.truck ? ' · Truck ' + esc(matchedPrior.truck) : ''}</span>` : ''}
              </div>
              <div class="origin-24h-cards-grid">
                ${recent24h.slice(0, 6).map(t => {
                  const optVal = (noCounts.get(norm(t.ticket_no)) > 1) ? `${t.ticket_no} (${t.kindLabel})` : t.ticket_no;
                  const isPicked = Boolean(matchedPrior && matchedPrior.id === t.id);
                  const partyLbl = t.kind === 'sales' ? (t.customer || '') : (t.site_owner || t.truck_owner || '');
                  const prodQtyLbl = t.product ? (t.qty > 0 ? `${t.product} (${fmtNum(t.qty, 2)} ${t.uom || 'm³'})` : t.product) : '';
                  const subLine = [t.truck ? `Truck ${t.truck}` : '', prodQtyLbl, partyLbl].filter(Boolean).join(' · ') || t.company || '';
                  return `
                    <button type="button" class="origin-tkt-card${isPicked ? ' active' : ''}" data-pick-origin-ticket="${esc(optVal)}">
                      <span class="origin-tkt-card-top">
                        <span style="display:inline-flex;align-items:center;gap:6px">
                          <span class="origin-tkt-kind ${t.kind === 'sales' ? 'is-sales' : 'is-raw'}">${esc(t.kindLabel)}</span>
                          <span class="origin-tkt-no">#${esc(t.ticket_no)}</span>
                        </span>
                        <span class="origin-tkt-age">${esc(t.ageLabel)}</span>
                      </span>
                      <span class="origin-tkt-card-sub">${esc(subLine)}</span>
                    </button>
                  `;
                }).join('')}
              </div>
            `;
            cardsWrapEl.dataset.cacheKey = cardsStamp;
          }
        } else {
          cardsWrapEl.hidden = true;
          cardsWrapEl.innerHTML = '';
          cardsWrapEl.dataset.cacheKey = '';
        }
      }

      if (!originSite) {
        setHint('hint_origin_ticket', 'Pick a Starting Site first to suggest last-24h Raw & Sales tickets', '');
      } else if (matchedPrior) {
        setHint('hint_origin_ticket', `Linked ${matchedPrior.kindLabel} #${matchedPrior.ticket_no} (${matchedPrior.ageLabel}${matchedPrior.truck ? ' · Truck ' + matchedPrior.truck : ''}${matchedPrior.product ? ' · ' + matchedPrior.product : ''})`, 'ok');
      } else if (recent24h.length > 0) {
        const sCnt = recent24h.filter(x => x.kind === 'sales').length;
        const rCnt = recent24h.filter(x => x.kind === 'raw').length;
        setHint('hint_origin_ticket', `${recent24h.length} ticket${recent24h.length === 1 ? '' : 's'} at ${originSite} in last 24h (${sCnt} Sales · ${rCnt} Raw) · optional`, '');
      } else {
        setHint('hint_origin_ticket', `No Raw or Sales tickets at ${originSite} in last 24h · optional`, '');
      }
    }

    const redirEl = $('originRedirectBanner');
    if (redirEl) {
      if (side === 'sales' && mode === 'site' && matchedPrior && matchedPrior.kind === 'sales') {
        const disp = FORM_UI.originPriorDisposition || 'keep';
        const pNo = matchedPrior.ticket_no;
        const qtyTxt = matchedPrior.qty > 0 ? ` · ${fmtNum(matchedPrior.qty, 2)} ${matchedPrior.uom || 'm³'}` : '';
        redirEl.hidden = false;
        redirEl.innerHTML = `
          <span class="origin-redirect-copy"><b>Redirected from Sales #${esc(pNo)}</b> (${esc(matchedPrior.customer || 'Customer')}${esc(qtyTxt)}${matchedPrior.product ? ' ' + esc(matchedPrior.product) : ''}) · Original Ticket Action:</span>
          <div class="origin-redirect-actions">
            <button type="button" class="origin-disp-btn${disp === 'keep' ? ' active' : ''}" data-origin-disp="keep">Keep #${esc(pNo)} As-Is</button>
            <button type="button" class="origin-disp-btn${disp === 'return' ? ' active' : ''}" data-origin-disp="return">Return #${esc(pNo)} on Save</button>
            <button type="button" class="origin-disp-btn${disp === 'void' ? ' active' : ''}" data-origin-disp="void">Void #${esc(pNo)} on Save</button>
          </div>
        `;
      } else {
        redirEl.hidden = true;
        redirEl.innerHTML = '';
        if (FORM_UI.originPriorDisposition && FORM_UI.originPriorDisposition !== 'keep') {
          FORM_UI.originPriorDisposition = 'keep';
        }
      }
    }

    const fromSpec = mode === 'site'
      ? { type: 'site', name: originSite }
      : { type: 'bu', name: mode === 'bu' ? (originBu || company) : company };
    const saleTypeVal = side === 'sales' ? (val('f_saletype') || 'Pickup') : 'Delivery';
    const isSalesNonDelivery = side === 'sales' && saleTypeVal !== 'Delivery';
    const destSite = isSalesNonDelivery ? '' : val('f_site');
    const est = (fromSpec.name && destSite)
      ? window.MFG_GEO.estimateLegKm(fromSpec, { type: 'site', name: destSite }, SEED)
      : null;
    const allowKmOverride = Boolean(!isSalesNonDelivery && fromSpec.name && destSite && canEditTicketPairKm(fromSpec, destSite));
    if (!allowKmOverride) FORM_UI.originKmEditOpen = false;

    const kmBadge = $('originKmBadge');
    const etaPill = $('originEtaPill');
    const editKmBtn = $('originEditKmBtn');
    const kmEditBar = $('originKmEditBar');
    if (kmBadge) {
      if (est && est.available) {
        kmBadge.hidden = false;
        kmBadge.classList.remove('is-idle');
        kmBadge.textContent = (est.showRoundTrip && est.roundTripKm != null)
          ? `One-Way: ${est.oneWayKm.toFixed(1)} km · Round-Trip: ${est.roundTripKm.toFixed(1)} km`
          : `One-Way: ${est.oneWayKm.toFixed(1)} km`;
        if (etaPill) {
          etaPill.hidden = false;
          etaPill.textContent = `~${est.estMinutes} min`;
        }
        if (editKmBtn) {
          editKmBtn.hidden = !allowKmOverride;
          editKmBtn.classList.toggle('active', Boolean(allowKmOverride && FORM_UI.originKmEditOpen));
          editKmBtn.textContent = est.source === 'Custom KM' ? 'Custom KM' : 'Adjust KM';
        }
      } else {
        kmBadge.hidden = true;
        kmBadge.classList.add('is-idle');
        kmBadge.textContent = '';
        if (etaPill) etaPill.hidden = true;
        if (editKmBtn) {
          editKmBtn.hidden = !allowKmOverride;
          editKmBtn.classList.toggle('active', Boolean(allowKmOverride && FORM_UI.originKmEditOpen));
          editKmBtn.textContent = 'Set KM';
        }
      }
    }
    if (kmEditBar) {
      const showKmBar = Boolean(allowKmOverride && FORM_UI.originKmEditOpen);
      if (!showKmBar) FORM_UI.originKmEditOpen = false;
      kmEditBar.hidden = !showKmBar;
      const kmInp = $('originInlineKmInp');
      if (showKmBar && kmInp && document.activeElement !== kmInp) {
        kmInp.value = (est && est.available) ? est.oneWayKm.toFixed(1) : '';
      }
    }

    // Sync Inline Interactive Route Mini-Map Drawer
    const mapToggleBtn = $('toggleOriginMiniMapBtn');
    const miniDrawer = $('originMiniMapDrawer');
    const miniCanvas = $('originMiniMapCanvas');
    const mapOpen = Boolean(FORM_UI.originMiniMapOpen);
    if (mapToggleBtn) {
      mapToggleBtn.classList.toggle('active', mapOpen);
      mapToggleBtn.setAttribute('aria-expanded', mapOpen ? 'true' : 'false');
    }
    if (miniDrawer) miniDrawer.hidden = !mapOpen;
    if (mapOpen && miniCanvas && typeof window.MFG_GEO.wireTicketOriginMiniMap === 'function') {
      const mapTarget = FORM_UI.originMapTarget === 'origin' ? 'origin' : 'dest';
      const tDestBtn = $('originMapTargetDestBtn');
      const tOrigBtn = $('originMapTargetOrigBtn');
      if (tDestBtn) tDestBtn.classList.toggle('active', mapTarget === 'dest');
      if (tOrigBtn) tOrigBtn.classList.toggle('active', mapTarget === 'origin');
      const mapHint = $('originMiniMapHint');
      if (mapHint && !mapHint.dataset.gpsPinned) {
        mapHint.textContent = mapTarget === 'origin'
          ? 'Click a site pin or BU hub on map to set Starting Point'
          : (side === 'raw' ? 'Click any site pin on map to set Source Site' : 'Click any site pin on map to set Destination');
      }
      window.MFG_GEO.wireTicketOriginMiniMap(miniCanvas, {
        SEED,
        STATE,
        fromSpec,
        toSpec: destSite ? { type: 'site', name: destSite } : null,
        onPickBu: buName => {
          const curCo = val('f_company') || defaultEntryCompany();
          if (norm(buName) === norm(curCo)) {
            FORM_UI.originMode = 'company';
            FORM_UI.originBu = '';
          } else {
            FORM_UI.originMode = 'bu';
            FORM_UI.originBu = buName;
          }
          FORM_UI.originPriorDisposition = 'keep';
          FORM_UI.lastAutoFilledOriginTicket = '';
          recalcForm();
        },
        onPickSite: sName => {
          const curTarget = FORM_UI.originMapTarget === 'origin' ? 'origin' : 'dest';
          if (curTarget === 'origin') {
            FORM_UI.originMode = 'site';
            FORM_UI.originBu = '';
            const origInp = $('f_origin_site');
            if (origInp) {
              origInp.value = sName;
              if (!val('f_site')) FORM_UI.originMapTarget = 'dest';
              origInp.dispatchEvent(new Event('change', { bubbles: true }));
            } else {
              recalcForm();
            }
          } else {
            if (side === 'sales' && $('f_saletype') && val('f_saletype') !== 'Delivery') {
              $('f_saletype').value = 'Delivery';
            }
            const siteInp = $('f_site');
            if (siteInp) {
              siteInp.value = sName;
              siteInp.dispatchEvent(new Event('change', { bubbles: true }));
            } else {
              recalcForm();
            }
          }
        },
        onClickMapCoord: (lat, lng) => {
          const det = window.MFG_GEO.findContainingRegion ? window.MFG_GEO.findContainingRegion(lat, lng, SEED) : null;
          const mapHintEl = $('originMiniMapHint');
          if (mapHintEl) {
            mapHintEl.dataset.gpsPinned = '1';
            mapHintEl.textContent = `${det && det.best ? 'Zone: ' + det.best + ' · ' : ''}GPS ${lat.toFixed(4)}, ${lng.toFixed(4)}`;
          }
        },
        onRouteResolved: () => {
          recalcForm();
        }
      });
    } else if (!mapOpen && typeof window.MFG_GEO.cleanupTicketOriginMiniMap === 'function') {
      window.MFG_GEO.cleanupTicketOriginMiniMap();
    }

    const originName = mode === 'site' ? originSite : (mode === 'bu' ? (originBu || company) : company);
    const originPointLabel = mode === 'site'
      ? (originSite ? `${originSite}${matchedPrior ? ' (#' + matchedPrior.ticket_no + ')' : (rawTktVal ? ' (#' + rawTktVal + ')' : '')}` : 'Other Site')
      : originName;

    return {
      originType: mode,
      originName,
      originPoint: originPointLabel,
      originSite: mode === 'site' ? originSite : '',
      originTicketNo: mode === 'site' ? (matchedPrior ? matchedPrior.ticket_no : rawTktVal) : '',
      originTicketKind: (mode === 'site' && matchedPrior) ? matchedPrior.kind : '',
      originTicketId: (mode === 'site' && matchedPrior && matchedPrior.rawRow && matchedPrior.rawRow.id) ? String(matchedPrior.rawRow.id) : '',
      estKm: (est && est.available) ? est.oneWayKm : null,
      estRoundTripKm: (est && est.available && est.showRoundTrip) ? est.roundTripKm : null,
      priorDisposition: (side === 'sales' && mode === 'site' && matchedPrior && matchedPrior.kind === 'sales')
        ? (FORM_UI.originPriorDisposition || 'keep')
        : 'keep',
      matchedPrior
    };
  }

  function applyOriginPriorDisposition(record, extraApiPosts) {
    if (!record || !record.prior_disposition || record.prior_disposition === 'keep') return null;
    if (record.origin_ticket_kind !== 'sales') return null;
    const pool = (STATE.customRecords.sales_tickets || []).concat(SEED.records.sales_tickets || []);
    const orig = pool.find(t => t && !t.voided && (
      (record.origin_ticket_id && String(t.id) === String(record.origin_ticket_id)) ||
      (record.origin_ticket_no && norm(t.ticket_no) === norm(record.origin_ticket_no) && (!record.origin_site || norm(t.site) === norm(record.origin_site)))
    ));
    if (!orig) return null;

    if (!Array.isArray(STATE.customRecords.sales_tickets)) STATE.customRecords.sales_tickets = [];
    if (record.prior_disposition === 'void') {
      orig.voided = true;
      orig.voided_by = record.entered_by_email || '';
      orig.voided_at = record.entered_at || nowStamp();
      orig.void_reason = `Redirected load to Ticket #${record.ticket_no || ''}`;
      orig.redirected_to_ticket = record.ticket_no;
      orig.notes = [orig.notes, `Redirected load to Ticket #${record.ticket_no} (${record.customer || ''})`].filter(Boolean).join(' · ');
      const cIdx = STATE.customRecords.sales_tickets.findIndex(x => x && String(x.id) === String(orig.id));
      if (cIdx >= 0) Object.assign(STATE.customRecords.sales_tickets[cIdx], orig);
      else STATE.customRecords.sales_tickets.unshift(Object.assign({}, orig));
      if (Array.isArray(extraApiPosts)) extraApiPosts.push(['sales_tickets', orig]);
      return { action: 'void', ticketNo: orig.ticket_no };
    }
    if (record.prior_disposition === 'return') {
      const retMethod = isCashSaleTicket(orig) ? 'C Return' : 'CR Return';
      const retTicketNo = `${orig.ticket_no}-RET`;
      const retRec = Object.assign({}, orig, {
        id: uid('sr'),
        name: `RET ${record.date} ${orig.customer || ''} #${retTicketNo}`,
        ticket_no: retTicketNo,
        date: record.date,
        rep_date: record.rep_date || record.date,
        method: retMethod,
        reference: `Redirected to #${record.ticket_no}`,
        notes: `Rejected load returned & redirected to ${record.customer || 'another customer'} on Ticket #${record.ticket_no}`,
        source: 'app',
        entered_by: record.entered_by,
        entered_by_email: record.entered_by_email,
        entered_at: record.entered_at,
        voided: false
      });
      STATE.customRecords.sales_tickets.unshift(retRec);
      if (Array.isArray(extraApiPosts)) extraApiPosts.push(['sales_tickets', retRec]);
      return { action: 'return', ticketNo: orig.ticket_no, returnTicketNo: retTicketNo };
    }
    return null;
  }

