    const toggleRepBtn = $('toggleRepDateBtn');
    if (toggleRepBtn) {
      toggleRepBtn.addEventListener('click', ev => {
        ev.preventDefault();
        if (FORM_UI.showRepDate) {
          FORM_UI.showRepDate = false;
          FORM_UI.repDateManual = false;
          if ($('f_repdate')) $('f_repdate').value = val('f_date');
          recalcForm();
        } else {
          FORM_UI.showRepDate = true;
          recalcForm();
          const rEl = $('f_repdate');
          if (rEl) { try { rEl.focus(); } catch (_) {} }
        }
      });
    }
    const resetRepBtn = $('resetRepDateBtn');
    if (resetRepBtn) {
      resetRepBtn.addEventListener('click', ev => {
        ev.preventDefault();
        FORM_UI.showRepDate = false;
        FORM_UI.repDateManual = false;
        if ($('f_repdate')) $('f_repdate').value = val('f_date');
        recalcForm();
      });
    }
    const pinBatchBtn = $('pinBatchRepDateBtn');
    if (pinBatchBtn) {
      pinBatchBtn.addEventListener('click', ev => {
        ev.preventDefault();
        const curRep = val('f_repdate');
        if (STATE.catchUpBatchRepDate && curRep === STATE.catchUpBatchRepDate) {
          clearCatchUpBatchRepDate({ resetCurrentForm: false });
          return;
        }
        if (!isValidBatchRepDate(curRep)) {
          toast(`Reporting Date must be between ${fmtDateDMY(MIN_DATE)} and today`, 'err');
          return;
        }
        if (curRep === val('f_date')) {
          toast('Pick a Reporting Date different from Transaction Date first', 'warn');
          return;
        }
        setCatchUpBatchRepDate(curRep);
        if (entryModalUserChangedValue() === false) {
          FORM_UI.userInteracted = false;
          FORM_UI.initialModalSig = getEntryModalStateSignature();
          markEntryModalBaseline();
        }
      });
    }
    const toggleAhBtn = $('toggleAfterHoursBtn');
    if (toggleAhBtn) {
      toggleAhBtn.addEventListener('click', ev => {
        ev.preventDefault();
        const dEl = $('f_date');
        if (!dEl) return;
        const today = todayISO();
        const yest = yesterdayISO(today);
        const turningOn = !(FORM_UI.afterHoursYesterday && dEl.value === yest);
        if (turningOn) {
          if (yest < MIN_DATE) return;
          if (!FORM_UI.adminUnlocked.__all) delete FORM_UI.adminUnlocked.f_date;
          FORM_UI.afterHoursYesterday = true;
          dEl.value = yest;
        } else {
          FORM_UI.afterHoursYesterday = false;
          dEl.value = today;
        }
        if (!isFieldAdminUnlocked('f_unitprice')) FORM_UI.priceManual = false;
        if (!isFieldAdminUnlocked('f_transunitprice')) FORM_UI.transManual = false;
        recalcForm();
      });
    }
    const toggleOtBtn = $('toggleOvertimeBtn');
