        chassis_vin: (val('f_vin') ? val('f_vin').toUpperCase().replace(/I/g, '1').replace(/[OQ]/g, '0').replace(/[^A-Z0-9]/g, '') : ((targetExistingRow && (targetExistingRow.chassis_vin || targetExistingRow.vin)) || '')),
