      const outT = fmtAttClockTime(val('f_out_time') || (isSplit ? '15:00' : '16:00')) || (isSplit ? '15:00' : '16:00');
      const splitS2 = fmtAttClockTime(val('f_split_s2') || '19:00') || '19:00';
      const splitE2 = fmtAttClockTime(val('f_split_e2') || '23:00') || '23:00';
