    const pendingExpRow = (form === 'expense' && pendingTargetId) ? findExpenseRecordById(pendingTargetId) : null;
    const pendingRawRow = (form === 'raw' && pendingRawTargetId) ? findRawPurchaseRecordById(pendingRawTargetId) : null;
