        const convAmtEdited = Boolean(($('insp_edit_usd_amount') && $('insp_edit_usd_amount').dataset.userEdited === '1') || ($('insp_edit_lbp_amount') && $('insp_edit_lbp_amount').dataset.userEdited === '1'));
