        if ($('insp_tw_end')) $('insp_tw_end').value = '';
        if ($('insp_tw_own')) $('insp_tw_own').value = targetEqRow.supplier || '';
        if ($('insp_tw_drv')) $('insp_tw_drv').value = targetEqRow.default_driver || '';
        if ($('insp_tw_cust')) $('insp_tw_cust').value = '';
