            recordKey: curCtx.key,
            recordId: curCtx.id,
            row: curCtx.row,
            subgrid: sgId && _inspSubgridUiState[sgId] ? _inspSubgridUiState[sgId].sg : null,
            source: hubBtn.hasAttribute('data-sg-open-hub') ? 'subgrid' : 'cmd'
