    otaChecking: false,
    blackFrameStreak: 0,
    consecutiveBlackRestarts: 0,
    cooldownUntil: 0,
    flashPunch: null,
    flashTimer: null,
    wallClockTimer: null,
    loopTimer: null,
    ensureTimer: null,
    watchdogTimer: null,
    busy: false,
    streakStaff: '',
    streakCount: 0,
    streakVecs: [],
    streakStartedAt: 0,
    livenessHistory: [],
    lastPadResult: null,
    unknownStreak: 0,
    bestDist: 9,
    lastVideoTime: -1,
    lastTimeMoveAt: 0,
    lastRestartAt: 0,
    restartCount: 0,
    lastWatchdogReason: '',
