    activityWired: false,
    originKioskTab: 'attendance',
    camActive: false,
    loopTimer: null,
    busy: false,
    streakAdmin: '',
    streakCount: 0,
    streakVecs: [],
    streakStartedAt: 0,
    livenessHistory: [],
    lastPadResult: null,
    missedFrames: 0,
    statusText: 'Look at the camera to verify Admin or Manager Face ID.',
    statusCls: '',
    err: '',
