  async function saveIndustryKioskEntry(opts = {}) {
    if (STATE.saving) return { ok: false, reason: 'saving' };
    const activeInd = getActiveIndustry(STATE.company);
    const kMode = STATE.activeKiosk || 'sales';
    const numV = id => { const el = $(id); const v = el ? parseFloat(el.value) : 0; return Number.isFinite(v) ? v : 0; };
    const strV = id => { const el = $(id); return el ? String(el.value || '').trim() : ''; };
    const errEl = $('kioskIndErrorBanner');
    const showErr = msg => {
      if (errEl) { errEl.style.display = 'block'; errEl.textContent = msg; }
      toast(msg, 'err');
    };
    if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }

    const indFormHost = $('kioskIndForm');
    if (indFormHost && typeof flushKioskPartyTypoGuard === 'function' && !flushKioskPartyTypoGuard(indFormHost)) {
      return { ok: false, reason: 'party_typo' };
    }
    const co = strV('ik_company') || defaultEntryCompany() || 'Bdeir Holding';
    const dt = strV('ik_date') || todayISO();
    const recId = strV('ik_id');
    if (!recId) {
      showErr('Reference / Voucher ID is required.');
      return { ok: false, errors: ['Reference / Voucher ID is required.'] };
    }

    let postedBucket = '';
    let postedRow = null;

    if (activeInd === 'Insurance & Brokerage') {
      if (kMode === 'sales') {
        const gwp = numV('ik_gwp');
        const rate = numV('ik_rate');
        const grossComm = round2(gwp * (rate / 100));
        const disc = numV('ik_discount');
        if (gwp <= 0) { showErr('Gross Written Premium ($ GWP) must be greater than 0.'); return { ok: false }; }
        if (disc > grossComm + 0.01) { showErr(`Client Discount ($${disc.toFixed(2)}) cannot exceed Gross Commission ($${grossComm.toFixed(2)}).`); return { ok: false }; }
        postedBucket = 'ins_policies';
        postedRow = addIndustryCustomRow('ins_policies', {
          id: recId, company: co, type: 'Policy (New)', start_date: dt, end_date: '2027-10-29', days_to_expiry: 364,
          insured: strV('ik_client') || 'Policyholder', carrier: strV('ik_carrier') || 'MedGulf',
          line: strV('ik_line') || 'MOT · Motor', product: 'Commercial Cover', sum_insured_usd: gwp * 25,
          gwp_usd: gwp, comm_rate_pct: rate, gross_comm_usd: grossComm, discount_usd: disc,
          policy_fee_usd: numV('ik_fee'), net_comm_usd: round2(grossComm - disc),
          carrier_payable_usd: round2(gwp - grossComm), collected_usd: gwp, open_ar_usd: 0,
          producer: activeUser().full_name || 'Desk Officer', status: 'Active'
        });
      } else if (kMode === 'raw') {
        const gwp = numV('ik_gwp');
        const comm = numV('ik_comm');
        const settled = numV('ik_settled');
        const netPay = round2(Math.max(0, gwp - comm));
        postedBucket = 'ins_remittances';
        postedRow = addIndustryCustomRow('ins_remittances', {
          id: recId, company: co, carrier: strV('ik_carrier') || 'MedGulf',
          settlement_mode: 'Net-of-Commission Bordereau', gl_payable: 'Carrier Payables',
          gwp_usd: gwp, comm_usd: comm, net_payable_usd: netPay, settled_usd: settled,
          balance_usd: round2(Math.max(0, netPay - settled)), due_date: dt,
          status: netPay - settled <= 0 ? 'Settled' : 'Part-Settled'
        });
      } else {
        const clm = numV('ik_claimed');
        const ded = numV('ik_deductible');
        postedBucket = 'ins_claims';
        postedRow = addIndustryCustomRow('ins_claims', {
          id: recId, company: co, loss_date: dt, policy_no: strV('ik_policy_no') || 'POL-2026',
          insured: strV('ik_client') || 'Insured Client', carrier: strV('ik_carrier') || 'Allianz SNA',
          line: 'MOT · Motor', peril: strV('ik_peril') || 'Motor Collision Survey',
          adjuster: 'Rapid Response Desk', claimed_usd: clm, deductible_usd: ded,
          approved_usd: Math.max(0, clm - ded), paid_usd: 0, status: 'Under Survey'
        });
      }
    } else if (activeInd === 'Real Estate & Property') {
      const is4235 = /4235/.test(co);
      if (kMode === 'sales') {
        const net = numV('ik_net');
        const vat = is4235 ? round2(net * 0.11) : 0;
        const tot = round2(net + vat);
        postedBucket = 're_receipts';
        postedRow = addIndustryCustomRow('re_receipts', {
          id: recId, date: dt, company: co, property: strV('ik_property') || co,
          tenant: strV('ik_tenant') || 'Tenant', invoice_id: strV('ik_inv_ref') || 'INV-4235-010',
          amount_usd: tot, method: strV('ik_method') || 'Bank Wire (Fresh USD)',
          reference: recId, status: 'Cleared & Reconciled', audit_flag: 'Verified Kiosk Receipt'
        });
      } else if (kMode === 'raw') {
        const net = numV('ik_net');
        const vat = is4235 ? round2(net * 0.11) : 0;
        const tot = round2(net + vat);
        postedBucket = 're_leases';
        postedRow = addIndustryCustomRow('re_leases', {
          id: recId, company: co, property: strV('ik_property') || co,
          unit: strV('ik_unit') || 'Commercial Suite', tenant: strV('ik_tenant') || 'Tenant',
          start_date: dt, end_date: '2029-10-31', days_to_expiry: 1095,
          freq: strV('ik_freq') || 'Quarterly', vat_rate_pct: is4235 ? 11 : 0,
          net_period_usd: net, vat_period_usd: vat, period_ttc_usd: tot,
          annual_base_usd: net * 4, annual_vat_usd: vat * 4, annual_ttc_usd: tot * 4,
          deposit_usd: numV('ik_deposit'), escalation: '3-Yr Commercial', status: 'Active'
        });
      } else {
        postedBucket = 're_maintenance';
        postedRow = addIndustryCustomRow('re_maintenance', {
          id: recId, date: dt, company: co, property: strV('ik_property') || co,
          unit: strV('ik_unit') || 'Common Area', category: strV('ik_category') || 'Generator & Solar Plant',
          vendor: strV('ik_vendor') || 'MEP Contractor', budget_usd: numV('ik_budget'),
          actual_usd: numV('ik_actual'), recoverable: 'Landlord CAPEX', status: 'Completed'
        });
      }
    } else if (activeInd === 'Automotive & Heavy Trading') {
      if (kMode === 'sales') {
        const vin = strV('ik_vin');
        const qty = vin.length === 17 ? 1 : Math.max(1, Math.round(numV('ik_qty')));
        const up = numV('ik_price');
        const uc = numV('ik_cost');
        const ht = round2(qty * up);
        const vat = round2(ht * 0.11);
        const tot = round2(ht + vat);
        postedBucket = 'trd_sales';
        postedRow = addIndustryCustomRow('trd_sales', {
          id: recId, seqNo: 900, book: 'SHOWROOM', date: dt, company: co,
          stream: vin.length === 17 ? 'Serial Unit (VIN)' : 'Spare Parts',
          customer: strV('ik_customer') || 'Fleet Buyer', item: strV('ik_item') || 'Shacman X3000',
          vin: vin || '—', qty, ht_usd: ht, vat_usd: vat, ttc_usd: tot,
          cogs_usd: round2(qty * uc), margin_usd: round2(ht - qty * uc),
          paid_usd: tot, status: 'Delivered & Settled', is_gap: false
        });
      } else if (kMode === 'raw') {
        postedBucket = 'trd_grn';
        postedRow = addIndustryCustomRow('trd_grn', {
          id: recId, import_file: strV('ik_import') || 'IMP-SH-2026-015', date: dt, company: co,
          warehouse: strV('ik_wh') || 'Shacman Bonded Yard', supplier: strV('ik_supplier') || 'OEM Supplier',
          items_summary: `${Math.max(1, Math.round(numV('ik_qty')))} Units · B/L ${strV('ik_bl') || 'COSU'}`,
          landed_val_usd: numV('ik_val'), qc_status: 'Verified & Tally Signed'
        });
      } else {
        postedBucket = 'trd_warranty';
        postedRow = addIndustryCustomRow('trd_warranty', {
          id: recId, date: dt, company: co, chassis_vin: strV('ik_vin') || 'LZGJLDR44PX019288',
          model: strV('ik_model') || 'Shacman X3000', job_type: strV('ik_job_type') || '52-Point PDI',
          claim_status: strV('ik_status') || 'Cleared & Signed Off', cost_usd: numV('ik_cost'),
          technician: activeUser().full_name || 'Lead Tech'
        });
      }
    } else if (activeInd === 'Hospitality & Resorts') {
      if (kMode === 'sales') {
        const cat = strV('ik_category') || 'Chalet & Cabana Rental';
        const tot = numV('ik_tot');
        const isZeroVat = /tip|gratuities|diesel/i.test(cat);
        const ht = isZeroVat ? tot : round2(tot / 1.11);
        const vat = isZeroVat ? 0 : round2(tot - ht);
        postedBucket = 'hsp_revenue';
        postedRow = addIndustryCustomRow('hsp_revenue', {
          id: recId, date: dt, company: co, outlet: strV('ik_outlet') || 'Beach Deck & Cabanas',
          category: cat, rooms: 1, capacity: 4, covers: Math.max(1, Math.round(numV('ik_covers'))),
          ht_usd: ht, vat_usd: vat, ttc_usd: tot, method: strV('ik_method') || 'Cash & Card',
          notes: strV('ik_guest') || 'Venue desk closing'
        });
      } else if (kMode === 'raw') {
        const opn = numV('ik_open');
        const pur = numV('ik_purch');
        const use = Math.max(1, numV('ik_usage'));
        postedBucket = 'hsp_stock';
        postedRow = addIndustryCustomRow('hsp_stock', {
          id: recId, date: dt, company: co, store: strV('ik_store') || 'Main Commissary',
          item_group: strV('ik_group') || 'Seafood & Prime Cuts', opening_usd: opn,
          purchases_in_usd: pur, transfers_net_usd: 0, recipe_usage_usd: use,
          closing_usd: round2(opn + pur - use), r3_ratio: round2(pur / use),
          status: 'Optimal', notes: strV('ik_supplier') || 'Commissary intake'
        });
      } else {
        const hrs = Math.max(0.5, numV('ik_hours'));
        const dsl = numV('ik_diesel');
        const lph = round2(dsl / hrs);
        const rated = Math.max(1, numV('ik_rated'));
        postedBucket = 'hsp_energy';
        postedRow = addIndustryCustomRow('hsp_energy', {
          id: recId, date: dt, company: co, asset: strV('ik_asset') || 'Prime Generator #1',
          tank_level_l: numV('ik_tank'), refill_l: 0, run_hours: hrs, diesel_used_l: dsl,
          l_per_hr: lph, rated_l_hr: rated, kwh_gen: Math.round(dsl * 3.8),
          solar_offset_pct: numV('ik_solar'), status: lph > rated * 1.15 ? 'Burn Spike' : 'Normal Burn',
          notes: 'Kiosk utility telemetry'
        });
      }
    } else {
      // Holding & Treasury
      if (kMode === 'sales') {
        const toCo = strV('ik_to') || 'WTC';
        if (co === toCo) { showErr('Sender and Receiver sister entities must differ.'); return { ok: false }; }
        postedBucket = 'hld_interactions';
        postedRow = addIndustryCustomRow('hld_interactions', {
          id: recId, company: canonCompany(co) || co, date: dt, fromCo: co, toCo, initiatorCo: co, mirrorCo: toCo,
          side: 'Out', usd: numV('ik_usd'), cur: 'USD',
          method: strV('ik_method') || 'Bank Transfer',
          notes: strV('ik_notes') || 'Bilateral sister treasury clearing',
          bookMirror: Boolean($('ik_mirror') && $('ik_mirror').checked)
        });
      } else if (kMode === 'raw') {
        const prin = numV('ik_prin');
        const rep = Math.min(prin, numV('ik_rep'));
        postedBucket = 'hld_loans';
        postedRow = addIndustryCustomRow('hld_loans', {
          id: recId, date: dt, company: co, lender: strV('ik_lender') || 'Cedar Capital Partners Trust',
          type: strV('ik_type') || 'Term Credit Facility', principal_usd: prin,
          repaid_usd: rep, balance_usd: round2(prin - rep),
          status: prin - rep <= 0 ? 'Settled' : 'Active Facility'
        });
      } else {
        const pool = numV('ik_pool');
        const pct = numV('ik_pct');
        const ent = round2(pool * (pct / 100));
        const drw = Math.min(ent, numV('ik_drawn'));
        postedBucket = 'hld_partners';
        postedRow = addIndustryCustomRow('hld_partners', {
          id: recId, company: canonCompany(co) || co, entity: co, partner: strV('ik_partner') || 'Rami Haddad',
          pct, pool_usd: pool, entitled_usd: ent, drawn_usd: drw,
          open_usd: round2(ent - drw), start_date: dt,
          status: ent - drw <= 0 ? 'Settled' : 'Active Agreement'
        });
      }
    }

    const draftSlip = buildIndustryKioskThermalDraft(activeInd, kMode);
    let printResult = null;
    if (opts.print !== false && window.MFG_PRINT) {
      const priceMode = opts.priceMode || window.MFG_PRINT.SETTINGS.priceMode || 'priced';
      const paperWidth = opts.paperWidth || window.MFG_PRINT.SETTINGS.paperWidth || 80;
      printResult = await window.MFG_PRINT.printThermalTicket('sales', draftSlip, {
        priceMode,
        paperWidth,
        channel: opts.channel || window.MFG_PRINT.SETTINGS.channel,
        openModal: opts.openModal !== false
      });
    }
    toast(`Posted ${recId} to ${activeInd}`, 'ok');
    renderApp();
    return { ok: true, bucket: postedBucket, record: postedRow, printResult };
  }

  function buildDraftThermalRecordFromForm(calcRes) {
    const kMode = STATE.activeKiosk || 'sales';
    const activeInd = typeof getActiveIndustry === 'function' ? getActiveIndustry(STATE.company) : 'Manufacturing';
    if (activeInd !== 'Manufacturing' && kMode !== 'attendance') {
      return buildIndustryKioskThermalDraft(activeInd, kMode);
    }
    const company = val('f_company') || defaultEntryCompany();
    const date = val('f_date') || todayISO();
    const repDate = val('f_repdate') || date;
    const time = val('f_time') || new Date().toTimeString().slice(0, 5);
    const overtime = !!($('f_overtime') && $('f_overtime').checked);
    const notes = val('f_notes');
    const who = activeUser();

    if (kMode === 'raw') {
      const effCalc = calcRes || ($('f_qty') ? recalcRaw() : null);
      const qty = effCalc && effCalc.qty != null ? effCalc.qty : num('f_qty');
      const up = effCalc && effCalc.up != null ? effCalc.up : num('f_unitprice');
      const tp = effCalc && effCalc.tp != null ? effCalc.tp : num('f_transunitprice');
      const disc = effCalc && effCalc.disc != null ? effCalc.disc : num('f_discount');
      const uom = (effCalc && effCalc.uom) || val('f_uom') || 'm³';
      const isTruckUom = /truck/i.test(uom);
      const isCo = val('f_transportby') === 'Company fleet';
      const mat = (effCalc && effCalc.mat != null)
        ? round2(effCalc.mat)
        : ($('f_mat_total') && val('f_mat_total') !== '' ? num('f_mat_total') : round2(Math.max(0, (isTruckUom ? up : qty * up) - disc)));
      const tr = isCo
        ? 0
        : ((effCalc && effCalc.tr != null)
            ? round2(effCalc.tr)
            : ($('f_trans_total') && val('f_trans_total') !== '' ? num('f_trans_total') : round2(isTruckUom ? tp : qty * tp)));
      return {
        id: 'DRAFT-RAW',
        company,
        date,
        rep_date: repDate,
        time,
        overtime,
        ticket_no: val('f_ticketno') || nextTicketNo(company, [SEED.records.raw_purchases, STATE.customRecords.raw_purchases]) || '1001',
        product: val('f_product') || 'Raw Aggregate',
        site: val('f_site') || 'Site',
        site_owner: val('f_siteowner') || 'Site Owner',
        transport_by: val('f_transportby') || 'Company fleet',
        truck_owner: isCo ? company : (val('f_truckowner') || 'Hauler'),
        truck: val('f_truck') || '—',
        driver: val('f_driver') || '—',
        uom,
        qty,
        unit_cost: up,
        cost: mat,
        trans_unit_cost: tp,
        trans_cost: tr,
        discount: disc,
        total: round2(mat + tr),
        method: val('f_method') || 'Credit',
        entered_by: who.full_name,
        notes
      };
    }

    if (kMode === 'fuel') {
      if (STATE.kioskFuelSubmode === 'malfunction') {
        const discType = val('f_disctype') || 'Malfunction';
        const showUnit = /^(wash|leakage|damaged)/i.test(discType);
        const signed = round2(num('f_qty') || 0);
        const mCls = classifyMalfunctionItem(val('f_malf_item') || 'Diesel');
        const mUom = normalizeMalfUom(val('f_malf_uom') || mCls.uom || 'L');
        return {
          id: 'DRAFT-FUEL-MALF',
          company,
          date,
          rep_date: repDate,
          time,
          ticket_no: (showUnit && val('f_ticketno')) || 'MALF-VAR',
          fuel_type: discType,
          item: `${mCls.item} (${signed >= 0 ? 'Shortage -Stock' : 'Surplus +Stock'})`,
          equipment: (showUnit && val('f_truck')) || (mCls.isDiesel ? 'Main Plant Tank' : mCls.category),
          driver: (showUnit && val('f_driver')) || 'Variance Reconciliation',
          litres: signed,
          uom: mUom,
          location: mCls.isDiesel ? 'Main Plant Tank' : `${company} Warehouse`,
          entered_by: who.full_name,
          notes
        };
      }
      if (STATE.kioskFuelSubmode === 'refill') {
        const qty = num('f_qty') || 1000;
        const amt = num('f_amount') || 0;
        return {
          id: 'DRAFT-FUEL-REFILL',
          company,
          date,
          rep_date: repDate,
          time,
          ticket_no: val('f_reference') || 'TANK-REFILL',
          fuel_type: val('f_subcategory') || val('f_category') || 'Bulk Diesel Refill',
          item: `${val('f_category') || 'Fuel'} (${val('f_supplier') || 'Bulk Supplier'})`,
          equipment: val('f_truck') || 'Main Plant Tank',
          driver: val('f_supplier') || 'Tanker Delivery',
          litres: qty,
          location: 'Main Plant Tank',
          amount: amt,
          unit_cost: qty > 0 ? round2(amt / qty) : 0,
          entered_by: who.full_name,
          notes
        };
      }
      const eqDraftName = val('f_truck');
      const mType = val('f_metertype') || (eqDraftName ? equipMeterSpec(eqDraftName, company).type : 'odometer');
      const mVal = val('f_meter') ? num('f_meter') : null;
      const fType = val('f_fueltype') || 'Diesel';
      return {
        id: 'DRAFT-FUEL',
        company,
        date,
        rep_date: repDate,
        time,
        ticket_no: val('f_ticketno') || 'PUMP-01',
        fuel_type: fType,
        item: fType === 'Lubricant' ? (val('f_item') || 'Oil 15W40') : fType,
        equipment: val('f_truck') || 'Select Equipment',
        driver: val('f_driver') || '—',
        litres: num('f_qty') || 0,
        odometer: mType === 'odometer' ? mVal : null,
        hours: mType === 'hours' ? mVal : null,
        meter_delta: calcRes && calcRes.delta != null ? calcRes.delta : null,
        entered_by: who.full_name,
        notes
      };
    }

    // Default: Sales Dispatch Kiosk
    const effCalc = calcRes || ($('f_qty') ? recalcSales() : null);
    const qty = effCalc && effCalc.qty != null ? effCalc.qty : num('f_qty');
    const up = effCalc && effCalc.up != null ? effCalc.up : num('f_unitprice');
    const tp = effCalc && effCalc.tp != null ? effCalc.tp : num('f_transunitprice');
    const disc = effCalc && effCalc.disc != null ? effCalc.disc : num('f_discount');
    const uom = (effCalc && effCalc.uom) || val('f_uom') || 'm³';
    const saleType = (effCalc && effCalc.saleType) || val('f_saletype') || 'Delivery';
    const isTruckUom = /truck/i.test(uom);
    const mat = (effCalc && effCalc.mat != null)
      ? round2(Math.max(0, effCalc.mat - disc))
      : ($('f_mat_total') && val('f_mat_total') !== '' ? num('f_mat_total') : round2(Math.max(0, (isTruckUom ? up : qty * up) - disc)));
    const tr = saleType === 'Delivery'
      ? ((effCalc && effCalc.tr != null)
          ? round2(effCalc.tr)
          : ($('f_trans_total') && val('f_trans_total') !== '' ? num('f_trans_total') : round2(isTruckUom ? tp : qty * tp)))
      : 0;
    const net = round2(mat + tr);
    const cust = val('f_customer') || 'Walk-In / Customer';
    const ci = customerInfo(cust);
    const vatReg = !!(ci && (ci['VAT Registered'] === 'Yes' || ci.vat_registered));
    const vat = vatReg ? round2(net * getVatFraction(val('f_date') || todayISO())) : 0;
    const ttc = round2(net + vat);
    return {
      id: 'DRAFT-SALES',
      company,
      date,
      rep_date: repDate,
      time,
      overtime,
      ticket_no: val('f_ticketno') || nextTicketNo(company, [SEED.records.sales_tickets, STATE.customRecords.sales_tickets]) || '5001',
      sale_type: saleType,
      transport_by: val('f_transportby') || 'Company fleet',
      customer: cust,
      product: val('f_product') || 'Select Product',
      site: saleType === 'Delivery' ? (val('f_site') || 'Destination Site') : 'Plant Pickup',
      truck_owner: val('f_transportby') === 'Company fleet' ? company : (val('f_truckowner') || ''),
      truck: val('f_truck') || '—',
      driver: saleType === 'Delivery' ? (val('f_driver') || '—') : '',
      uom,
      qty,
      unit_price: up,
      price: mat,
      trans_unit_price: tp,
      trans_price: tr,
      discount: disc,
      total: net,
      vat,
      total_ttc: ttc,
      method: val('f_method') || 'Credit',
      vat_invoice: vatReg ? val('f_vatinvoice') : '',
      entered_by: who.full_name,
      notes
    };
  }

  function updateKioskLiveThermalPreview(calcRes) {
    const previewWrap = $('kioskLiveThermalPreview');
    if (!previewWrap || !window.MFG_PRINT) return;
    const docType = STATE.activeKiosk === 'raw' ? 'raw' : (STATE.activeKiosk === 'fuel' ? 'fuel' : 'sales');
    const paperWidth = window.MFG_PRINT.SETTINGS.paperWidth || 80;
    const priceMode = window.MFG_PRINT.SETTINGS.priceMode || 'priced';
    const draft = buildDraftThermalRecordFromForm(calcRes);
    previewWrap.innerHTML = window.MFG_PRINT.renderThermalTicketHtml(draft, { docType, paperWidth, priceMode });
    const metaEl = $('kioskEscPosByteMeta');
    if (metaEl) {
      const bytes = window.MFG_PRINT.buildEscPosBytes(draft, { docType, paperWidth, priceMode });
      metaEl.textContent = `ESC/POS Stream Ready · ${bytes.length.toLocaleString()} bytes · ${paperWidth}mm (${paperWidth === 58 ? '32 cols' : '48 cols'}) · ${priceMode === 'unpriced' ? 'UNPRICED GATE PASS' : 'PRICED VOUCHER'}`;
    }
  }

  async function saveKioskEntry(opts = {}) {
    if (STATE.saving) return { ok: false, reason: 'saving' };
    const activeInd = typeof getActiveIndustry === 'function' ? getActiveIndustry(STATE.company) : 'Manufacturing';
    if (activeInd !== 'Manufacturing' && STATE.activeKiosk !== 'attendance') {
      return saveIndustryKioskEntry(opts);
    }
    const formType = resolveKioskFormType();
    STATE.modalForm = formType;
    if (!canEnterForm(formType)) {
      toast('Your seat cannot post this kiosk entry', 'err');
      return { ok: false, reason: 'permission' };
    }
    if (STATE.modalForm === 'expense' && !STATE.editingPendingExpenseId) {
      const qcDrawerNow = $('expQuickCatalogDrawer');
      if (qcDrawerNow && !qcDrawerNow.hidden && val('exp_qc_name') && typeof FORM_UI.commitQuickCatalogItem === 'function') {
        const qcOk = await FORM_UI.commitQuickCatalogItem({ deferServerPost: true });
        if (!qcOk) return { ok: false, reason: 'catalog_item' };
      }
    }
    const mfgFormHost = $('kioskFormBody');
    if (mfgFormHost && typeof flushKioskPartyTypoGuard === 'function' && !flushKioskPartyTypoGuard(mfgFormHost)) {
      return { ok: false, reason: 'party_typo' };
    }
    cancelNearCopyLiveCheck();
    const { errors, fieldErrors, record, crKey, pendingCatalogAdds } = validateAndBuild({ deferCatalogAdds: true });
    if (errors.length) {
      FORM_UI.postAttempted = true;
      recalcForm(true);
      syncFormValidationUI(fieldErrors, true);
      return { ok: false, errors, fieldErrors };
    }
    FORM_UI.postAttempted = false;
    syncFormValidationUI([], false);

    STATE.saving = true;
    const btnPrint = $('kioskPostAndPrintBtn');
    const btnPost = $('kioskPostOnlyBtn');
    const origPrintText = btnPrint ? btnPrint.textContent : 'Post & Print';
    const origPostText = btnPost ? btnPost.textContent : 'Post Only';
    if (btnPrint) { btnPrint.disabled = true; btnPrint.textContent = 'Posting & Printing…'; }
    if (btnPost) { btnPost.disabled = true; }
    try {
      const stagedExpenseItems = Array.isArray(record._staged_expense_items) ? record._staged_expense_items : [];
      const assignSiteReg = record._assign_site_region;
      const groupTransferMirror = record._group_transfer_mirror;
      delete record._group_transfer_mirror;
      delete record._backpay_lines;
      delete record._staged_expense_items;
      delete record._staged_repair_items;
      delete record._post_as_paired_return;
      delete record._pair_ow_km;
      delete record._pair_rt_km;
      delete record._assign_site_region;
      record.modified_at = record.modified_at || new Date().toISOString();

      const kioskRollbackTables = [];
      if (assignSiteReg) {
        kioskRollbackTables.push('sites', 'regions', 'jv_partnerships', 'price_rules', 'customers', 'suppliers');
      }
      if (crKey === 'expenses' || crKey === 'items' || crKey === 'warehouse_movements' || (Array.isArray(pendingCatalogAdds) && pendingCatalogAdds.length)) {
        kioskRollbackTables.push('items', 'expense_items');
      }
      if (groupTransferMirror) kioskRollbackTables.push('expenses');
      const kioskRollbackSnap = (hasServerApi() && !isDemoScopeActive())
        ? _captureLedgerAndGeoRollbackSnap(kioskRollbackTables, Boolean(assignSiteReg))
        : null;
      if (kioskRollbackSnap) {
        kioskRollbackSnap.snapSeedRow(crKey, record.id);
        if (crKey === 'sales_tickets' && record.origin_ticket_id) {
          kioskRollbackSnap.snapSeedRow('sales_tickets', record.origin_ticket_id);
        }
      }

      const newlyCreatedCatItems = _materializePendingCatalogAdds(pendingCatalogAdds);
      const kioskExtraPosts = [];
      if (assignSiteReg && assignSiteReg.site && assignSiteReg.region) {
        ensureSiteHasRegion(assignSiteReg.site, assignSiteReg.region, assignSiteReg.supplier, kioskExtraPosts);
      }
      if (!Array.isArray(STATE.customRecords[crKey])) STATE.customRecords[crKey] = [];
      STATE.customRecords[crKey].unshift(record);
      if (groupTransferMirror && crKey === 'sales_tickets') {
        groupTransferMirror.modified_at = record.modified_at;
        if (!Array.isArray(STATE.customRecords.expenses)) STATE.customRecords.expenses = [];
        STATE.customRecords.expenses.unshift(groupTransferMirror);
        kioskExtraPosts.push(['expenses', groupTransferMirror]);
      }
      if (crKey === 'sales_tickets') {
        applyOriginPriorDisposition(record, kioskExtraPosts);
      }
      _stageExpenseAndCatalogPosts(crKey, record, newlyCreatedCatItems, stagedExpenseItems, kioskExtraPosts);
      stampBatchModifiedAt(kioskExtraPosts, crKey, record);
      applyCustomRecordsToSeed();
      saveLocalAuthAndRecords();

      const mainPostRes = await postRecordToLocalApi(crKey, record, { deferRender: true });
      if ((mainPostRes && mainPostRes.blockedSameName) || isServerRejectRes(mainPostRes)) {
        const rejectMsg = await extractServerRejectMsg(mainPostRes, 'Save was rejected by the server.');
        if (kioskRollbackSnap) kioskRollbackSnap.restore(rejectMsg);
        else { toast(rejectMsg, 'err'); renderApp(); }
        return { ok: false, reason: 'server_reject', error: rejectMsg };
      }
      let extraPostRes = { ok: true, postedResults: [] };
      if (mainPostRes && mainPostRes.shellOutdated) {
        enqueuePending426Pairs(kioskExtraPosts);
        setPendingCloudPush(true);
      } else if (kioskExtraPosts.length) {
        extraPostRes = await postRecordPairsChunked(kioskExtraPosts, 8, { deferRender: true });
      }
      if ((extraPostRes && extraPostRes.blockedSameName) || isServerRejectRes(extraPostRes)) {
        await rollbackRecordListOnServer(extraPostRes && extraPostRes.postedResults);
        const rbOk = await rollbackRecordOnServer(mainPostRes);
        if (!rbOk && canVoid()) {
          await postRecordToLocalApi(crKey, Object.assign({}, record, { voided: true, void_reason: 'Rolled back after peer save rejection', modified_at: nextMonotonicIso(), modified_by: activeUser().email }), { deferRender: true }).catch(() => null);
        }
        const rejectMsg = await extractServerRejectMsg(extraPostRes, 'Save was rejected by the server.');
        if (kioskRollbackSnap) kioskRollbackSnap.restore(rejectMsg);
        else { toast(rejectMsg, 'err'); renderApp(); }
        return { ok: false, reason: 'server_reject', error: rejectMsg };
      }
      FORM_UI.pendingQuickCatMeta = {};

      const malfHit = crKey === 'fuel_malfunctions' ? getMalfunctionSaveWatchdogHit(record) : null;
      if (malfHit) {
        toast(`✓ Kiosk ${CR_LABEL[crKey] || 'entry'} posted · ⚠️ High Diesel Malfunction Alert (${malfHit.scopeLbl}): ${malfHit.hit.malfunctionPct.toFixed(1)}% of company diesel used`, 'warn');
      } else {
        toast(`✓ Kiosk ${CR_LABEL[crKey] || 'entry'} posted · ${record.name}`, 'ok');
      }

      let printResult = null;
      const shouldPrint = opts.print !== false;
      if (shouldPrint && window.MFG_PRINT) {
        const docType = STATE.activeKiosk === 'raw' ? 'raw' : (STATE.activeKiosk === 'fuel' ? 'fuel' : 'sales');
        const priceMode = opts.priceMode || window.MFG_PRINT.SETTINGS.priceMode || 'priced';
        const paperWidth = opts.paperWidth || window.MFG_PRINT.SETTINGS.paperWidth || 80;
        printResult = await window.MFG_PRINT.printThermalTicket(record, {
          docType,
          priceMode,
          paperWidth,
          channel: opts.channel || window.MFG_PRINT.SETTINGS.channel
        });
      }
      renderApp();
      syncWithCloud(true);
      return { ok: true, record, crKey, printResult };
    } finally {
      STATE.saving = false;
      if (btnPrint) { btnPrint.disabled = false; btnPrint.textContent = origPrintText; }
      if (btnPost) { btnPost.disabled = false; btnPost.textContent = origPostText; }
    }
  }

